INSERT INTO spells (id, name, school, subschool, descriptor, level, type, class_lists, casting_time, range, target, area, effect, duration, saving_throw, spell_resistance, description, material, arcane_focus, divine_focus, costly_components)
VALUES
  ('countless_eyes', 'Countless Eyes', 'transmutation', NULL, NULL, 3, 'both', 'alchemist 3, bloodrager 3, inquisitor 3, occultist 3, psychic 3, sorcerer/wizard 3, witch 3', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 hour/level', 'Will negates (harmless); Spell resistance yes (harmless)', NULL, 'The target sprouts extra eyes all over its body, including on the back of its head. It gains all-around vision and cannot be flanked.', NULL, NULL, false, false),
  ('covetous_aura', 'Covetous Aura', 'abjuration', NULL, NULL, 5, 'arcane', 'bard 5, sorcerer/wizard 5', '1 standard action', 'personal', NULL, '25-ft.-radius emanation centered on you', NULL, '1 round/level or until discharged', 'none', 'no', 'Anytime a harmless (so noted by a spell’s saving throw description) spell of 3rd level or lower is cast within a covetous aura’s area of effect, you may choose to immediately gain the benefit of that spell as if it had also targeted you. The intended target still gains the effect of the spell. You gain the benefits of this duplicated spell only if the caster is in range of the covetous aura. You are considered the caster of the additional spell effect. If the effect allows for multiple targets other than yourself, you cannot use the stolen spell effect to target other creatures—a covetous aura only aids you. Once you choose to gain the benefit of another spell, the covetous aura immediately ends. Rumors hold that this unusual spell was invented thousands of years ago by a powerful spellcaster who was constantly jealous of other spellcasters’ abilities.', NULL, NULL, false, false),
  ('covetous_urge', 'Covetous Urge', 'enchantment', 'compulsion', 'curse, language-dependent', 2, 'arcane', 'arcanist 2, bard 2, skald 2, sorcerer/wizard 2, summoner 2, summoner (unchained) 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one living creature with 7 HD or fewer', NULL, NULL, '1 minute/level (D)', 'Will negates', 'yes', 'You curse the target with insatiable greed, causing it to attempt to steal any item worth 100 gp or more that it can see, each time it enters a new room or area. If it can see multiple items of value in a single room or area, it attempts to steal the item it thinks is worth the most. This covetous compulsion might cause the target to act recklessly where it normally would not (unless acting in this manner would clearly cause it to die, suffer great harm, or get caught).', 'a golden coin', NULL, false, false),
  ('coward_s_cowl', 'Coward’s Cowl', 'enchantment', NULL, 'mind-affecting', 1, 'both', 'alchemist 1, bard 1, cleric 1, mesmerist 1, psychic 1, shaman 1, sorcerer/wizard 1, witch 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 minute/level', 'Will negates (harmless)', 'no', 'You imbue the target with a compulsion to avoid threats, enhancing its defensive instincts.', NULL, NULL, false, false),
  ('coward_s_lament', 'Coward’s Lament', 'enchantment', 'compulsion', 'mind-affecting', 4, 'divine', 'inquisitor 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 round/level (D)', 'Will partial', 'yes', 'You compel an opponent to face you in combat, or suffer for its cowardice. Each round that the target fails to attack you in melee, it receives a cumulative -1 penalty to its Armor Class, attack rolls, and saving throws (maximum penalty -5). Each round at the end of its turn, the target may attempt a Will Saving Throw to prevent the penalties from increasing for that round. All penalties reset to zero when the target attacks you in melee, but increase again if it stops attacking. If the target is prevented from attacking you by physical restraint, magic, or impassable terrain, the penalties do not increase. If you move away from the target, the spell ends.', NULL, NULL, true, false),
  ('crafter_s_curse', 'Crafter’s Curse', 'transmutation', NULL, 'curse', 1, 'arcane', 'sorcerer/wizard 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 day/level (D)', 'Will negates', 'yes', 'The target of crafter’s curse takes a -5 penalty on all Craft skill checks while the spell lasts.', 'a broken tool', NULL, false, false),
  ('crafter_s_fortune', 'Crafter’s Fortune', 'transmutation', NULL, NULL, 1, 'arcane', 'alchemist 1, sorcerer/wizard 1; Domains [subdomains] Artifice [industry]', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 day/level or until discharged (D)', 'Will negates (harmless)', 'yes (harmless)', 'The target is struck by inspiration and gains a +5 luck bonus on its next Craft skill check.', NULL, 'a tool', false, false),
  ('crafter_s_nightmare', 'Crafter’s Nightmare', 'necromancy', 'haunted', 'emotion, fear, mind-affecting', 1, 'both', 'bard 2, druid 2, medium 1, mesmerist 2, occultist 2, psychic 2, sorcerer/wizard 2, spiritualist 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, 'one 5-ft. cube/level (S)', NULL, '1 day/level (D)', 'Will negates', 'yes', 'You concentrate feelings of competitiveness, envy, and ill will into a poltergeist-like haunt that wreaks havoc on its victim’s long-term endeavors. Every time a creature in the affected area attempts a Craft or Profession check to generate income, create an item, or earn capital, any skill check required for crafting or repairing a magic item, or any skill check required for an occult ritual, the haunt imposes a –5 penalty on the check. If the creature fails its check by 5 or more, the haunt’s mischief deals 1d6 points of damage to the creature in addition to any other negative effects from such a failure. If the creature attempts to cast a spell with a casting time of 1 minute or longer, the haunt becomes similarly disruptive, requiring the caster to succeed at a concentration check (DC = 15 + spell level) or lose the spell and take 1d6 points of damage from the mischief. Each time the haunt is disruptive, the spell’s haunt-like manifestation occurs during that round.', 'a broken tool', NULL, false, false),
  ('create_armaments', 'Create Armaments', 'conjuration', 'creation', NULL, 3, 'arcane', 'bard 4, medium 4, psychic 4, sorcerer/wizard 4, spiritualist 3, witch 4', '1 minute', '0 ft.', NULL, NULL, 'one non-magical weapon, shield, or set of armor', 'instantaneous', 'none', 'no', 'You create one non-magical weapon, shield, or set of armor. To determine whether the item functions as intended, you must attempt an appropriate Craft check with the DC required to create the item normally. If you fail, the item is created with the broken condition. You can create items made of rare or unusual materials if you include a bit of that material as an additional material component when you cast the spell, but cannot create cold iron items with this spell.', 'diamonds worth price of arms to be created', NULL, false, true),
  ('create_demiplane', 'Create Demiplane', 'conjuration', 'creation', NULL, 5, 'both', 'cleric/oracle 7, sorcerer/wizard 7, summoner 5, unchained summoner 6, witch 7', '2 hours', '0 ft.', NULL, NULL, 'extradimensional demiplane, up to three 10-ft. cubes/level (S)', '1 day/level', 'none; Spell resistance no', NULL, 'You create a small, finite demiplane. You must be on the Astral or Ethereal Plane or on a plane that has access to one of those planes (such as the Material Plane) to cast this spell. When you cast the spell, you decide whether the demiplane is within the Astral or the Ethereal Plane. It is filled with air or water (decided by you). The plane is generally flat and featureless, such as an earth, stone, water, or wood floor. The “walls” and “ceiling” of the plane may appear like solid earth, stone, wood, or water, or they may end in mist, a featureless void, or a similar unreal-looking border. The plane’s environmental conditions are those of a temperate spring day on the Material Plane. You determine the plane’s light level (bright, normal, dim, or darkness), which affects the entire plane.', NULL, 'a forked metal rod worth at least 500 gp', false, true),
  ('create_drug', 'Create Drug', 'conjuration', 'creation', NULL, 3, 'both', 'alchemist 3, cleric 4, druid 3, occultist 3', '1 round', '0 ft.', NULL, NULL, '1 dose of a drug/3 levels', '1 minute', 'none (see below)', 'no', 'The caster conjures into being one of the following drugs: aether, flayleaf, opium, keif, scour, shiver, or zerk. (At the GM’s discretion, other drugs of similar power can be included on this list.) The drug doses the caster creates with this spell must be used within 1 minute of being conjured, or they dissolve into worthless dust or evaporate into noxious but fleeting vapors, though the effects of the drug may last far longer if taken before it decays.', NULL, NULL, false, false),
  ('create_food_and_water', 'Create Food and Water', 'conjuration', 'creation', NULL, 3, 'divine', 'cleric/oracle 3, shaman 3; Subdomain family 3', '10 minutes', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'food and water to sustain three humans or one horse/level for 24 hours', '24 hours; see text', 'none', 'no', 'The food that this spell creates is simple fare of your choice–highly nourishing, if rather bland. Food so created decays and becomes inedible after 24 hours, although it can be kept fresh for another 24 hours by casting a purify food and drink spell on it. The water created by this spell is just like clean rain water, and it doesn’t go bad as the food does.', NULL, NULL, false, false),
  ('create_holds', 'Create Holds', 'transmutation', NULL, NULL, 3, 'both', 'druid 4, ranger 3, sorcerer/wizard 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'path of handholds', '1 hour/level (D)', 'none', 'no', 'You create a path of handholds on earthen, plaster, stone, or wooden walls.', 'handful of pebbles', NULL, false, false),
  ('create_mindscape', 'Create Mindscape', 'illusion )', 'phantasm', 'mind-affecting', 4, 'arcane', 'medium 4, mesmerist 4, psychic 4, sorcerer/wizard 5', '1 round', 'long (400 ft. + 40 ft./level)', 'one creature', NULL, NULL, '10 minutes/level', 'Will disbelief; see text', 'yes', 'You create an immersive mindscape that the minds of both you and another creature enter together.', NULL, NULL, false, false),
  ('create_pit', 'Create Pit', 'conjuration', 'creation', NULL, 2, 'arcane', 'sorcerer/wizard 2, summoner/unchained summoner 2; Subdomain caves 2; Elemental School earth 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, '10-ft.-by-10-ft. hole, 10 ft. deep/2 levels', '1 round + 1 round/level', 'Reflex negates', 'no', 'You create a 10-foot-by-10-foot extra-dimensional hole with a depth of 10 feet per two caster levels (maximum 30 feet). You must create the pit on a horizontal surface of sufficient size. Since it extends into another dimension, the pit has no weight and does not otherwise displace the original underlying material. You can create the pit in the deck of a ship as easily as in a dungeon floor or the ground of a forest. Any creature standing in the area where you first conjured the pit must make a Reflex saving throw to jump to safety in the nearest open space. In addition, the edges of the pit are sloped, and any creature ending its turn on a square adjacent to the pit must make a Reflex saving throw with a +2 bonus to avoid falling into it. Creatures subjected to an effect intended to push them into the pit (such as bull rush) do not get a saving throw to avoid falling in if they are affected by the pushing effect.', NULL, 'miniature shovel costing 10 gp', false, true),
  ('create_soul_gem', 'Create Soul Gem', 'necromancy', NULL, 'death, evil', 3, 'both', 'cleric 3, occultist 3, shaman 3, sorcerer/wizard 3, spiritualist 3, witch 3', '1 round', 'close (25 ft. + 5 ft./2 levels)', 'one dying or recently dead creature', NULL, NULL, '1 day/level', 'Will negates', 'yes', 'You draw forth the ebbing life force of a dying creature or one that has died in the past round, focusing it through a crystal lens focus to transform into a soul gem. If the creature is alive and fails its saving throw, it dies and you capture its soul in the gem. If the creature is dead, it can still resist the spell effect by attempting a Will save as if it were still alive. The value of the soul gem created depends on the nature of the creature it is made from. Soul gems created by this spell crumble to dust once the spell’s duration expires, releasing the trapped soul to travel on to judgment in the Great Beyond.', NULL, 'crystal lens worth 500 gp', false, true),
  ('create_treasure_map', 'Create Treasure Map', 'divination', NULL, NULL, 2, 'both', 'bard 2, druid 3, psychic 2, ranger 2, sorcerer/wizard 2', '1 hour', 'touch', NULL, NULL, NULL, 'instantaneous', 'none', 'no', 'You can take a piece from a dead creature’s body and use it to create a map that reveals the locations of any valuables that creature knew about while still alive. You must cut this piece off yourself and the creature cannot have died more than 24 hours prior to the casting of this spell. You cannot cast this spell on a creature without a physical body, and the portion you remove must have a fairly level surface such as a piece of hide, carapace, or skin. The map you create is accurate to the best knowledge the creature had at the time of its death. It reveals the location of one source of treasure for every three caster levels you possess.', 'powdered metal and rare inks worth 100 gp', NULL, false, true),
  ('create_undead', 'Create Undead', 'necromancy', NULL, 'evil', 5, 'both', 'cleric/oracle 6, shaman 6, sorcerer/wizard 6; Domain death 6, evil 6; Mystery juju(PAP39/PZO9039) 5', '1 hour', 'close (25 ft. + 5 ft./2 levels)', 'one corpse', NULL, NULL, 'instantaneous', 'none', 'no', 'A much more potent spell than animate dead, this evil spell allows you to infuse a dead body with negative energy to create more powerful sorts of undead: ghouls, ghasts, mummies, and mohrgs. The type or types of undead you can create are based on your caster level, as shown on the table below.', 'a clay pot filled with grave dirt and an onyx gem worth at least 50 gp per HD of the undead to be created', NULL, false, true),
  ('create_variant_mummy', 'Create Variant Mummy', 'necromancy', NULL, 'evil', 7, 'both', 'arcanist 7, cleric/oracle 7, sorcerer/wizard 7', '1 hour', 'close (25 ft. + 5 ft./2 levels)', '1 corpse steeped in a peat bog for at least 24 hours', NULL, NULL, 'instantaneous', 'none', 'no', 'This spell functions as create undead, except it creates one of the following variant mummies: bog mummy, ice mummy, or Tomb Guardian mummy', 'onyx gems worth 50 gp per HD of the undead to be created', NULL, false, true),
  ('create_water', 'Create Water', 'conjuration', 'creation', 'water', 0, 'divine', 'cleric/oracle 0, druid 0, inquisitor 0, paladin 1, shaman 0', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'up to 2 gallons of water/level', 'instantaneous', 'none', 'no', 'This spell generates wholesome, drinkable water, just like clean rain water. Water can be created in an area as small as will actually contain the liquid, or in an area three times as large — possibly creating a downpour or filling many small receptacles. This water disappears after 1 day if not consumed.', NULL, NULL, false, false),
  ('creeping_doom', 'Creeping Doom', 'conjuration', 'summoning', NULL, 5, 'both', 'druid 7, shaman 7, summoner 5, unchained summoner 6; Domain [subdomain] Jungle 7, Scalykind 7; Mystery juju(PAP39/PZO9039) 7, nature 7', '1 standard action', 'close (25 ft. + 5 ft./2 levels)/100 ft.; see text', NULL, NULL, NULL, '1 round/level', 'Fortitude partial, see text', 'no', 'This spell summons four massive swarms of biting and stinging insects. These swarms appear adjacent to one another, but can be directed to move independently. Treat these swarms as centipede swarms with the following adjustments. The swarms have 60 hit points each and deal 4d6 points of damage with their swarm attack. The save to resist their poison and distraction effects is equal to the save DC of this spell. Creatures caught in multiple swarms only take damage and make saves once.', NULL, NULL, false, false),
  ('creeping_ice', 'Creeping Ice', 'evocation', NULL, 'cold', 3, 'both', 'druid 4, sorcerer/wizard 4, summoner 3, unchained summoner 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'anchored plane of ice, up to one 10-ft. square/level', '10 minutes/level', 'Reflex negates (see text)', 'yes', 'This spell covers the floor, the ground, or some other calm horizontal surface (such as a placid lake or a gentle river) with a sheet of slowly growing ice. The initial sheet of ice cannot form in an area occupied by physical objects or creatures. Its surface must be smooth and unbroken when created. The ice is hard, strong, and opaque, and is 1 inch thick per caster level. The ice is strong enough to support the weight of a typical horse, making it possible for creatures to cross a body of water.', NULL, NULL, false, false),
  ('crime_of_opportunity', 'Crime of Opportunity', 'enchantment', 'compulsion', 'mind-affecting', 1, 'divine', 'antipaladin 1, mesmerist 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round', 'Will negates', 'yes', 'You awaken a sudden criminal impulse in the target, compelling it to commit a criminal act as if affected by the crime wave spell.', 'a slit purse', NULL, false, false),
  ('crime_wave', 'Crime Wave', 'enchantment', 'compulsion', 'mind-affecting', 4, 'both', 'antipaladin 4, bard 5, mesmerist 5, psychic 7, sorcerer/wizard 7', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one creature/level, no two of which can be more than 30 ft. apart', NULL, NULL, '1 round/level (D)', 'Will negates', 'yes', 'You instill overwhelming avarice in the targets and impel them toward a wild spree of larceny. Creatures affected by a crime wave must roll percentile dice each round to determine what action they take.', 'a tarnished coin', NULL, false, false),
  ('crimson_breath', 'Crimson Breath', 'transmutation', NULL, NULL, 4, 'both', 'alchemist 4, cleric 4, druid 4, sorcerer/wizard 4, witch 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'instantaneous', 'Fort negates', 'no', 'When you cast this spell, your salivary glands transform and instantly fill with potent venom.', NULL, NULL, false, false),
  ('crimson_confession', 'Crimson Confession', 'abjuration', NULL, NULL, 2, 'arcane', 'psychic 2, sorcerer/wizard 2, witch 2', '10 minutes', 'touch', 'or', 'object touched or up to 1 sq. ft.', NULL, 'permanent and 1 hour/level (see text)', 'Fort negates', 'yes', 'You ward an object or an area with your personal rune or mark. You can choose for the writing to be visible or invisible, and it doesn’t harm the material upon which it is placed. A detect magic spell causes an invisible mark to glow and be visible. If any creature other than you touches the warded object or area and fails a Fortitude save, its skin turns bright red for 1 hour per level. This coloring cannot be washed away, but it can be dispelled.', NULL, NULL, false, false),
  ('crown_of_glory', 'Crown of Glory', 'evocation', NULL, NULL, 8, 'arcane', 'glory 8', '1 full round', 'personal', NULL, NULL, NULL, '1 minute/level', 'Will negates', 'yes', 'You gain a +4 enhancement bonus to Charisma. All creatures with fewer than 8 HD are compelled to stop and pay attention to you. Any such creature that wants to take hostile action against you must make a Will save to do so. Any creature that fails this saving throw the first time it attempts a hostile action is enthralled for the duration of the spell (as the enthrall spell), as long as it is in the spell’s area. It does not try to leave the area on its own. Creatures with 8 HD or more are not affected.', 'opal worth at least 200 gp', NULL, true, true),
  ('cruel_jaunt', 'Cruel Jaunt', 'conjuration', 'teleportation', 'evil, fear, mind-affecting', 4, 'both', 'antipaladin 4, cleric 6, inquisitor 6, magus 6, psychic 6, shaman 6, sorcerer/wizard 6, witch 6', '1 standard action', 'medium (100 feet + 10 ft./level)', 'you', NULL, NULL, '1 round/level (D)', 'none', 'no', 'You gain the ability to detect fear, as per sense fear, but you sense creatures within medium range.', 'a dilated human eyeball', NULL, true, false),
  ('crusader_s_edge', 'Crusader’s Edge', 'transmutation', NULL, 'good', 4, 'divine', 'cleric 4, inquisitor 4, paladin 4', '1 standard action', 'touch', 'melee weapon touched', NULL, NULL, '1 minute/level', 'Fort negates', 'no', 'When you cast this spell on a melee weapon you imbue it with a powerful holy energy, granting the weapon the bane weapon quality against evil outsiders. Furthermore, whenever you score a successful critical hit against an outsider with the evil subtype, you not only deal normal critical damage with the weapon but also nauseate the outsider for 1d3 rounds—the outsider can reduce this nauseated condition to sickened for 1 round with a successful Fortitude save.', 'dried blood from an evil outsider, sprinkled on the weapon', NULL, false, false),
  ('crushing_despair', 'Crushing Despair', 'enchantment', 'compulsion', 'emotion, mind-affecting', 3, 'arcane', 'bard 3, bloodrager 4, sorcerer/wizard 4, witch 4; Subdomain isolation 4', '1 standard action', '30 ft.', NULL, 'cone-shaped burst', NULL, '1 min./level', 'Will negates', 'yes', 'An invisible cone of despair causes great sadness in the subjects. Each affected creature takes a -2 penalty on attack rolls, saving throws, ability checks, skill checks, and weapon damage rolls.', NULL, NULL, false, false),
  ('crushing_hand', 'Crushing Hand', 'evocation', NULL, 'force', 9, 'arcane', 'sorcerer/wizard 9; Domain strength 9', '1 standard action', 'Medium (100 ft. + 10 ft./level)', '10′ Hand', NULL, NULL, 'round/level (D)', 'none', 'yes', 'This spell functions as interposing hand, except that it can also grapple one opponent as grasping hand. Its CMB and CMD for grapple checks use your caster level in place of its base attack bonus, with a +12 bonus for its Strength score (35) and a +1 bonus for being Large (its Dexterity is 10, granting no bonus to the CMD). A crushing hand deals 2d6+12 points of damage on each successful grapple check against an opponent. The crushing hand can instead be directed to bull rush a target (as forceful hand), using the same bonuses outlined above, or it can be directed to interpose itself, as interposing hand does.', NULL, 'a soft glove', false, false),
  ('cultural_adaptation', 'Cultural Adaptation', 'divination', NULL, NULL, 1, 'both', 'bard 1, cleric 1, medium 1, occultist 1, psychic 1, sorcerer/wizard 1', '1 standard action', 'personal', 'you', NULL, NULL, '10 minutes/level', NULL, NULL, 'When casting this spell, you must concentrate on a culture or subculture to which you wish to adapt. If you speak the native language of the culture in question, then for the duration of this spell, you speak the language with a native accent. The spell doesn’t teach you the language in question, but can be combined with tongues or a similar spell. Your body language and gestures mark you as a native of the culture, and you unconsciously make small decisions that help you blend in. Combined, these grant you a +2 circumstance bonus on Diplomacy checks to influence members of the culture to which you have adapted, which doesn’t stack with other circumstance bonuses you might possess by virtue of being a member of the chosen culture. You also gain a +2 circumstance bonus on Disguise checks to pass yourself off as if you were a member of the culture, if you are not.', 'a document written in the language of the culture to be emulated', NULL, true, false),
  ('cup_of_dust', 'Cup of Dust', 'transmutation', NULL, 'curse', 3, 'both', 'druid 3, mesmerist 3, occultist 3, psychic 3, witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 day/level (D)', 'Fortitude negates', 'yes', 'You curse the target with a thirst no drink can quench. On a failed saving throw, the target begins to dehydrate (see starvation and thirst). The effects of this spell cannot inflict more nonlethal damage than the target has hit points. No amount of drinking can counter this effect, although the target still experiences the other normal effects of any liquid imbibed (such as poisons or potions). Cup of dust can be removed with a break enchantment, limited wish, miracle, remove curse, or wish spell, but effects suffered as a result of dehydration must be healed by normal means.', 'a pinch of dust', NULL, false, false),
  ('curative_distillation', 'Curative Distillation', 'conjuration', 'healing', NULL, 2, 'both', 'alchemist 2, cleric/oracle 3, investigator 2, warpriest 3', '1 standard action', 'touch', 'one living creature touched', NULL, NULL, 'instantaneous', 'Will half (harmless)', 'yes (harmless)', 'You concentrate the healing potential of the material component so that it’s exceptionally potent and restorative. This spell restores a number of hit points equal to 1d8 + 1 point per caster level (maximum +10) to the target, and also grants the target the benefits of the material component. Roll the hit points restored separately when determining how many total hit points this spell and the material component restore.', 'healing herb, alchemical remady, or potion of a healing spell worth at least 50 gp', NULL, false, true),
  ('cure_critical_wounds', 'Cure Critical Wounds', 'conjuration', 'healing', NULL, 4, 'both', 'alchemist 4, bard 4, cleric/oracle 4, druid 5, inquisitor 4, shaman 4, witch 5; Domain healing 4', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions like cure light wounds, except that it cures 4d8 points of damage + 1 point per caster level (maximum +20).', NULL, NULL, false, false),
  ('cure_light_wounds', 'Cure Light Wounds', 'conjuration', 'healing', NULL, 1, 'both', 'alchemist 1, bard 1, cleric/oracle 1, druid 1, inquisitor 1, paladin 1, ranger 2, shaman 1, witch 1; Domain healing 1', '1 standard action', 'touch', 'creature touched', NULL, NULL, 'instantaneous', 'Will half (harmless); see text', 'yes (harmless); see text', 'When laying your hand upon a living creature, you channel positive energy that cures 1d8 points of damage +1 point per caster level (maximum +5). Since undead are powered by negative energy, this spell deals damage to them instead of curing their wounds. An undead creature can apply Spell Resistance, and can attempt a Will save to take half damage.', NULL, NULL, false, false),
  ('cure_moderate_wounds', 'Cure Moderate Wounds', 'conjuration', 'healing', NULL, 2, 'both', 'alchemist 2, bard 2, cleric/oracle 2, druid 3, inquisitor 2, paladin 3, ranger 3, shaman 2, witch 2; Domain healing 2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions like cure light wounds, except that it cures 2d8 points of damage + 1 point per caster level (maximum +10).', NULL, NULL, false, false),
  ('cure_serious_wounds', 'Cure Serious Wounds', 'conjuration', 'healing', NULL, 3, 'both', 'alchemist 3, bard 3, cleric/oracle 3, druid 4, inquisitor 3, paladin 4, shaman 3, ranger 4, witch 4; Domain healing 3', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions like cure light wounds, except that it cures 3d8 points of damage + 1 point per caster level (maximum +15).', NULL, NULL, false, false),
  ('curse_of_befouled_fortune', 'Curse of Befouled Fortune', 'necromancy', NULL, 'curse', 3, 'both', 'antipaladin 3, bloodrager 4, cleric 3, shaman 3, sorcerer/wizard 4, spiritualist 3, witch 3', '1 standard action', 'touch', 'creature touched', NULL, NULL, 'permanent', 'Will negates', 'yes', 'You curse the target, making it incredibly unlucky. While affected by curse of befouled fortune, the target can’t receive luck bonuses or benefit from effects that grant it the ability to roll multiple times and take the higher result (like the swashbuckler’s charmed life ability). The target also can’t choose a die result, such as taking 10 or 20 in lieu of rolling (as per the bard’s lore master ability). Finally, the first time each turn the target would succeed at an attack, saving throw, or skill check, it must roll twice and use the worse of the two results.', NULL, NULL, false, false),
  ('curse_of_burning_sleep', 'Curse of Burning Sleep', 'transmutation', NULL, 'curse, fire', 4, 'both', 'shaman 4, sorcerer/wizard 4, witch 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature duration permanent until triggered (see text)', NULL, NULL, NULL, 'Will negates (see text)', 'yes', 'You place a curse upon the target that triggers 1 hour after the next time it falls asleep. When the curse is triggered, the creature bursts into flame, taking 1d6 points of fire damage per 2 caster levels (maximum 8d6). Furthermore, it catches on fire, taking 2d6 points of fire damage per round at the end of its turn each round until the creature dies or is quenched as normal. If the target is still asleep, the fire damage from this spell wakes it.', 'a feather and a drop of oil', NULL, false, false),
  ('curse_of_disgust', 'Curse of Disgust', 'enchantment', 'compulsion', 'curse, emotion, mind-affecting', 3, 'arcane', 'bard 3, sorcerer/wizard 5, witch 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'permanent', 'Will negates', 'yes', 'You place a curse upon a creature, causing it to avoid the sight of a specific trigger, which is a kind of creature, object, or condition designated by you. When the target is within 30 feet of a trigger and is aware of the trigger, it gains the sickened condition and feels an urge to leave. A successful Will save negates the urge to leave, but the sickened condition persists as long as the target is within 30 feet of a trigger and aware of it. Example triggers include beggars, filthy clothing, diseased creatures, the king, blood, spiders, rats, corpses, and sewage.', NULL, NULL, false, false),
  ('curse_of_dragonflies', 'Curse of Dragonflies', 'conjuration', NULL, 'air, curse', 3, 'both', 'druid 3, magus 3, shaman 4, sorcerer/wizard 4, summoner 4, witch 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one creature', NULL, NULL, 'permanent (D)', 'Will negates', 'yes', 'You invest a target with cursed elemental energy, making the open skies anathema to it. If the affected creature ever tries to fly more than 5 feet above the ground, paper insects erupt from the air around the creature to interfere with its movement. The affected creature’s flight maneuverability decreases by one step for every 3 caster levels you have. A creature whose maneuverability would be brought below clumsy must land at the end of its turn each round or fall.', 'a paper insect', NULL, false, false),
  ('curse_of_fell_seasons', 'Curse of Fell Seasons', 'transmutation', NULL, 'curse, darkness', 9, 'both', 'druid 9, shaman 9, sorcerer/wizard 9, witch 9', '10 minutes', 'touch', NULL, '2-mile radius emanating from the touched point', NULL, 'permanent (D)', 'none', 'no', 'By touching the ground, you drastically change the weather in the area, as the unseasonable weather curse. The focus merges into the cursed area as part of the spell and can only be retrieved if the curse is lifted.', NULL, 'darkwood carving of a tree worth 15,000 gp', false, true),
  ('curse_of_keeping', 'Curse of Keeping', 'enchantment', 'compulsion', 'curse', 2, 'both', 'antipaladin 2, mesmerist 2, shaman 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 day/level', 'Will negates', 'yes', 'You curse the target with the inability to sell, barter, or give away any item it owns, other than ordinary currency, for as long as the spell remains in effect. The target cannot sell, trade, drop, or give away possessions. The target can purchase items using ordinary currency but can’t then sell the purchased items. The target can accept gifts from others but can’t offer anything in exchange. A curse of keeping can be ended by break enchantment, limited wish, remove curse, miracle, or wish. Dispel magic does not affect a curse of keeping.', NULL, NULL, true, false),
  ('curse_of_magic_negation', 'Curse of Magic Negation', 'abjuration', NULL, 'curse', 4, 'both', 'cleric/oracle 5, inquisitor 4, sorcerer/ wizard 4, witch 4', '1 round', 'medium (100 ft. + 10 ft./level)', 'one creature', NULL, NULL, '10 minute/level', 'Will negates; Spell resistance no', NULL, 'You disrupt the target creature’s ability to draw upon magical energies. For the duration of the spell, it gains the negated spellblight. Dispel checks to remove the spellblight take a –5 penalty due to this spell’s interference with magical energies.', 'powdered lead and platinum worth 250 gp', NULL, false, true),
  ('curse_of_night', 'Curse of Night', 'evocation', NULL, 'curse, darkness', 8, 'both', 'cleric 8, druid 8, sorcerer/wizard 8, witch 8', '10 minutes', 'touch', NULL, '1-mile radius emanating from the touched point', NULL, 'permanent (D)', 'none (see curse text)', 'no', 'By touching the ground, you curse an area to remain in bleak darkness, as the endless night curse. The focus merges into the cursed area as part of the spell and can only be retrieved if the curse is lifted.', NULL, 'jet gemstones worth a total of 10,000 gp', false, true),
  ('curse_of_the_outcast', 'Curse of the Outcast', 'enchantment', 'compulsion', 'curse, emotion, mind-affecting', 4, 'both', 'bard 4, cleric 6, inquisitor 4, mesmerist 4, shaman 6, witch 6', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'permanent', 'Will negates', 'yes', 'Everything about the target seems off-putting and grating, and everyone he meets is compelled to see the worst in him.', 'a handful of earthworms', NULL, false, false),
  ('curse_of_unexpected_death', 'Curse of Unexpected Death', 'necromancy', NULL, 'curse, death', 4, 'both', 'cleric 4, shaman 5, witch 5', '1 standard action', 'touch', 'living creature touched', NULL, NULL, '1 minute/level (see text)', 'Fortitude partial (see text)', 'yes', 'You curse one living creature with a chance of instant and unexpected death. When you cast this spell, your hand seethes with eerie gray fire. You must succeed at a melee touch attack to touch the target, at which time the fire buries itself within the target’s body and disappears. On the round you touch the creature and once per minute thereafter, roll 1d100. On a result of 01–05, the spell is triggered and the creature takes 8d6 points of damage + 1 point per caster level; the creature can attempt a saving throw to reduce the damage to 2d6 points of damage + 1 point per caster level. On a result of 06–100, nothing happens. Once the spell is triggered or if the duration expires before it triggers, the magic ends and no further 1d100 rolls are made. If the target has spell resistance, a caster level check is made when you succeed at the touch attack. A creature can be affected by only one instance of this spell at a time. The untriggered spell can be removed with dispel magic, remove curse, or similar effects.', NULL, NULL, false, false),
  ('curse_terrain', 'Curse Terrain', 'necromancy', NULL, 'curse, evil', 4, 'both', 'cleric 4, druid 4, shaman 4, sorcerer/wizard 4, witch 4', NULL, 'touch', NULL, NULL, NULL, NULL, NULL, NULL, 'By touching the ground, you curse the land with four unnatural hazards. This functions as lesser curse terrain, but with the effects of the major perilous demesne curse.', 'the heart of a creature that dwelled in the area and powdered onyx worth 700 gp', NULL, false, true),
  ('curse_water', 'Curse Water', 'necromancy', NULL, 'evil', 1, 'divine', 'antipaladin 1, cleric/oracle 1, inquisitor 1', '1 minute', 'touch', 'flask of water touched', NULL, NULL, 'instantaneous', 'Will negates (object)', 'yes (object)', 'This spell imbues a flask (1 pint) of water with negative energy, turning it into unholy water. Unholy water damages good outsiders the way holy water damages undead and evil outsiders.', '5 lbs. of powdered silver worth 25 gp', NULL, false, true),
  ('curse_major', 'Curse, Major', 'necromancy', NULL, 'curse', 5, 'both', 'cleric/oracle 5, shaman 5, sorcerer/wizard 6, witch 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'permanent', 'Will negates; Spell resistance yes', NULL, 'This spell functions as bestow curse, except the DC to remove the curse is equal to the save DC +5.', NULL, NULL, false, false),
  ('cursed_earth', 'Cursed Earth', 'necromancy', NULL, 'curse, evil; see text', 9, 'both', 'cleric/oracle 9, sorcerer/wizard 9, witch 9', '10 minutes', 'touch', NULL, '1-mile radius emanating from the touched point', NULL, 'permanent', 'none (see text); Spell resistance no', NULL, 'You lay a terrible curse upon the land, blighting those who live and die there. Choose one of the following effects.', 'powdered onyx 10,000 gp', NULL, true, true),
  ('cursed_treasure', 'Cursed Treasure', 'necromancy', NULL, 'curse', 3, 'both', 'antipaladin 3, arcanist 4, bloodrager 4, cleric/oracle 3, shaman 3, sorcerer/wizard 4, spiritualist 3, warpriest 3, witch 3', '1 minute', 'touch', 'unattended object touched', NULL, NULL, 'permanent until discharged, then permanent (see text)', 'Fort negates (object), then Will negates (see text)', 'yes (object), then yes (see text)', 'You touch a piece of treasure or container filled with treasure and place a terrible curse upon it, choosing from any option available with bestow curse. The next creature to take the treasure or remove items from the container is affected by the curse, unless it succeeds at a Will save (spell resistance applies). If you are the next creature to take the treasure or get objects from the container, though, the spell discharges harmlessly instead.', 'a platinum piece', NULL, false, false),
  ('cushioning_bands', 'Cushioning Bands', 'conjuration', 'creation', 'force', 2, 'arcane', 'psychic 2, sorcerer/wizard 2, summoner/unchained summoner 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 hour/level or until discharged (D)', 'Will negates (harmless); Spell resistance yes', NULL, 'Invisible bands of force encircle vital areas of the target. The bands resist crushing forces and impacts without interfering with movement. The target gains DR 2/piercing or slashing and takes half damage from constriction, falling, and being buried, as well as from similar crushing effects such as crushing hand. Grapple checks for attacks other than constricting (such as pinning or swallowing whole) are not affected. Once the spell has blocked 12 points of damage per caster level (to a maximum of 120 points at 10th level), it is discharged. The bands have no effect on incorporeal attacks unless they deal damage from constriction or crushing, or unless the attacks would be subject to damage reduction.', NULL, NULL, false, false),
  ('cyclic_reincarnation', 'Cyclic Reincarnation', 'transmutation', NULL, NULL, 5, 'arcane', 'druid 6 Components V, S, M (oils worth 5,000 gp), DF', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell allows a dead creature that died no more than 1 year before the casting of the spell to return to life in a body that closely resembles its original body; it functions as reincarnate except as noted. Cyclic reincarnation returns the dead creature to life in a new body of the same race that the target belonged to in life, and the new body appears physically similar to the creature’s previous one, to the extent that the creature could be easily mistaken for its own offspring or kin. If the affected creature isn’t a humanoid, there is a 75% chance that the creature returns to life as a youth of its race, gaining the young creature simple template instead (or becomes a juvenile, in the case of dragons and other creatures whose power is determined by their age category).', NULL, NULL, false, false),
  ('daemon_ward', 'Daemon Ward', 'necromancy', NULL, NULL, 4, 'both', 'cleric 4, druid 5, paladin 4, sorcerer/wizard 4, witch 4', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions like death ward, except as noted above and it only protects against these attacks from daemons.', '50 gp worth of powdered silver', NULL, false, true),
  ('damnation', 'Damnation', 'evocation', NULL, 'good', 3, 'divine', 'cleric 3, inquisitor 3, paladin 3', '1 standard action', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'You pass judgment on your enemies’ intentions and punish them with holy power. Each creature in the spell’s area takes 1d8 points of damage per spell level, determined by the most powerful effect with the evil descriptor either affecting that creature or in its spell repertoire. A caster who prepares spells takes this damage based on the highest-level evil spell he prepared that day, even if he already cast that spell.', 'a drop of holy water', NULL, true, false),
  ('damnation_of_memory', 'Damnation of Memory', 'enchantment', 'compulsion', 'mind-affecting', 6, 'arcane', 'bard 6, mesmerist 6, psychic 9', '1 hour', 'long (400 ft. + 40 ft./level)', NULL, NULL, NULL, 'permanent', 'Will negates', 'yes', 'You name one creature and excise all memory of that creature’s involvement in events the targets remember. The targets either forget who exactly performed the named creature’s deeds or assume some other individual performed them.', NULL, 'a massive, flawless gemstone worth 5,000 gp', false, true),
  ('damnation_stride', 'Damnation Stride', 'conjuration', 'teleportation', 'fire', 4, 'arcane', 'sorcerer/wizard 5, summoner 4, witch 5', '1 standard action', NULL, 'you (teleportation) and creatures within a 10-foot-radius burst (burst of flame) (see text)', NULL, NULL, 'instantaneous', 'Reflex half, see text', 'no', 'This spell functions like dimension door, except you leave behind a burst of fire. Choose one corner of your starting square. A 10-foot-radius burst of flame explodes from that corner the moment you leave, dealing 4d6 points of fire damage.', NULL, NULL, false, false),
  ('damp_powder', 'Damp Powder', 'transmutation', NULL, NULL, 1, 'both', 'druid 1, sorcerer/wizard 1, witch 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', '1 loaded firearm', NULL, NULL, 'instantaneous', 'Will negates (object)', 'yes (object)', 'This spell causes ammunition already loaded into the target firearm is ruined with moisture. Any attempt to fire that ammunition fails, with no chance for misfire, and the user must then take a full-round action to clear the weapon before reloading and firing it. If aware of this spell’s effect prior to firing the altered ammunition (a DC 16 Spellcraft check to identify the spell being cast or similar effect), the firearm’s user can spend a standard action to clear the altered ammunition from the firearm. Doing so destroys that ammunition.', 'a damp piece of cotton', NULL, true, false),
  ('dance_of_a_hundred_cuts', 'Dance of a Hundred Cuts', 'transmutation', NULL, NULL, 4, 'arcane', 'bard 4', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level', NULL, NULL, 'You become a lethal combat dancer, swirling and spinning with grace and precision.', NULL, NULL, false, false),
  ('dance_of_a_thousand_cuts', 'Dance of a Thousand Cuts', 'transmutation', NULL, NULL, 6, 'arcane', 'bard 6', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions as dance of a hundred cuts, except you also gain the benefits of haste.', NULL, NULL, false, false),
  ('dancing_darkness', 'Dancing Darkness', 'evocation', NULL, 'darkness, shadow', 1, 'both', 'antipaladin 1, bard 1, magus 1, shaman 1, psychic 1, sorcerer/wizard 1, spiritualist 1, witch 1', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'Up to four spheres, all within a 10-ft.-radius area', '1 minute/level (D)', 'none', 'no', 'You create either up to four spheres of darkness that each reduce the illumination level by one step within a 20-foot-radius, or one dimly lit, vaguely humanoid shape. Each sphere must stay within a 10-foot-radius area of one another but can otherwise move as you desire (no concentration required): forward or back, up or down, straight or turning corners, or the like.', NULL, NULL, false, false),
  ('dancing_lantern', 'Dancing Lantern', 'transmutation', NULL, 'fire, light', 1, 'both', 'bard 1, cleric/oracle 1, ranger 1, shaman 1, sorcerer/wizard 1, witch 1; Elemental School fire 1', '1 standard action', 'touch', NULL, NULL, 'animates one lantern', '1 hour/level (D)', 'none', 'no', 'You can animate a lantern and order it to follow you. The lantern floats at shoulder height and remains within 5 feet of you, no matter how fast you move. The lantern cannot support any additional weight. The lantern illuminates its normal area, even if it does not have any oil in it. For the purposes of spells or effects targeting it the lantern always acts as if in your possession even when not directly on your person. A dancing lantern can be made permanent with a permanency spell (CL 9th, 2,500 gp).', NULL, 'a lantern', false, false),
  ('dancing_lights', 'Dancing Lights', 'evocation', NULL, 'light', 0, 'both', 'bard 0, magus 0, psychic 0, shaman 0, sorcerer/wizard 0, witch 0', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'Up to four lights, all within a 10-ft.-radius area', '1 minute (D)', 'none', 'no', 'Depending on the version selected, you create up to four lights that resemble lanterns or torches (and cast that amount of light), or up to four glowing spheres of light (which look like will-o’-wisps), or one faintly glowing, vaguely humanoid shape. The dancing lights must stay within a 10-foot-radius area in relation to each other but otherwise move as you desire (no concentration required): forward or back, up or down, straight or turning corners, or the like. The lights can move up to 100 feet per round. A light winks out if the distance between you and it exceeds the spell’s range.', NULL, NULL, false, false),
  ('dark_whispers', 'Dark Whispers', 'illusion', 'shadow', 'language-dependent, shadow', 1, 'both', 'antipaladin 1, bard 2, cleric 2, sorcerer/wizard 2, summoner 2, witch 2', '1 standard action', 'long (400 ft. plus 40 ft./level)', NULL, NULL, NULL, '10 minutes/level (D)', 'none', 'yes', 'You communicate through the shadows of one or more targets within range. The shadows have no physical presence and don’t move or animate. Instead, your words emerge from the shadow as a clear whisper, absent any accent or other identifying features. The targets can make conversation with the shadow, but must speak aloud to do so. The targets’ voices emerge from your own shadow only when they intend to speak to the shadow, but you hear no other sounds from the target’s immediate area. Their responses also emerge as clear whispers, absent identifying features, but you can instinctively identify which target is speaking to you through the shadow.', NULL, NULL, true, false),
  ('dark_light', 'Dark-Light', 'evocation', NULL, 'light', 3, 'both', 'cleric 3, druid 3, sorcerer/wizard 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'living creatures without light sensitivity', NULL, NULL, 'instantaneous', 'Fortitude partial', 'yes', 'You evoke a powerful light that affects all sighted creatures that do not posses light sensitivity. Those that succeed on their saves are dazzled for 1 round per level; those who fail are blinded for the same duration.', 'a pinch of earth', NULL, true, false),
  ('darkness', 'Darkness', 'evocation', NULL, 'darkness', 2, 'both', 'antipaladin 2, bard 2, cleric/oracle 2, inquisitor 2, magus 2, shaman 2, sorcerer/wizard 2', '1 standard action', 'touch', 'object touched', NULL, NULL, '1 min./level (D)', 'none', 'no', 'This spell causes an object to radiate darkness out to a 20-foot radius. This darkness causes the illumination level in the area to drop one step, from bright light to normal light, from normal light to dim light, or from dim light to darkness. This spell has no effect in an area that is already dark. Creatures with light vulnerability or sensitivity take no penalties in normal light. All creatures gain concealment (20% miss chance) in dim light. All creatures gain total concealment (50% miss chance) in darkness. Creatures with darkvision can see in an area of dim light or darkness without penalty. Nonmagical sources of light, such as torches and lanterns, do not increase the light level in an area of darkness. Magical light sources only increase the light level in an area if they are of a higher spell level than darkness.', 'bat fur and a piece of coal', NULL, true, false),
  ('darkvault', 'Darkvault', 'abjuration', NULL, NULL, 3, 'both', 'alchemist 3, cleric 5, druid 5, psychic 5, shaman 5, sorcerer/wizard 5, witch 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, '30-ft.-radius emanation', NULL, '24 hours', 'none', 'no', 'You ward an area’s shadows such that light cannot penetrate them.', 'a stone that has never seen sunlight', NULL, false, false),
  ('darkvision', 'Darkvision', 'transmutation', NULL, NULL, 2, 'both', 'alchemist 2, antipaladin 2, psychic 2, ranger 3, sorcerer/wizard 2; Bloodline deep earth 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 hour/level', 'Will negates (harmless)', 'yes (harmless)', 'The subject gains the ability to see 60 feet even in total darkness. Darkvision is black and white only but otherwise like normal sight.', 'either a pinch of dried carrot or an agate', NULL, false, false),
  ('darting_duplicate', 'Darting Duplicate', 'illusion', 'figment', NULL, 1, 'both', 'antipaladin 1, bard 1, magus 1, shaman 1, sorcerer/wizard 1, witch 1', '1 swift action', '5 ft.', NULL, NULL, 'visual figment of the caster', 'instantaneous', 'Will negates', 'yes', 'An illusory duplicate of you steps clumsily into an adjacent square, presenting a tempting target before winking out of existence.', NULL, NULL, false, false),
  ('daybreak_arrow', 'Daybreak Arrow', 'evocation', NULL, 'light', 3, 'divine', 'cleric 3, inquisitor 3, paladin 3', '1 standard action', 'touch', 'up to 50 pieces of ammunition, all of which must be together at the time of casting', NULL, NULL, '10 minutes/level', 'Fort negates (harmless, object)', 'yes (harmless, object)', 'You cause ammunition, including shuriken, to exude radiant energy. Creatures that take penalties in bright light take these penalties for 1 round after being struck by such ammunition. Undead and creatures harmed by sunlight take an additional 1d6 points of damage from such projectiles. This extra damage and half of any other damage you deal with an affected projectile results directly from radiant energy and is not subject to damage resistance. Such a projectile sheds light as if it were a sunrod for 1 round after it is fired or thrown.', NULL, NULL, false, false),
  ('daylight', 'Daylight', 'evocation', NULL, 'light', 3, 'both', 'bard 3, cleric/oracle 3, druid 3, inquisitor 3, magus 3, paladin 3, shaman 3, sorcerer/wizard 3; Subdomain day 3, light 3; Mystery heavens 3, solar 3', '1 standard action', 'touch', 'object touched', NULL, NULL, '10 min./level (D)', 'none', 'no', 'You touch an object when you cast this spell, causing the object to shed bright light in a 60-foot radius. This illumination increases the light level for an additional 60 feet by one step (darkness becomes dim light, dim light becomes normal light, and normal light becomes bright light). Creatures that take penalties in bright light take them while within the 60-foot radius of this magical light. Despite its name, this spell is not the equivalent of daylight for the purposes of creatures that are damaged or destroyed by such light.', NULL, NULL, false, false),
  ('daywalker', 'Daywalker', 'necromancy', NULL, NULL, 4, 'both', 'antipaladin 4, cleric 5, sorcerer/wizard 5, witch 5', '1 standard action', 'touch', 'undead creature touched', NULL, NULL, '24 hours (D)', 'none', 'yes (harmless)', 'You reshape the substance of a willing undead creature to resemble a living, breathing creature of the same size. This is a physical change to the undead creature’s bone, flesh, or incorporeal ectoplasm, adding new flesh or bone and even hair, teeth, and blood, all of which demonstrate false signs of life that mimic a living creature’s breathing and other physiological processes. An incorporeal undead creature using daywalker ceases to be incorporeal for the duration of the spell, gaining a physical corpse body. Creatures interacting with the undead can attempt a Perception check (DC = 30 or DC = 21 + the undead’s Disguise modifier, whichever is higher) to realize that the signs of life are false, and a close examination with a Heal check always reveals the truth of the dead flesh.', 'a black glass vial containing unholy water', NULL, false, false),
  ('daze', 'Daze', 'enchantment', 'compulsion', 'mind-affecting', 0, 'both', 'bard 0, inquisitor 0, magus 0, psychic 0, shaman 0, sorcerer/wizard 0, summoner/unchained summoner 0, witch 0', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one humanoid creature of 4 HD or less', NULL, NULL, '1 round', 'Will negates', 'yes', 'This spell clouds the mind of a humanoid creature with 4 or fewer Hit Dice so that it takes no actions. Humanoids of 5 or more HD are not affected. A dazed subject is not stunned, so attackers get no special advantage against it. After a creature has been dazed by this spell, it is immune to the effects of this spell for 1 minute.', 'a pinch of wool or similar substance', NULL, false, false),
  ('daze_monster', 'Daze Monster', 'enchantment', 'compulsion', 'mind-affecting', 1, 'arcane', 'bard 2, bloodrager 2, psychic 2, sorcerer/wizard 2, summoner/unchained summoner 1, witch 2; Mystery godclaw 2', NULL, 'medium (100 ft. + 10 ft./level)', 'one living creature of 6 HD or less', NULL, NULL, NULL, NULL, NULL, 'This spell functions like daze, but it can affect any one living creature of any type. Creatures of 7 or more HD are not affected.', NULL, NULL, false, false),
  ('dazzling_blade', 'Dazzling Blade', 'illusion', 'pattern', NULL, 1, 'arcane', 'bard 1, sorcerer/wizard 1', '1 swift action', 'Touch', 'one metal weapon', NULL, NULL, '1 minute/level', 'Will negates (see text)', 'yes (harmless, object)', 'Dazzling blade makes a weapon appear dazzlingly shiny, as if crafted from pure silver and heavily polished. In combat, the flashing movements of a dazzling blade become almost hypnotic. The wielder of a weapon under the effects of dazzling blade gains a +1 competence bonus on all Bluff checks made to feint in combat. The wielder also gains a +1 competence bonus on all CMB checks made to disarm a foe, and a +1 competence bonus to his CMD against disarm attempts made against the weapon bearing the dazzling blade effect. This bonus increases by +1 for every 3 caster levels, to a maximum bonus of +5 at 12th level.', NULL, NULL, false, false),
  ('deadeye_s_arrow', 'Deadeye’s Arrow', 'evocation', 'electricity', NULL, 1, 'divine', 'cleric/oracle 2, druid 1, inquisitor 1, paladin 1, ranger 1, magus 1; Domain healing 1', '1 standard action', 'medium (100 ft. + 10ft./level)', NULL, NULL, 'arrow of electricity', 'instantaneous or 1 round (see text)', 'none', 'yes', 'You create an arrow made of crackling electricity, which you may use for one of two effects.', 'one arrow', NULL, false, false),
  ('deadeye_s_lore', 'Deadeye’s Lore', 'divination', NULL, NULL, 1, 'both', 'bard 1, cleric 1, druid 1, inquisitor 1, ranger 1', '1 round', 'personal', 'you', NULL, NULL, '1 hour/level', NULL, NULL, 'While subject to this spell, you take upon yourself the mantle of the hunter, channeling the insights of the spirits of the wild.', NULL, NULL, false, false),
  ('deadly_finale', 'Deadly Finale', 'evocation', NULL, 'sonic', 6, 'arcane', 'bard 6', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, 'instantaneous', 'Fortitude partial', 'yes', 'You must have a bardic performance in effect to cast this spell.', NULL, NULL, false, false),
  ('deadly_juggernaut', 'Deadly Juggernaut', 'necromancy', NULL, 'death', 3, 'divine', 'antipaladin 3, cleric 3, inquisitor 3, paladin 3', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level', NULL, NULL, 'With every enemy life you take, you become increasingly dangerous and difficult to stop. During the duration of the spell, you gain a cumulative +1 luck bonus on melee attack rolls, melee weapon damage rolls, Strength checks, and Strength-based skill checks as well as DR 2/— each time you reduce a qualifying opponent to 0 or few hit points (maximum +5 bonus and DR 10/—) with a melee attack. A qualifying opponent has a number of Hit Dice equal to or greater than your Hit Dice –4.', NULL, NULL, false, false),
  ('deadman_s_contingency', 'Deadman’s Contingency', 'evocation', NULL, NULL, 4, 'both', 'bard 4, cleric 4, psychic 4, sorcerer/wizard 4, witch 4', '10 minutes or more; see text', 'personal', 'you', NULL, NULL, 'up to 1 hour/level plus 1d6 rounds (D); see text', NULL, NULL, 'This spell functions as contingency, except as noted above. This spell also only comes into effect after your death and works only with certain spells. The companion spell triggers 1d6 rounds after your death. All decisions made involving the companion spell must be made when deadman’s contingency is cast (including messages and recipients for spells like magic mouth or sending).', 'a scorpion’s tail', 'ivory statuette of you worth 1,500 gp', false, true),
  ('deafening_song_bolt', 'Deafening Song Bolt', 'evocation', NULL, 'sonic', 5, 'arcane', 'bard 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, 'instantaneous', 'none', 'no', 'Three notes you sing or perform become tangible bolts of arcane energy that shriek across the battlefield. Each bolt requires a ranged touch attack to hit and deals 3d10 points of sonic damage, deafening the target for 1d6 rounds. The bolts may be fired at the same or different targets, but all must be fired simultaneously.', NULL, NULL, false, false),
  ('death_candle', 'Death Candle', 'necromancy', NULL, 'death, evil, fire', 1, 'both', 'antipaladin 1, cleric 2, inquisitor 2, witch 2', '1 round', 'touch', 'living creature touched', NULL, NULL, 'instantaneous/1 round per HD of subject; see text', 'Fort negates', 'yes', 'This spell functions like death knell, except instead of using the slain target’s life energy to enhance yourself, you use it to summon a Small fire elemental resembling a burning, howling version of the slain creature. The elemental acts immediately on your turn and otherwise behaves as if you had summoned it with summon monster II. The elemental remains for a number of rounds equal to the Hit Dice of the slain creature.', NULL, NULL, false, false),
  ('death_clutch', 'Death Clutch', 'necromancy', NULL, 'death, evil', 8, 'both', 'cleric 8, druid 9, psychic 8, sorcerer/wizard 8, witch 8', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one living creature', NULL, NULL, 'instantaneous', 'Fortitude partial (see text)', 'yes', 'Chanting an unholy litany, you reach out with a grasping motion toward your target and cause its heart to leap out of its chest and into your hand. A target with 200 or fewer hit points remaining that fails its saving throw is instantly reduced to a number of negative hit points equal to your caster level or its Constitution score – 1, whichever is less negative. The creature is staggered until the beginning of your next turn, at which point it dies. If the affected creature receives a regenerate spell before the beginning of your next turn, the creature gains the normal benefits of that spell and, thanks to its heart’s regeneration, it doesn’t immediately die when your next turn begins. If a creature that dies from death clutch is brought back from the dead by a breath of life or raise dead spell, it must also be targeted with regenerate on the following round to restore its missing heart or be unable to return to life.', NULL, NULL, false, false),
  ('death_from_below', 'Death from Below', 'abjuration', NULL, NULL, 2, 'arcane', 'bard 3, bloodrager 2, sorcerer/wizard 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 round/level', 'Fort negates (harmless)', 'yes (harmless)', 'You grant the target a dodge bonus to its Armor Class against attacks from larger creatures. The bonus is equal to +1 for every size category the attacker is larger than the target of the spell, to a maximum of +1 per 3 caster levels. If the spell’s target is a gnome, the maximum bonus is equal to +1 per 2 caster levels.', NULL, NULL, false, false),
  ('death_knell', 'Death Knell', 'necromancy', NULL, 'death, evil', 1, 'divine', 'antipaladin 1, cleric/oracle 2, inquisitor 2, witch 2; Domain death 2', '1 standard action', 'touch', 'living creature touched', NULL, NULL, 'instantaneous/10 minutes per HD of subject; see text', 'Will negates', 'yes', 'You draw forth the ebbing life force of a creature and use it to fuel your own power. Upon casting this spell, you touch a living creature that has -1 or fewer hit points. If the subject fails its saving throw, it dies, and you gain 1d8 temporary hit points and a +2 enhancement bonus to Strength. Additionally, your effective caster level goes up by +1, improving spell effects dependent on caster level. This increase in effective caster level does not grant you access to more spells. These effects last for 10 minutes per HD of the subject creature.', NULL, NULL, false, false),
  ('death_knell_aura', 'Death Knell Aura', 'necromancy', NULL, 'death, evil', 4, 'both', 'cleric 4, inquisitor 4, sorcerer/wizard 4, witch 4', '1 standard action', '20 ft.', NULL, '20-ft.-radius emanation, centered on you', NULL, '1 round/level (D)', 'Will negates', 'yes', 'You gain a shimmering gray aura that feeds on the souls of creatures who die within it. The aura sheds light as a candle. If a creature at –1 or fewer hit points is within the aura at the start of its turn, it must save or die, granting you the benefits of death knell.', NULL, NULL, false, false),
  ('death_pact', 'Death Pact', 'enchantment', NULL, 'mind-affecting', 5, 'arcane', 'bard 5, mesmerist 5, psychic 6, witch 6', '1 minute', 'touch', 'one creature', NULL, NULL, '24 hours', 'Will negates; see text', 'yes', 'You take control of a creature’s mind and implant deadly subconscious commands. This spell functions as dominate person, allowing you to control your subject and see through her senses, but also implants a powerful burst of psychic energy in the subject’s mind. At any point during the spell’s duration, you can trigger this burst as an immediate action, dealing 1d8 points of damage per caster level (Fortitude half) to the subject. If this damage is enough to reduce to target to 0 or fewer hit points, the target dies instantly.', 'a contract signed in blood', NULL, false, false),
  ('death_ward', 'Death Ward', 'necromancy', NULL, NULL, 4, 'both', 'alchemist 4, cleric/oracle 4, druid 5, inquisitor 4, paladin 4, witch 4; Domain death 4,  repose 4', '1 standard action', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The subject gains a +4 morale bonus on saves against all death spells and magical death effects. The subject is granted a save to negate such effects even if one is not normally allowed. The subject is immune to energy drain and any negative energy effects, including channeled negative energy.', NULL, NULL, true, false),
  ('deathwatch', 'Deathwatch', 'necromancy', NULL, NULL, 1, 'divine', 'cleric/oracle 1; Domain repose 1; Mystery apocalypse 1', '1 standard action', '30 ft.', NULL, 'cone-shaped emanation', NULL, '10 min./level', 'none', 'no', 'Using the powers of necromancy, you can determine the condition of creatures near death within the spell’s range. You instantly know whether each creature within the area is dead, fragile (alive and wounded, with 3 or fewer hit points left), fighting off death (alive with 4 or more hit points), healthy, undead, or neither alive nor dead (such as a construct). Deathwatch sees through any spell or ability that allows creatures to feign death.', NULL, NULL, false, false),
  ('deathwine', 'Deathwine', 'necromancy', NULL, NULL, 2, 'both', 'alchemist 2, cleric 2, sorcerer/wizard 3, witch 3', '1 minute', 'touch', '1 potion touched/level', NULL, NULL, '1 hour/level', 'none (object)', 'no (object)', 'This spell allows you to turn a potion into a temporary pool of necromantic energy. Only a potion created using a conjuration (healing) spell can be affected by this spell. An affected potion turns dark red and reveals a necromantic aura if detect magic is cast on it while it remains under this spell’s effects.', NULL, NULL, false, false),
  ('debilitating_pain', 'Debilitating Pain', 'enchantment', 'compulsion', 'mind-affecting, pain', 3, 'arcane', 'psychic 3, witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round/3 levels', 'Will partial (see text)', 'yes', 'The target is overcome with intense pain, causing it to be stunned on a failed save or dazed for 1 round on a successful save.', NULL, NULL, false, false),
  ('debilitating_portent', 'Debilitating Portent', 'enchantment', 'compulsion', 'mind-affecting', 4, 'both', 'cleric 4, witch 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one creature', NULL, NULL, '1 round/level (D) see text', 'none', 'yes', 'The target is surrounded by a glowing green aura of ill fate.', NULL, NULL, true, false),
  ('debilitating_speech', 'Debilitating Speech', 'enchantment', NULL, 'language-dependent, mind-affecting', 4, 'arcane', 'sorcerer/wizard 4', 'see below', 'close (25 feet + 5 ft./2 levels)', NULL, NULL, NULL, '1 round/level', 'Will negates', 'yes', 'By speaking eloquently on the subject of your opponents’ ineptitude in combat, past failures, personal hygiene, or other faults, you sap their will to fight.', NULL, NULL, false, false),
  ('decapitate', 'Decapitate', 'evocation', NULL, NULL, 5, 'both', 'inquisitor 5, magus 6, psychic 6, sorcerer/wizard 6', '1 immediate action', 'close (25 ft. + 5 ft./2 levels)', 'one creature (see text)', NULL, NULL, 'instantaneous', 'Fortitude partial (see text)', 'yes', 'You can cast this spell only as a response to a confirmed critical hit against the target that would deal slashing damage. If the target fails the saving throw and has a discernible head, the attack deals an extra 4d6 points of damage and the critical multiplier of the critical hit increases by 1. If the critical hit then brings the target to 0 hit points or fewer, the target is instantly decapitated and dies unless it can survive decapitation. Even on a successful saving throw, the critical hit deals an extra 4d6 points of damage.', NULL, 'a sliver from a guillotine blade', false, false),
  ('deceitful_veneer', 'Deceitful Veneer', 'illusion', 'glamer', NULL, 3, 'both', 'antipaladin 3, bard 4, inquisitor 4, medium 3, mesmerist 4, psychic 4, witch 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '10 minutes/level (D)', 'Will negates', 'yes', 'You subtly alter both the target’s aura and subtle cues in its body language, tone of voice, and word choice, which makes everything that the target says seem to be a lie. Every statement that the target makes appears to be a lie under both magical scrutiny (such as discern lies) and mundane scrutiny (such as using the Sense Motive skill). Someone who closely scrutinizes the target can determine when it is actually telling the truth with a successful Sense Motive check (DC = 15 + your caster level).', NULL, NULL, false, false),
  ('deceptive_redundancy', 'Deceptive Redundancy', 'illusion', 'glamer', NULL, 5, 'arcane', 'bard 5, mesmerist 5, psychic 5, sorcerer/wizard 5', '1 standard action', 'personal', NULL, NULL, NULL, '10 minutes/level or until triggered, then 1 round/level', 'none', 'no', 'You create a contingent ward that defies those who would dispel your magic, convincing them that their spell worked.', NULL, NULL, false, false),
  ('decollate', 'Decollate', 'necromancy', NULL, NULL, 4, 'both', 'alchemist 4, antipaladin 4, cleric 5, psychic 6, sorcerer/wizard 5, spiritualist 4, witch 5', '1 standard action', 'touch', 'one willing humanoid or monstrous humanoid creature', NULL, NULL, '24 hours', 'none', 'yes (harmless)', 'A thin red line circles the target’s neck. The target’s head becomes detachable so long as she removes it willingly. While the target’s head is detached, she gains DR 2/— and immunity to decapitation effects and other effects that require their target to have a head or a particular facial feature. The target is blind so long as she has no head, but she gains blindsense to a distance of 15 feet. The target hears normally even without its head.', NULL, 'a red wax pencil', false, false),
  ('decompose_corpse', 'Decompose Corpse', 'necromancy', NULL, NULL, 1, 'both', 'cleric/oracle 1, druid 1, medium 1, occultist 1, psychic 1, sorcerer/wizard 1, spiritualist 1, witch 1', '1 standard action', 'touch', 'one corpse or corporeal undead', NULL, NULL, 'instantaneous or 1 minute; see text', 'Fortitude negates (object); Spell resistance yes (object)', NULL, 'Using this spell, the caster rapidly decomposes the flesh from a single corpse of size Huge or smaller, leaving behind a perfectly cleaned skeleton. If it is cast on a non-skeletal corporeal undead, the creature takes a –2 penalty on all rolls and to its Armor Class and CMD for 1 minute.', 'a pinch of dried toadstool', NULL, false, false),
  ('decrepit_disguise', 'Decrepit Disguise', 'illusion', 'glamer', NULL, 1, 'arcane', 'bard 1, medium 1, mesmerist 1, occultist 1, psychic 1, sorcerer/wizard 1', '1 standard action', 'close (25 ft. + 5 ft./level)', 'one object of no more than 10 cu. ft./level', NULL, NULL, '1 day/level', 'none (object) or Will disbelief (if interacted with)', 'no', 'You make an object seem like a worthless version of itself. A masterwork or magic sword could seem to be a useless, rusting, discarded blade, and a luxurious throne could appear to be a decrepit wooden chair. If used against an attended object, the wielder can immediately attempt a Will save to disbelieve the effect. Decrepit disguise counters and dispels quintessence.', NULL, NULL, false, false),
  ('deep_slumber', 'Deep Slumber', 'enchantment', 'compulsion', 'mind-affecting', 3, 'both', 'bard 3, mesmerist 3, occultist 3, psychic 3, shaman 3, sorcerer/wizard 3, witch 3; Bloodline dreamspun 3, fey 3', NULL, 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions like sleep, except that it affects 10 HD of targets.', NULL, NULL, false, false),
  ('deeper_darkness', 'Deeper Darkness', 'evocation', NULL, 'darkness', 3, 'divine', 'antipaladin 3, cleric/oracle 3, inquisitor 3, shaman 3; Domain darkness 3; Bloodline div 3; Mystery shadow 3', NULL, NULL, NULL, NULL, NULL, '10 min./level (D)', NULL, NULL, 'This spell functions as darkness, except that objects radiate darkness in a 60-foot radius and the light level is lowered by two steps. Bright light becomes dim light and normal light becomes darkness. Areas of dim light and darkness become supernaturally dark. This functions like darkness, but even creatures with darkvision cannot see within the spell’s confines.', NULL, NULL, false, false),
  ('defending_bone', 'Defending Bone', 'necromancy', NULL, NULL, 2, 'both', 'cleric/oracle 2, inquisitor 2, magus 2, sorcerer/wizard 2, witch 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 hour/level or until discharged', 'none', 'no', 'You animate a bone with necromantic energy, giving it the power to float near your body and interpose itself against physical attacks.', NULL, NULL, true, false),
  ('defending_sword', 'Defending Sword', 'evocation', NULL, 'force', 6, 'arcane', 'magus 6, occultist 6, psychic 7, sorcerer/wizard 6', '1 standard action', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'You create a sword of force that functions as mage’s sword except as described here. The sword does not receive the additional +3 enhancement bonus a mage’s sword receives, and deals 3d6 points of force damage. You cannot command the sword. Until the sword is triggered, it hovers in your space without interfering with your actions. While hovering in this way, the sword attempts to defend you from incoming attacks, granting you a +4 shield bonus to your AC. The first time a foe within close range damages you or forces you to attempt a saving throw that you fail, the sword is triggered and begins attacking that target as described in mage’s sword for the duration of the spell. This ends the shield bonus. You cannot direct the sword to defend against a new target once it has begun to attack. If its target moves beyond the sword’s range, the sword returns to you and hovers until the target is again within range. The sword’s return does not restore the spell’s shield bonus to AC.', NULL, NULL, false, false),
  ('defensive_grace', 'Defensive Grace', 'transmutation', NULL, NULL, 5, 'arcane', 'investigator 5', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level (D; see below)', NULL, NULL, 'Each round you can roll an inspiration die without expending a use of inspiration and gain the result as a dodge bonus to AC for that round. You are immune to precision damage (including the extra damage from the precise strike deed, sneak attack, studied combat, and studied strike).', 'a living fly', NULL, false, false),
  ('defensive_shock', 'Defensive Shock', 'evocation', NULL, 'electricity', 2, 'arcane', 'alchemist 2, bloodrager 2, magus 2, sorcerer/wizard 2; Elemental School metal 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level or until discharged', NULL, NULL, 'Electrical energy floods your body, shocking the next creature that touches you. Any creature striking you with its body or a handheld weapon takes 1d6 points of electricity damage per two caster levels (maximum 6d6). If the attacker has spell resistance, it applies against this damage. Each time the spell discharges, the number of damage dice it deals is halved (rounded down); when the spell’s damage dice reach 0, the spell ends.', 'a hollow metal sphere', NULL, false, false),
  ('defile_armor', 'Defile Armor', 'abjuration', NULL, 'evil', 3, 'divine', 'antipaladin 3, inquisitor 4', '1 standard action', 'touch', NULL, NULL, NULL, '1 minute/level', 'Will negates (harmless, object)', 'yes (harmless, object)', 'As sanctify armor, except you gain DR 5/good when using your judgment or smite ability.', NULL, NULL, false, false),
  ('deflect_blame', 'Deflect Blame', 'enchantment', 'compulsion', 'mind-affecting', 2, 'arcane', 'bard 2, mesmerist 2, psychic 2, sorcerer/wizard 3', '1 immediate action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'instantaneous', 'Will negates', 'yes', 'You can cast this spell immediately after attacking a creature, causing that creature to believe that a different creature that threatens it was responsible for the attack rather than you.', NULL, NULL, false, false),
  ('deflection', 'Deflection', 'abjuration', NULL, 'force', 7, 'arcane', 'sorcerer/wizard 7; Subdomain defense 7', '1 standard action', 'personal', NULL, NULL, NULL, '1 round/level', NULL, NULL, 'You surround yourself in a whirling barrier of force that sends any attack that misses you hurling back toward its source.', 'a piece of rubber dipped in glue', NULL, false, false),
  ('defoliate', 'Defoliate', 'necromancy', NULL, NULL, 1, 'both', 'druid 2, ranger 1, sorcerer/wizard 2; Subdomain radiation 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'or', 'see text', NULL, 'instantaneous', 'none', 'yes', 'You hurl a tiny ball of negative energy, destroying plant life either in a line 60 feet long or a 10-foot-radius spread. This effect removes the cover and concealment provided by trees and undergrowth, eliminates the movement penalties associated with undergrowth, and so forth.You may also target a single plant creature with this spell. You must succeed on a ranged touch attack to hit your target. An affected plant creature takes 2d8 points of damage.', 'a locust', NULL, false, false),
  ('deft_digits', 'Deft Digits', 'transmutation', NULL, NULL, 3, 'arcane', 'bard 3, medium 3, occultist 3, psychic 3, sorcerer/wizard 3, spiritualist 3, summoner 3', '1 standard action', 'Medium (100 ft. + 10 ft./level)', '1 unattended gauntlet or glove', NULL, NULL, '10 minutes/level', 'None (harmless, object)', 'no', 'You animate the target of the spell, manipulating the glove with your own hand from a distance. The glove moves as you direct it with a fly speed of 30 feet and average maneuverability. Directing the glove is a standard action, though the glove can move up to its speed and perform a task in the same action. You can attempt Disable Device and Sleight of Hand checks using the glove, though attempting these checks at a distance increases the normal skill check DCs by 5, or by 20 if you do not have line of sight to the object you are manipulating. The glove can also lift or drag objects using your caster level as your Strength score. The glove cannot wield weapons or make attacks effectively while this spell is in effect. If you cast this spell on a magical glove, its innate magic is suppressed for the duration of the spell.', NULL, NULL, false, false),
  ('deja_vu', 'Deja Vu', 'enchantment', 'compulsion', 'mind-affecting', 1, 'arcane', 'bard 1, mesmerist 1, psychic 1, sorcerer/wizard 1', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one creature', NULL, NULL, '2 rounds', 'none', 'yes', 'You reach into the target’s mind and put its thought processes into a temporary loop. Whatever full-round, standard, or move actions the creature takes on its first turn after you cast this spell, it must repeat on the turn after that. The creature must take the same type of actions in the same order (for example, making a full attack, casting a specific spell, withdrawing, attempting a bull rush combat maneuver, or activating a magic item) and must act against the same target or targets, but doesn’t have to make exactly the same choices (such as using Power Attack when attacking, moving exactly 15 feet, or choosing “drop” for the command spell). If the circumstances would prevent the target from repeating an action, such as if the target of its attack is dead or the target cannot cast the same spell again, the target instead becomes confused until the spell ends. A creature currently affected by deja vu can’t be targeted with another deja vu spell. A creature affected by deja vu can’t delay, and if it readies an action on its first turn, it must ready the same action on its second turn.', NULL, NULL, false, false),
  ('delay_disease', 'Delay Disease', 'conjuration', 'healing', NULL, 1, 'both', 'alchemist 2, cleric 2, druid 2, inquisitor 2, paladin 2, ranger 2, witch 1', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 day', 'Fort negates (harmless)', 'yes (harmless)', 'The target becomes temporarily immune to disease. Any disease to which it is exposed during the spell’s duration does not affect the target until the spell’s duration has expired. If the target is currently infected with a disease, you must make a caster level check against the disease’s DC to suspend it for the duration of the spell; otherwise, that disease affects the target normally. Delay disease does not cure any damage a disease may have already done.', NULL, NULL, true, false),
  ('delay_pain', 'Delay Pain', 'enchantment', NULL, 'emotion', 1, 'both', 'bard 2, cleric/oracle 2, bloodrager 2, inquisitor 2, psychic 2, sorcerer/wizard 2, witch 2; Subdomain kyton (evil, law) 1', NULL, 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 hour/level', 'Will negates; Spell resistance yes', NULL, 'You override the target’s ability to feel pain. Pain effects (such as pain strike and symbol of pain) do not affect the target until this spell’s duration has expired. This does not negate any physical damage, ability damage, or ability drain that a pain effect has already done, but it does negate ongoing penalties from pain while the spell lasts.', NULL, NULL, false, false),
  ('delay_poison', 'Delay Poison', 'conjuration', 'healing', NULL, 1, 'both', 'alchemist 2, bard 2, cleric/oracle 2, druid 2, inquisitor 2, paladin 2, ranger 1, shaman 2, witch 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 hour/level', 'Fortitude negates (harmless)', 'yes (harmless)', 'The subject becomes temporarily immune to poison. Any poison in its system or any poison to which it is exposed during the spell’s duration does not affect the subject until the spell’s duration has expired. Delay poison does not cure any damage that poison may have already done.', NULL, NULL, true, false),
  ('delayed_blast_fireball', 'Delayed Blast Fireball', 'evocation', NULL, 'fire', 7, 'arcane', 'sorcerer/wizard 7; Subdomain arson 7; Elemental School fire 7', NULL, NULL, NULL, NULL, NULL, '5 rounds or less; see text', NULL, NULL, 'This spell functions like fireball, except that it is more powerful and can detonate up to 5 rounds after the spell is cast. The burst of flame deals 1d6 points of fire damage per caster level (maximum 20d6). The glowing bead created by delayed blast fireball can detonate immediately if you desire, or you can choose to delay the burst for as many as 5 rounds. You select the amount of delay upon completing the spell, and that time cannot change once it has been set unless someone touches the bead. If you choose a delay, the glowing bead sits at its destination until it detonates. A creature can pick up and hurl the bead as a thrown weapon (range increment 10 feet). If a creature handles and moves the bead within 1 round of its detonation, there is a 25% chance that the bead detonates while being handled.', NULL, NULL, false, false),
  ('delayed_consumption', 'Delayed Consumption', 'transmutation', NULL, NULL, 5, 'arcane', 'alchemist 5', '1 standard action', 'personal', NULL, NULL, NULL, '1 day/level (D) or until discharged', NULL, NULL, 'When you consume this extract, you quickly consume another extract of your choice-this second extract’s effects do not come into effect until a later point. You must consume this second, companion extract on the round following delayed consumption or waste the extract. The companion extract can be no higher than 4th level, and you must pay any costs associated with the companion extract when you consume it.', NULL, NULL, false, false),
  ('delectable_flesh', 'Delectable Flesh', 'transmutation', NULL, 'mind-affecting, polymorph', 6, 'both', 'druid 7, shaman 7, sorcerer/wizard 6, witch 6', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 minute/level (D)', 'Will negates', 'yes', 'Choose a creature within range as the object of hunger. All other creatures within 15 feet of the target that can see or smell the target’s delectable flesh must succeed at a Will save or spiral into a depraved state from which they gain a single purpose—to consume as much of the target’s delicious flesh as possible. the creature chosen as the target of this spell is not affected by this depravity.', NULL, NULL, false, false),
  ('delusional_pride', 'Delusional Pride', 'enchantment', 'compulsion', 'emotion, mind-affecting', 1, 'arcane', 'bard 1, psychic 1, sorcerer/wizard 1, witch 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 minute', 'Will negates; Spell resistance yes', NULL, 'The target becomes so distracted by an overblown sense of its worth that it takes a –2 penalty on attacks and skill checks. However, this feeling also gives the target a +2 morale bonus on saves against charm and compulsion effects.', NULL, NULL, false, false),
  ('demand', 'Demand', 'enchantment', 'compulsion', 'mind-affecting', 8, 'arcane', 'sorcerer/wizard 8, witch 8; Domain charm 8, nobility 8; Subdomain torture 8', '10 Minutes standard action', 'See Description', '1 Creature', NULL, NULL, '1 round', 'Will partial', 'yes', 'This spell functions like sending, but the message can also contain a suggestion (see the suggestion spell), which the subject does its best to carry out. A successful Will save negates the suggestion effect but not the contact itself. The demand, if received, is understood even if the subject’s Intelligence score is as low as 1. If the message is impossible or meaningless according to the circumstances that exist for the subject at the time the demand is issued, the message is understood but the suggestion is ineffective.', 'fine copper wire', NULL, true, false),
  ('demand_offering', 'Demand Offering', 'enchantment', 'compulsion', 'mind-affecting', 1, 'both', 'antipaladin 1, bard 2, inquisitor 2, mesmerist 1, occultist 2, psychic 2, sorcerer/wizard 2, witch 2', '1 standard action', '5 ft.', 'one creature', NULL, NULL, 'instantaneous or 1 round', 'Will negates', 'yes', 'A creature that fails its save uses an immediate action to hand you whatever object it’s currently wielding or holding. If the target doesn’t have an immediate action available, it uses a move action at the beginning of its next turn to hand you the object. If it’s currently holding or wielding more than one item, determine randomly which item it gives you. If you’re no longer adjacent to the creature when it has to give you the item, the spell ends with no effect. A creature that isn’t holding an item when you cast this spell is unaffected.', NULL, NULL, false, false),
  ('demanding_message', 'Demanding Message', 'enchantment', 'compulsion', 'language-dependent, mind-affecting', 3, 'arcane', 'bard 3, medium 3, mesmerist 3, occultist 4, psychic 3, sorcerer/wizard 4, witch 4', NULL, NULL, NULL, NULL, NULL, '10 minutes/level, then 1 hour/level or until completed (D); see text', 'Will negates (see text)', 'yes; see text', 'This spell initially functions as message (allowing no save or spell resistance). Once during the message effect, you can concentrate as a standard action to issue a suggestion to one target as part of delivering a message. Spell resistance and a Will save apply to the suggestion, and it lasts for 1 hour per level or until completed.', NULL, NULL, false, false),
  ('denounce', 'Denounce', 'enchantment', 'compulsion', 'language-dependent, mind-affecting', 4, 'both', 'bard 4, inquisitor 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, '30-ft.-radius burst', NULL, '1 hour/level', 'Will negates', 'yes', 'You speak out against a single creature within line of sight and turn possible allies against it by drawing upon the power of your voice and conviction. Creatures in the area who can see the denounced creature must make a Will Saving Throw or have their starting attitude toward the denounced creature worsened by two levels (see Diplomacy skill or table on this page for details). For example, creatures previously indifferent to the subject turn unfriendly.', NULL, NULL, false, false),
  ('depilate', 'Depilate', 'necromancy', NULL, NULL, 1, 'both', 'bard 1, druid 1, sorcerer/wizard 1, witch 1', '1 round', 'medium (100 ft. + 10 ft./level)', 'one creature with hair or fur', NULL, NULL, 'instantaneous', 'Will negates', 'yes', 'This simple jinx causes a target’s hair or fur to fall out in patchy clumps, leaving the creature disheveled and less commanding.', 'a sliver of cow’s tongue', NULL, false, false),
  ('desecrate', 'Desecrate', 'evocation', NULL, 'evil', 2, 'divine', 'antipaladin 2, cleric/oracle 2, inquisitor 2', '1 standard actionComponent V, S, M (a vial of unholy water and 25 gp worth (5 pounds) of silver dust, all of which must be sprinkled around the area), DF', 'close (25 ft. + 5 ft./2 levels)', NULL, '20-ft.-radius emanation', NULL, '2 hours/level', 'none', 'yes', 'This spell imbues an area with negative energy. The DC to resist negative channeled energy within this area gains a +3 profane bonus. Every undead creature entering a desecrated area gains a +1 profane bonus on all attack rolls, damage rolls, and saving throws. An undead creature created within or summoned into such an area gains +1 hit points per HD.', 'a vial of unholy water and 25 gp worth (5 pounds', NULL, true, true),
  ('desperate_weapon', 'Desperate Weapon', 'conjuration', 'creation', NULL, 1, 'both', 'antipaladin 1, bard 1, bloodrager 1, cleric 1, inquisitor 1, magus 1, occultist 1, ranger 1, sorcerer/wizard 1', '1 swift action', 'personal', NULL, NULL, 'one-handed improvised weapon', '1 minute/level', 'none', 'no', 'You create a one-handed object that you might expect to see in your current surroundings, which you can then use as an improvised weapon. The spell conjures such an object near your hand such that you can retrieve it as you complete the spell.', NULL, NULL, false, false),
  ('destablize_powder', 'Destablize Powder', 'transmutation', NULL, NULL, 2, 'arcane', 'sorcerer/wizard 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', '1 loaded firearm', NULL, NULL, 'instantaneous', 'Will negates (object)', 'yes (object)', 'This spell makes the ammunition in the target firearm is prone to misfire. Increase the misfire range by 1 + 1 per five caster levels (maximum +5) for the ammunition currently loaded into that firearm. If aware of this spell’s effect prior to firing the altered ammunition (a DC 17 Spellcraft check to identify the spell being cast or similar effect), the firearm’s user can spend a standard action to clear the altered ammunition from the firearm. Doing so destroys that ammunition.', 'a few drops of liquor', NULL, false, false),
  ('destroy_robot', 'Destroy Robot', 'transmutation', NULL, NULL, 5, 'both', 'druid 5, sorcerer/wizard 6', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one robot (see below)', NULL, NULL, 'instantaneous', 'Fortitude partial', 'yes', 'You attempt to destroy any one robot in range. When you cast this spell, your hand crackles with electricity.', NULL, NULL, true, false),
  ('destruction', 'Destruction', 'necromancy', NULL, 'death', 7, 'divine', 'cleric/oracle 7, shaman 8, witch 8; Domain death 7, repose 7; Subdomain entropy 7; Mystery reaper 7', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'instantaneous', 'Fortitude partial', 'yes', 'This spell instantly delivers 10 points of damage per caster level. If the spell slays the target, it consumes the remains utterly in holy (or unholy) fire (but not its equipment or possessions). If the target’s Fortitude saving throw succeeds, it instead takes 10d6 points of damage. The only way to restore life to a character who has failed to save against this spell (and was slain) is to use true resurrection, a carefully worded wish spell followed by resurrection, or miracle.', NULL, 'holy or unholy symbol costing 500 gp', false, true),
  ('detect_aberration', 'Detect Aberration', 'divination', NULL, NULL, 1, 'both', 'druid 1, psychic 1, ranger 1', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, 'cone-shaped emanation', NULL, 'concentration, up to 10 minutes/level (D)', 'none', 'no', 'This spell functions like detect animals or plants, except it detects creatures of the aberration type.', NULL, NULL, false, false),
  ('detect_animals_or_plants', 'Detect Animals or Plants', 'divination', NULL, NULL, 1, 'both', 'druid 1, psychic 1, ranger 1, shaman 1', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, 'cone-shaped emanation', NULL, 'concentration, up to 10 min./level (D)', 'none', 'no', 'You can detect a particular kind of animal or plant in a cone emanating out from you in whatever direction you face. You must think of a kind of animal or plant when using the spell, but you can change the animal or plant kind each round. The amount of information revealed depends on how long you search a particular area or focus on a specific kind of animal or plant.', NULL, NULL, false, false),
  ('detect_anxieties', 'Detect Anxieties', 'divination', NULL, 'mind-affecting', 2, 'both', 'antipaladin 2, bard 3, cleric 3, inquisitor 3, medium 2, mesmerist 2, paladin 3, psychic 2, sorcerer/wizard 3, spiritualist 3, witch 3', '1 standard action', '60 ft.', NULL, 'cone-shaped emanation', NULL, 'concentration, up to 1 minute/level (D)', 'Will negates (see text)', 'no', 'This spell functions as detect thoughts except that you sense significant anxieties of creatures with an Intelligence score of 1 or higher, regardless of whether they are conscious or not.', NULL, NULL, true, false),
  ('detect_chaos', 'Detect Chaos', 'divination', NULL, NULL, 1, 'divine', 'cleric/oracle 1, inquisitor 1, shaman 1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions like detect evil, except that it detects the auras of chaotic creatures, clerics of chaotic deities, chaotic spells, and chaotic magic items, and you are vulnerable to an overwhelming chaotic aura if you are lawful.', NULL, NULL, false, false),
  ('detect_charm', 'Detect Charm', 'divination', NULL, NULL, 1, 'both', 'bard 1, cleric 1, inquisitor 1, medium 1, mesmerist 1, occultist 1, paladin 1, psychic 1, shaman 1, sorcerer/wizard 1, spiritualist 1, witch 1', '1 standard action', '60 ft.', NULL, 'cone-shaped emanation', NULL, 'concentration, up to 1 minute/level (D)', 'none', 'no', 'This spell functions as per detect magic, except that it detects only charm, compulsion, and possession effects. You immediately detect the strength and location of each such aura on all creatures in the area. You can attempt to identify the properties of each aura (see Spellcraft). In addition to noticing the targets of these effects, you can recognize when creatures in the area are using these effects on others by attempting a Sense Motive check as a standard action (DC = 20 + caster level). If you succeed, you can attempt a Spellcraft check to identify what magic it is using (even if the target is not in the area).', NULL, NULL, false, false),
  ('detect_demon', 'Detect Demon', 'divination', NULL, NULL, 1, 'divine', 'cleric 1, inquisitor 1, paladin 1', '1 standard action', '60 ft.', NULL, 'cone-shaped emanation', NULL, 'concentration, up to 10 minutes/level (D)', 'none (see text)', 'no', 'You sense the presence of a specific kind of evil—that of demons, their servants, and the Abyss. The amount of information revealed depends on how long you study a particular area or subject.', NULL, NULL, true, false),
  ('detect_desires', 'Detect Desires', 'divination', NULL, 'mind-affecting', 2, 'both', 'antipaladin 2, bard 2, cleric 3, inquisitor 3, medium 2, mesmerist 3, paladin 3, psychic 2, sorcerer/wizard 3, spiritualist 3, witch 3', '1 standard action', '60 ft.', NULL, 'cone-shaped emanation', NULL, 'concentration, up to 1 minute/level (D)', 'Will negates (see text)', 'no', 'This spell functions as detect thoughts, except you sense significant desires of creatures with an Intelligence score of 1 or higher, regardless of whether they are conscious or not.', NULL, NULL, true, false),
  ('detect_evil', 'Detect Evil', 'divination', NULL, NULL, 1, 'divine', 'cleric/oracle 1, inquisitor 1, shaman 1', '1 standard action Component V, S, DF', '60 ft.', NULL, 'cone-shaped emanation', NULL, 'concentration, up to 10 min./ level (D)', 'none', 'no', 'You can sense the presence of evil. The amount of information revealed depends on how long you study a particular area or subject.', NULL, NULL, true, false),
  ('detect_fiendish_presence', 'Detect Fiendish Presence', 'divination', NULL, NULL, 0, 'both', 'bard 0, cleric 0, magus 0, sorcerer/wizard 0, witch 0', '1 standard action', '60 ft.', NULL, 'cone-shaped emanation', NULL, 'concentration, up to 10 minutes/level (D)', 'none', 'no', 'This spell functions like detect evil, except that it detects only outsiders with the evil subtype, as well as the lingering effects caused by their gifts, presence, and spells. It can also detect clerics and paladins of fiendish deities, including Asmodeus, archdevils, daemonic harbingers, and demon lords.', NULL, NULL, false, false),
  ('detect_good', 'Detect Good', 'divination', NULL, NULL, 1, 'divine', 'cleric/oracle 1, inquisitor 1, shaman 1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions like detect evil, except that it detects the auras of good creatures, clerics or paladins of good deities, good spells, and good magic items, and you are vulnerable to an overwhelming good aura if you are evil.', NULL, NULL, false, false),
  ('detect_law', 'Detect Law', 'divination', NULL, NULL, 1, 'divine', 'cleric/oracle 1, inquisitor 1, shaman 1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions like detect evil, except that it detects the auras of lawful creatures, clerics of lawful deities, lawful spells, and lawful magic items, and you are vulnerable to an overwhelming lawful aura if you are chaotic.', NULL, NULL, false, false),
  ('detect_magic', 'Detect Magic', 'divination', NULL, NULL, 0, 'both', 'bard 0, cleric/oracle 0, druid 0, inquisitor 0, magus 0, psychic 0, shaman 0, sorcerer/wizard 0, summoner/unchained summoner 0, witch 0', '1 standard action Component: V, S', '60 ft.', NULL, 'cone-shaped emanation', NULL, 'concentration, up to 1 min./level (D)', 'none', 'no', 'You detect magical auras. The amount of information revealed depends on how long you study a particular area or subject.', NULL, NULL, false, false),
  ('detect_metal', 'Detect Metal', 'divination', NULL, NULL, 1, 'arcane', 'alchemist 1, bard 1, sorcerer/wizard 1, summoner 1', '1 standard action', '60 ft.', NULL, 'cone-shaped emanation', NULL, 'concentration, up to 1 minute/level (D)', 'none', 'no', 'You detect any metal objects or creatures within a 60-foot cone.', NULL, 'a magnetized nail or nugget of ore', false, false),
  ('detect_mindscape', 'Detect Mindscape', 'divination', NULL, NULL, 2, 'arcane', 'medium 2, mesmerist 2, psychic 2, sorcerer/wizard 3', '1 standard action', '60 ft.', NULL, 'cone-shaped emanation', NULL, 'concentration, up to 1 minute/level (D)', 'Will negates; see text', 'no', 'This spell functions similarly to detect thoughts, allowing you to sense when one or more creatures’ consciousnesses are inside a mindscape. The amount of information revealed depends on how long you study a particular subject.', NULL, NULL, false, false),
  ('detect_poison', 'Detect Poison', 'divination', NULL, NULL, 0, 'both', 'antipaladin 1, cleric/oracle 0, druid 0, inquisitor 0, paladin 1, psychic 0, ranger 1, shaman 0, sorcerer/wizard 0, witch 0', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'or', 'one creature, one object, or a 5-ft. cube', NULL, 'instantaneous', 'none', 'no', 'You determine whether a creature, object, or area has been poisoned or is poisonous. You can determine the exact type of poison with a DC 20 Wisdom check. A character with the Craft (alchemy) skill may try a DC 20 Craft (alchemy) check if the Wisdom check fails, or may try the Craft (alchemy) check prior to the Wisdom check. The spell can penetrate barriers, but 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt blocks it.', NULL, NULL, false, false),
  ('detect_psychic_significance', 'Detect Psychic Significance', 'divination', NULL, NULL, 0, 'arcane', 'medium 0, mesmerist 0, occultist 0, psychic 0, spiritualist 0', '1 standard action', '40 ft.', NULL, '40-ft.-radius burst, centered on you', NULL, 'instantaneous', 'none', 'no', 'You detect the presence of psychically significant items in your vicinity. Such items are those that might have significant psychic imprints or histories that can be read by the psychometry occult skill unlock, or items under the effects of the charge object or implant false reading spells. Items within range that contain significant psychic energy spark a recognition in your mind’s eye, but no other information is imparted. This spell doesn’t automatically detect magic items or strongly aligned items, though such items often have storied histories and might have had previous owners who possessed psychic abilities.', NULL, NULL, false, false),
  ('detect_radiation', 'Detect Radiation', 'divination', NULL, NULL, 1, 'both', 'bard 1, cleric 1, druid 1, ranger 1, sorcerer/wizard 1', '1 standard action', '120 ft.', NULL, 'spherical emanation, centered on you', NULL, NULL, NULL, NULL, 'You detect radiation in the surrounding area. You see radioactive auras as a glowing green shimmer in the air that emanates from radioactive objects; the brighter and more intense the green, the more powerful the radioactivity. This glow does not provide illumination or allow you to see in darkness, apart from being able to see the glow itself. The spell can penetrate barriers, but 3 feet of dirt or wood, 1 foot of stone, 1 inch of common metal, or a thin sheet of lead blocks it—although radiation can seep into such barriers, causing them to become radioactive (and thus visible to the spell) in time.', NULL, NULL, false, false),
  ('detect_relations', 'Detect Relations', 'divination', NULL, NULL, 2, 'both', 'bard 2, cleric 2, inquisitor 2, witch 2', NULL, NULL, NULL, NULL, NULL, 'concentration, up to 1 min./level (D)', 'Will negates; see text', 'no', 'You can determine whether or not two or more creatures are related by blood. The amount of information gleaned depends on how long you study a particular area or set of subjects.', NULL, NULL, false, false),
  ('detect_scrying', 'Detect Scrying', 'divination', NULL, NULL, 4, 'both', 'bard 4, inquisitor 4, shaman 4, sorcerer/wizard 4, witch 4; Subdomain solitude 4', '1 standard action', '40 ft.', NULL, '40-ft.-radius emanation centered on you', NULL, '24 hours', 'none', 'no', 'You immediately become aware of any attempt to observe you by means of a divination (scrying) spell or effect. The spell’s area radiates from you and moves as you move. You know the location of every magical sensor within the spell’s area.', 'a piece of mirror and a miniature brass hearing trumpet', NULL, false, false),
  ('detect_secret_doors', 'Detect Secret Doors', 'divination', NULL, NULL, 1, 'arcane', 'alchemist 1, bard 1, psychic 1, sorcerer/wizard 1, witch 1; Subdomain revelation 1', '1 standard action', '60 ft.', NULL, 'cone-shaped emanation', NULL, 'concentration, up to 1 min./level (D)', 'none', 'no', 'You can detect secret doors, compartments, caches, and so forth. Only passages, doors, or openings that have been specifically constructed to escape detection are detected by this spell. The amount of information revealed depends on how long you study a particular area or subject.', NULL, NULL, false, false),
  ('detect_snares_and_pits', 'Detect Snares and Pits', 'divination', NULL, NULL, 1, 'divine', 'druid 1, ranger 1', '1 standard action', '60 ft.', NULL, 'cone-shaped emanation', NULL, 'concentration, up to 10 min./level (D)', 'none', 'no', 'You can detect simple pits, deadfalls, and snares as well as mechanical traps constructed of natural materials. The spell does not detect complex traps, including trapdoor traps.', NULL, NULL, false, false),
  ('detect_the_faithful', 'Detect the Faithful', 'divination', NULL, NULL, 1, 'divine', 'antipaladin 1, cleric 1, druid 1, inquisitor 1, paladin 1, ranger 1, shaman 1', '1 standard action', '60 ft.', NULL, 'cone-shaped emanation', NULL, 'concentration, up to 1 minute/level (D)', 'none', 'no', 'You can detect other worshipers of your deity (mortal worshipers, outsider servants, and so on). The amount of information revealed depends on how long you focus on a particular area or subject.', NULL, NULL, true, false),
  ('detect_thoughts', 'Detect Thoughts', 'divination', NULL, 'mind-affecting', 1, 'both', 'alchemist 2, bard 2, inquisitor 2, psychic 1, sorcerer/wizard 2, summoner/unchained summoner 2, witch 2; Domain knowledge 2; Mystery streets 2', '1 standard action', '60 ft.', NULL, 'cone-shaped emanation', NULL, 'concentration, up to 1 min./level (D)', 'Will negates; see text', 'no', 'You detect surface thoughts. The amount of information revealed depends on how long you study a particular area or subject.', NULL, NULL, true, false),
  ('detect_undead', 'Detect Undead', 'divination', NULL, NULL, 1, 'both', 'alchemist 1, cleric/oracle 1, inquisitor 1, paladin 1, psychic 1, shaman 1, sorcerer/wizard 1; Mystery life 1', '1 standard action', '60 ft.', NULL, 'cone-shaped emanation', NULL, 'concentration, up to 1 minute/ level (D)', 'none', 'no', 'You can detect the aura that surrounds undead creatures. The amount of information revealed depends on how long you study a particular area.', 'earth from a grave', NULL, true, false),
  ('determine_depth', 'Determine Depth', 'divination', NULL, NULL, 2, 'both', 'bard 2, druid 2, sorcerer/wizard 2', '1 standard action', 'touch', 'solid surface touched', NULL, NULL, 'concentration, up to 1 round/level (D)', 'none', 'no', 'With a touch, you can determine the exact thickness of a wall, ceiling, or other solid barrier, measuring from the point you are touching to the direct opposite side of the barrier in a straight line. You can only detect depths or widths of up to 10 feet per caster level (maximum 200 feet at 20th level); amounts in excess of this limit are detected as being the maximum you are able to detect. So, for example, a 5th-level wizard using this spell on a 60-foot-thick wall would detect that the wall is 50 feet thick.', NULL, NULL, false, false),
  ('detonate', 'Detonate', 'evocation', NULL, 'acid, cold, electricity, or fire', 4, 'arcane', 'alchemist 4, bloodrager 4, magus 4, sorcerer/wizard 4; Elemental School air 4, earth 4, fire 4, water 4', '1 standard action', '30 ft.', NULL, '30-ft.-radius spread centered on you', NULL, '1 round, then instantaneous', 'Reflex half', 'yes', 'You flood yourself with a potent surge of elemental energy.', 'two vials; one containing acid and one containing an alkaline solution worth a total of 50 gp', NULL, false, true),
  ('detoxify', 'Detoxify', 'transmutation', NULL, NULL, 2, 'both', 'cleric 3, druid 3, inquisitor 3, paladin 3, ranger 2, shaman 3, witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '10 minutes/level', 'Fort negates', 'yes', 'You remove a creature’s ability to poison others, whether inherent or via poisoned weapons. Whenever an affected creature would inflict poison with an attack, spell, or other method (including auras and other constant methods), that poison is automatically neutralized. This does not grant the subject of the spell any resistance to poison itself.', 'a dandelion stem', NULL, false, false),
  ('devil_snare', 'Devil Snare', 'abjuration', NULL, 'good', 4, 'both', 'cleric 4, sorcerer/wizard 5', '1 full-round action', 'touch', NULL, NULL, '10-ft.-radius circle', '1 round/level', 'Will negates; see text', 'yes; see text', 'Your touch creates an invisible circle on a flat surface.', 'a pouch of silvered powder worth 25 gp', NULL, false, true),
  ('devolution', 'Devolution', 'transmutation', NULL, NULL, 3, 'arcane', 'psychic 3, sorcerer/wizard 3, summoner/unchained summoner 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 round/level', 'Will negates', 'yes', 'This spell causes an eidolon to lose one evolution plus one additional evolution for every five caster levels. Evolutions with the highest total cost are lost first. If there is a tie, randomly determine which is lost. If this spell causes an eidolon to fail to meet the prerequisites for other evolutions or abilities, those evolutions or abilities are lost as long as this spell persists.', 'a chameleon scale', NULL, false, false),
  ('diagnose_disease', 'Diagnose Disease', 'divination', NULL, NULL, 1, 'both', 'cleric/oracle 1, druid 1, paladin 1, psychic 1, ranger 1, witch 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'or', 'one creature, one object, or a 5-ft. cube', NULL, 'instantaneous', 'none; Spell resistance no', NULL, 'You determine whether a creature, object, or area carries any sort of disease or infestation (including molds, slimes, and similar hazards), or any exceptional or supernatural effects causing the sickened or nauseated effects. If there is disease present, you know what disease it is and its effects. If the target is a creature, you gain a +4 bonus on Heal checks to treat the creature’s disease. The spell can penetrate many barriers, but 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt blocks it.', NULL, NULL, false, false),
  ('diamond_spray', 'Diamond Spray', 'evocation', NULL, 'earth', 3, 'arcane', 'sorcerer/wizard 3', '1 standard action', '20 ft.', NULL, 'cone-shaped burst', NULL, 'instantaneous', 'Reflex half', 'yes', 'A cone of tiny, sparkling slivers as hard and sharp as fled diamonds springs from your outstretched fingers at tremendous speed. Any creature in the area of the torrent takes 1d6 points of slashing damage per caster level (maximum 10d6). These magical slivers are treated as adamantine and cold iron for the purpose of overcoming damage reduction. In addition, this spell bypasses up to 1 point of an object’s hardness per 2 caster levels (maximum 10).', 'a lump of coal', NULL, false, false),
  ('dictum', 'Dictum', 'evocation', NULL, 'lawful, sonic', 7, 'divine', 'cleric/oracle 7, inquisitor 6; Domain law 7; Mystery godclaw 7', '1 standard action', '40 ft.', NULL, 'nonlawful creatures in a 40-ft.-radius spread centered on you', NULL, 'instantaneous', 'none or Will negates; see text', 'yes', 'Any nonlawful creature within the area of a dictum spell suffers the following ill effects.', NULL, NULL, false, false),
  ('die_for_your_master', 'Die for Your Master', 'enchantment', 'compulsion', NULL, 4, 'both', 'antipaladin 4, druid 5, sorcerer/wizard 5, witch 5', '1 immediate action', 'touch', 'your animal companion, familiar, or fiendish servant', NULL, NULL, 'instantaneous', 'none', 'no', 'This spell allows your companion or familiar to intercept any attack that targets you, including those that do not require attack rolls (e.g., chain lightning, hold monster, and magic missile).', NULL, NULL, false, false),
  ('dimension_door', 'Dimension Door', 'conjuration', 'teleportation', NULL, 3, 'arcane', 'bard 4, magus 4, sorcerer/wizard 4, summoner 3, unchained summoner 4, witch 4; Domain travel 4; Bloodline arcane 4; Mystery solar 4', '1 standard action', 'long (400 ft. + 40 ft./level)', 'you and touched objects or other touched willing creatures', NULL, NULL, 'instantaneous', 'none and Will negates (object)', 'no and yes (object)', 'You instantly transfer yourself from your current location to any other spot within range. You always arrive at exactly the spot desired – whether by simply visualizing the area or by stating direction. After using this spell, you can’t take any other actions until your next turn. You can bring along objects as long as their weight doesn’t exceed your maximum load. You may also bring one additional willing Medium or smaller creature (carrying gear or objects up to its maximum load) or its equivalent per three caster levels. A Large creature counts as two Medium creatures, a Huge creature counts as two Large creatures, and so forth. All creatures to be transported must be in contact with one another, and at least one of those creatures must be in contact with you.', NULL, NULL, false, false),
  ('dimensional_anchor', 'Dimensional Anchor', 'abjuration', NULL, NULL, 3, 'both', 'cleric/oracle 4, inquisitor 3, sorcerer/wizard 4, summoner 3, unchained summoner 4; Subdomain wards 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'ray', '1 min./level', 'none', 'yes (object)', 'A green ray springs from your hand. You must make a ranged touch attack to hit the target. Any creature or object struck by the ray is covered with a shimmering emerald field that completely blocks extradimensional travel. Forms of movement barred by a dimensional anchor include astral projection, blink, dimension door, ethereal jaunt, etherealness, gate, maze, plane shift, shadow walk, teleport, and similar spell-like abilities. The spell also prevents the use of a gate or teleportation circle for the duration of the spell.', NULL, NULL, false, false),
  ('dimensional_blade', 'Dimensional Blade', 'transmutation', NULL, NULL, 4, 'both', 'antipaladin 4, bloodrager 4, cleric 6, inquisitor 5, magus 5, paladin 4, sorcerer/wizard 6', '1 swift action', 'personal', 'you', NULL, NULL, '1 round', NULL, NULL, 'This spell gives you the power to turn one melee weapon in your hand into a two-dimensional object with length and height but no width. A sword becomes a flat image of a sword, a mace is reduced to a flat outline, and so on. The magic of the spell allows the weapon to be wielded by you normally, creating just enough depth to grasp it.', NULL, NULL, false, false),
  ('dimensional_bounce', 'Dimensional Bounce', 'conjuration', 'teleportation', NULL, 6, 'arcane', 'sorcerer/wizard 7, summoner/unchained summoner 6, witch 7', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 round/level or until discharged', 'none and Will negates (object)', 'no and yes (object)', 'You designate two locations within range and create a dimensional link between them; you must have line of effect to both locations when casting this spell. As a swift action, you can teleport from your current location to either of the designated locations as if you had cast dimension door. The spell is discharged once you have used it to teleport a number of times equal to one-fourth your caster level (maximum 5 times).', NULL, NULL, false, false),
  ('dimensional_lock', 'Dimensional Lock', 'abjuration', NULL, NULL, 6, 'both', 'cleric/oracle 8, sorcerer/wizard 8, summoner 6, Bloodline accursed 8', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, '20-ft.-radius emanation centered on a point in space', NULL, '1 day/level', 'none', 'yes', 'You create a shimmering emerald barrier that completely blocks extradimensional travel. Forms of movement barred include astral projection, blink, dimension door, ethereal jaunt, etherealness, gate, maze, plane shift, shadow walk, teleport, and similar spell-like abilities. Once dimensional lock is in place, extradimensional travel into or out of the area is not possible.', NULL, NULL, false, false),
  ('diminish_plants', 'Diminish Plants', 'transmutation', NULL, NULL, 3, 'divine', 'druid 3, ranger 3', '1 standard action', 'see text', 'or', 'see text', NULL, 'instantaneous', 'none', 'no', 'This spell has two versions.', NULL, NULL, true, false),
  ('diminish_resistance', 'Diminish Resistance', 'transmutation', NULL, NULL, 2, 'both', 'bard 2, cleric 2, inquisitor 2, magus 2, mesmerist 2, psychic 2, sorcerer/wizard 2, witch 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one creature', NULL, NULL, '1 round/level (D)', 'Fort negates', 'yes', 'You weaken a creature’s resistance against one energy type you select: acid, cold, electricity, fire, or sonic. The creature’s resistance to that energy type decreases by 5 (minimum 0), plus an additional 5 for every 5 caster levels beyond 3rd (to a maximum of 20 at 18th level).', 'a pinch of coarse sand', NULL, true, false),
  ('diminished_detection', 'Diminished Detection', 'abjuration', NULL, NULL, 2, 'arcane', 'alchemist 2, bard 2, sorcerer/wizard 2, witch 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 hour/level', NULL, NULL, 'You can avoid being detected when you are on the edges of some divination spells’ ranges. Whenever you would normally be within the area of effect of a detection spell (such as detect magic, detect evil, or detect undead), the area of effect is reduced by half for the purposes of the spell’s caster detecting you or your possessions. The caster of the detect spell is unaware of this reduction in her spell’s range; she simply does not detect you.', 'a piece of wool', NULL, false, false),
  ('dirge_of_the_victorious_knights', 'Dirge of the Victorious Knights', 'illusion', 'shadow', NULL, 6, 'arcane', 'bard 6', '1 round', '120 ft.', NULL, NULL, '120-ft. line, 10 ft. wide', 'instantaneous', 'Reflex half', 'yes', 'By performing part of an opera, you call forth spectral illusions of mounted knights to trample your foes under the hooves of their glorious steeds.', NULL, 'a medal from a dead Hellknight or a copy of an opera script, either worth at least 100 gp', false, true),
  ('disable_construct', 'Disable Construct', 'transmutation', NULL, NULL, 3, 'arcane', 'alchemist 3, sorcerer/wizard 3, witch 3', '1 standard action', 'touch', 'construct touched', NULL, NULL, '1 round/level (D)', 'Will negates', 'no', 'You can make a melee touch attack to send a pulse into the target, interfering with the magic that endows it with life. If the construct fails its saving throw, it becomes helpless, but it receives a new save each round at the end of its turn to shake off the effect. If the construct is normally immune to magic, the pulse is less effective and the construct receives a +4 bonus on its saving throw.', NULL, NULL, false, false),
  ('discern_lies', 'Discern Lies', 'divination', NULL, NULL, 3, 'both', 'alchemist 4, cleric/oracle 4, inquisitor 4, paladin 3, witch 4; Domain nobility 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, 'concentration, up to 1 round/level', 'Will negates', 'no', 'Each round, you concentrate on one target, who must be within range. You know if the target deliberately and knowingly speaks a lie by discerning disturbances in its aura caused by lying. The spell does not reveal the truth, uncover unintentional inaccuracies, or necessarily reveal evasions.', NULL, NULL, true, false),
  ('discern_location', 'Discern Location', 'divination', NULL, NULL, 6, 'both', 'cleric/oracle 8, shaman 8, sorcerer/wizard 8, summoner 6, witch 8; Domain knowledge 8', '10 minutes', 'unlimited', 'one creature or object', NULL, NULL, 'instantaneous', 'none', 'no', 'A discern location spell is among the most powerful means of locating creatures or objects. Nothing short of a mind blank spell or the direct intervention of a deity keeps you from learning the exact location of a single individual or object. Discern location circumvents normal means of protection from scrying or location. The spell reveals the name of the creature or object’s location (place, name, business name, building name, or the like), community, county (or similar political division), country, continent, and the plane of existence where the target lies.', NULL, NULL, true, false),
  ('discern_next_of_kin', 'Discern Next of Kin', 'divination', NULL, 'mind-affecting', 1, 'both', 'bard 1, psychic 1, shaman 1, sorcerer/wizard 1, witch 1', '1 standard action', '60 ft.', 'one creature', NULL, NULL, 'concentration, up to 1 minute/level (D)', 'Will negates (see text)', 'yes', 'You can scan the thoughts of one individual and learn the names and locations of the target’s living relatives, as well as the attitude of the target toward those relatives (and vice versa). You learn about one relative per round you concentrate on the target. For example, you might learn the target’s father’s name, that the father lives on a nearby farm, and that the target and his father don’t get along. Since this spell reads the target’s mind, you can learn only what the target knows or believes.', NULL, 'a copper piece', false, false),
  ('discern_value', 'Discern Value', 'divination', NULL, NULL, 3, 'arcane', 'bard 3, sorcerer/wizard 3', '1 standard action', '60 ft.', NULL, 'cone-shaped emanation', NULL, 'concentration, up to 1 minute/level (D)', 'none', 'no', 'You can quickly analyze the monetary value of objects and identify which are most valuable to an average trader.', NULL, 'platinum monocle worth 100 gp', false, true),
  ('discharge', 'Discharge', 'abjuration', NULL, NULL, 3, 'both', 'bard 3, cleric 3, magus 3, sorcerer/wizard 3, witch 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one creature or technological object', NULL, NULL, 'instantaneous', 'Fort negates', 'no', 'Discharge dissipates the charges from one technical object, temporarily depowers one electrically powered technological object that does not use charges, or severely hinders a creature with the robot subtype. If the spell targets an object with charges, the object loses all of its remaining charges. If the object is powered by electrical means other than charges, its functions are suppressed for 1d4 rounds. If the spell targets a creature not of the robot subtype, it affects a random charged or electrically powered item in that creature’s possession. If the target is a robot, the robot is staggered and cannot use any energy-based attacks for 1d4 rounds. A robot that’s affected by this spell receives a new saving throw at the end of each round to shrug off the effect.', NULL, NULL, false, false),
  ('discordant_blast', 'Discordant Blast', 'evocation', NULL, 'sonic', 4, 'arcane', 'bard 4', '1 standard action', '10 ft. or 30 ft.', NULL, 'see text', NULL, 'instantaneous', 'none', 'yes', 'You create a wave of thunder and force, either in a 10-foot radius burst centered on you or in 30-foot cone-shaped burst.', NULL, NULL, false, false),
  ('discovery_torch', 'Discovery Torch', 'evocation', NULL, 'light', 2, 'both', 'bard 2, cleric 3, inquisitor 2', '1 round', 'touch', 'object touched', NULL, NULL, '10 minutes/level', 'none', 'no', 'An object you touch emanates a 20-foot radius of bright light. The effect looks like a regular flame but creates no heat and uses no oxygen. Allies within the area of this light gain a +2 enhancement bonus on Perception and Sense Motive checks, as well as on Knowledge checks to identify monsters that are also within the area and their special powers and vulnerabilities.', NULL, NULL, false, false),
  ('disfiguring_touch', 'Disfiguring Touch', 'transmutation', NULL, 'curse', 2, 'both', 'bloodrager 2, cleric/oracle 2, psychic 2, sorcerer/wizard 2, witch 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 day/level', 'Will negates; Spell resistance yes', NULL, 'With a touch, you cause the victim of this spell to suffer a painful curse that causes it to grow hideously disfigured.', NULL, NULL, false, false),
  ('disguise_other', 'Disguise Other', 'illusion', 'glamer', NULL, 2, 'both', 'bard 2, inquisitor 2, psychic 2, sorcerer/wizard 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '10 minute/level (D)', NULL, NULL, 'This spell functions as disguise self, except you can disguise either yourself or another creature.', NULL, NULL, false, false),
  ('disguise_self', 'Disguise Self', 'illusion', 'glamer', NULL, 1, 'both', 'alchemist 1, antipaladin 1, bard 1, inquisitor 1, psychic 1, sorcerer/wizard 1; Domain trickery 1; Bloodline div 1; Mystery streets 1', '1 standard action', 'personal', 'you', NULL, NULL, '10 min./level (D)', NULL, NULL, 'You make yourself – including clothing, armor, weapons, and equipment – look different. You can seem 1 foot shorter or taller, thin, fat, or in between. You cannot change your creature type (although you can appear as another subtype). Otherwise, the extent of the apparent change is up to you. You could add or obscure a minor feature or look like an entirely different person or gender.', NULL, NULL, false, false),
  ('disguise_weapon', 'Disguise Weapon', 'illusion', 'glamer', NULL, 1, 'arcane', 'bard 1, magus 1, psychic 1, sorcerer/wizard 1, witch 1', '1 round', 'touch', 'manufactured weapon touched', NULL, NULL, '1 hour/level (D)', 'none', 'no', 'You make one manufactured weapon look like a different manufactured weapon of the same size and relative encumbrance (light, one-handed, or two-handed). For example, you could make a Small greatsword look like a Small quarterstaff, a Medium club, or a Large dagger. Even the appearance of an improvised weapon is possible. The extent of the apparent change is up to you. You could add or obscure a minor feature or make the item look like it is composed of different materials (stone, wood, adamantine, and so on). The spell does not provide any of the abilities of the chosen form, nor does it alter the perceived tactile or audible properties of the item or how it is wielded. A creature that interacts with the glamer may attempt a Will save to recognize it as an illusion.', NULL, NULL, false, false),
  ('disintegrate', 'Disintegrate', 'transmutation', NULL, NULL, 6, 'arcane', 'magus 6, sorcerer/wizard 6; Domain destruction 7; Subdomain ash 7; Bloodline div 6; Elemental School metal 6; Mystery time 7', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'ray', 'instantaneous', 'Fortitude partial (object)', 'yes', 'A thin, green ray springs from your pointing finger.', 'a lodestone and a pinch of dust', NULL, true, false),
  ('dismissal', 'Dismissal', 'abjuration', NULL, NULL, 4, 'both', 'cleric/oracle 4, inquisitor 4, shaman 4, sorcerer/wizard 5, summoner 4, unchained summoner 5; Bloodline  abyssal 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one extraplanar creature', NULL, NULL, 'instantaneous', 'Will negates; see text', 'yes', 'This spell forces an extraplanar creature back to its proper plane if it fails a Will save. If the spell is successful, the creature is instantly whisked away, but there is a 20% chance of actually sending the subject to a plane other than its own.', NULL, NULL, true, false),
  ('dispel_balance', 'Dispel Balance', 'abjuration', NULL, NULL, 5, 'divine', 'cleric 5, inquisitor 5', '1 standard action', 'touch', 'you and a touched, neutral creature from another plane, or you and an enchantment on a touched creature or object', NULL, NULL, '1 round/level or until discharged, whichever comes first', 'see text', 'see text', 'Pulsing bronze energy surrounds you, bestowing three effects.', NULL, NULL, true, false),
  ('dispel_chaos', 'Dispel Chaos', 'abjuration', NULL, 'lawful', 4, 'divine', 'cleric/oracle 5, inquisitor 5, paladin 4, shaman 5; Domain law 5', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions like dispel evil, except that you are surrounded by constant, blue lawful energy, and the spell affects chaotic creatures and spells rather than evil ones.', NULL, NULL, false, false),
  ('dispel_evil', 'Dispel Evil', 'abjuration', NULL, 'good', 4, 'divine', 'cleric/oracle 5, inquisitor 5, paladin 4, shaman 5; Domain good 5', '1 standard action', 'touch', 'or Targets you and a touched evil creature from another plane, or you and an enchantment or evil spell on a touched creature or object', NULL, NULL, '1 round/level or until discharged, whichever comes first', 'see text', 'see text', 'Shimmering, white holy energy surrounds you. This energy has three effects.', NULL, NULL, true, false),
  ('dispel_good', 'Dispel Good', 'abjuration', NULL, 'evil', 4, 'divine', 'antipaladin 4, cleric/oracle 5, inquisitor 5, shaman 5; Domain evil 5', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions like dispel evil, except that you are surrounded by dark, wavering unholy energy, and the spell affects good creatures and spells rather than evil ones.', NULL, NULL, false, false),
  ('dispel_law', 'Dispel Law', 'abjuration', NULL, 'chaotic', 4, 'divine', 'antipaladin 4, cleric/oracle 5, inquisitor 5, shaman 5; Domain chaos 5', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions like dispel evil, except that you are surrounded by flickering, yellow chaotic energy, and the spell affects lawful creatures and spells rather than evil ones.', NULL, NULL, false, false),
  ('dispel_magic', 'Dispel Magic', 'abjuration', NULL, NULL, 3, 'both', 'antipaladin 3, bard 3, cleric/oracle 3, druid 4, inquisitor 3, magus 3, medium 3, mesmerist 3, occultist 3, paladin 3, psychic 3, shaman 3, sorcerer/wizard 3, spiritualist 3, summoner/unchained summoner 3, witch 3; Domain magic 3; Subdomain entropy 3; Bloodline arcane 3; Elemental School void 3; Mystery spellscar 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'or', 'one spellcaster, creature, or object', NULL, 'instantaneous', 'none', 'no', 'You can use dispel magic to end one ongoing spell that has been cast on a creature or object, to temporarily suppress the magical abilities of a magic item, or to counter another spellcaster’s spell. A dispelled spell ends as if its duration had expired. Some spells, as detailed in their descriptions, can’t be defeated by dispel magic. Dispel magic can dispel (but not counter) spell-like effects just as it does spells. The effect of a spell with an instantaneous duration can’t be dispelled, because the magical effect is already over before the dispel magic can take effect.', NULL, NULL, false, false),
  ('displacement', 'Displacement', 'illusion', 'glamer', NULL, 3, 'arcane', 'alchemist 3, bard 3, magus 3, medium 3, mesmerist 3, occultist 3, psychic 3, sorcerer/wizard 3, spiritualist 3, summoner/unchained summoner 3; Subdomain protean 3', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 round/level (D)', 'Will negates (harmless)', 'yes (harmless)', 'The subject of this spell appears to be about 2 feet away from its true location. The creature benefits from a 50% miss chance as if it had total concealment. Unlike actual total concealment, displacement does not prevent enemies from targeting the creature normally. True seeing reveals its true location and negates the miss chance.', 'a small loop of leather', NULL, false, false),
  ('display_aversion', 'Display Aversion', 'illusion', 'shadow', NULL, 2, 'both', 'bard 2, cleric/oracle 2, inquisitor 2, sorcerer/wizard 3, witch 2', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, NULL, 'visual figment that cannot extend beyond four 10-ft. cubes + one 10-ft. cube/level (S)', 'concentration + 1d4 rounds', 'Will disbelief (if interacted with)', 'no', 'This spell functions like minor image, except it always creates an animated illusion of you presenting to a vampire a material, object, or sound that it is averse to, such as garlic, a holy symbol, or bells ringing. You specify what aversion the illusion depicts when you cast the spell. The vampire reacts to the illusion as if it were real; it can overcome the effect by succeeding at a disbelief save or a normal Will save against the illusion’s DC (instead of the normal DC 25 to overcome its revulsion). The illusion is only quasireal and cannot otherwise affect creatures.', 'a drop of holy water', NULL, false, false),
  ('disrupt_link', 'Disrupt Link', 'abjuration', NULL, NULL, 2, 'both', 'antipaladin 2, bard 3, inquisitor 3, sorcerer/wizard 2, witch 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, NULL, '1 round/level', 'Will negates', 'yes', 'The target has her link with her bonded creature temporarily severed. If the subject has a familiar, she loses the benefits of the alertness, deliver touch spells, empathic link, scry on familiar, share spells, and speak with master abilities. If the target has an animal companion, she loses the benefits of the link, share spells, and devotion abilities. The target and her familiar or animal companion also lose any other abilities (such as those from archetypes or feats) that rely on the two having a connection.', NULL, NULL, false, false),
  ('disrupt_silence', 'Disrupt Silence', 'abjuration', NULL, NULL, 2, 'both', 'bard 2, cleric 3, inquisitor 3, psychic 3', '1 standard action', 'touch', NULL, '10-ft.-radius emanation centered on a creature, object, or point in space', NULL, '1 round/level (D)', 'Will negates', 'yes', 'You suppress magical sound-dampening effects within the area.', 'tiny silver bell, chime, or gong', NULL, false, false),
  ('disrupt_undead', 'Disrupt Undead', 'necromancy', NULL, NULL, 0, 'both', 'inquisitor 0, magus 0, sorcerer/wizard 0', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'ray', 'instantaneous', 'none', 'yes', 'You direct a ray of positive energy.', NULL, NULL, false, false),
  ('disrupting_weapon', 'Disrupting Weapon', 'transmutation', NULL, NULL, 5, 'divine', 'cleric/oracle 5, inquisitor 5', '1 standard action', 'touch', NULL, NULL, NULL, '1 round/level', 'Will negates (harmless, object); see text', 'yes (harmless, object)', 'This spell makes a melee weapon deadly to undead. Any undead creature with HD equal to or less than your caster level must succeed on a Will save or be destroyed utterly if struck in combat with this weapon. Spell resistance does not apply against the destruction effect.', NULL, NULL, false, false),
  ('dissolution', 'Dissolution', 'transmutation', NULL, NULL, 4, 'arcane', 'alchemist 4, sorcerer/wizard 5, spiritualist 6, summoner 6', '1 standard action', 'touch', 'Tiny or smaller object touched', NULL, NULL, '10 minutes/level (D)', 'Fort negates (object)', 'no', 'You touch a Tiny or smaller item, causing the item to vanish as if it did not exist at all. The item doesn’t take damage or otherwise gain any condition; it simply ceases to be visible to or interact with the world in any way, as if it no longer existed. The oil vanishes with the item and leaves no residue, nor does it affect surfaces that handle or hold the item during its application. No spell or ability short of miracle or wish can locate or affect the item while it is under the effect of this spell. Though the item seems to not exist while under the effects of this spell, its own reality is consistent (it ages normally, and any ongoing effects upon it continue normally). The target object can be one size larger than Tiny for every 5 caster levels above 5th you possess.', 'vial of alchemical reagents worth 50 gp', NULL, false, true),
  ('distracting_cacophony', 'Distracting Cacophony', 'evocation', NULL, 'sonic', 2, 'arcane', 'bard 2, psychic 3, sorcerer/wizard 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, '20-ft. spread', NULL, '1 round/level (D)', 'none; Spell resistance yes', NULL, 'The air fills with loud and discordant noise, making concentration difficult. Casting a spell in this area of cacophony requires a concentration check (DC 15 + the level of the spell being cast). Any other concentration checks in the area have their DCs increased by 5. The DC of Perception checks involving hearing is likewise increased by 5.', NULL, NULL, false, false),
  ('distressing_tone', 'Distressing Tone', 'evocation', NULL, 'sonic', 2, 'both', 'bard 2, inquisitor 2', '1 round', 'close (25 ft. + 5 ft./2 levels)', '1d4 living creatures', NULL, NULL, '1 round/level', 'Fortitude negates; Spell resistance yes', NULL, 'You create a powerful tone that vibrates living flesh.', NULL, NULL, false, false),
  ('divide_mind', 'Divide Mind', 'enchantment', NULL, 'mind-affecting', 9, 'arcane', 'psychic 9', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute', 'none', 'no', 'You partition your mind to maximize your mental power. Until the spell ends, you roll twice and use the higher result for all Will saves, Intelligence checks, and Intelligence-based skill checks. In addition, as a swift action you can have your second mind perform any purely mental action that normally requires a standard action or a move action. This includes casting psychic spells, using spell-like abilities, and concentrating on spells.', NULL, NULL, false, false),
  ('divination', 'Divination', 'divination', NULL, NULL, 4, 'divine', 'cleric/oracle 4, inquisitor 4, shaman 4, witch 4; Domain knowledge 4; Bloodline dreamspun 4', '10 minutes', 'personal', 'you', NULL, NULL, 'instantaneous', NULL, NULL, 'Similar to augury but more powerful, a divination spell can provide you with a useful piece of advice in reply to a question concerning a specific goal, event, or activity that is to occur within 1 week. The advice granted by the spell can be as simple as a short phrase, or it might take the form of a cryptic rhyme or omen. If your party doesn’t act on the information, the conditions may change so that the information is no longer useful. The base chance for a correct divination is 70% + 1% per caster level, to a maximum of 90%. If the die roll fails, you know the spell failed, unless specific magic yielding false information is at work.', 'incense and an appropriate offering worth 25 gp', NULL, false, true),
  ('divine_arrow', 'Divine Arrow', 'transmutation', NULL, 'good', 2, 'divine', 'paladin 2', '1 standard action', 'touch', 'one projectile', NULL, NULL, '1 round/level or until discharged', 'none', 'no', 'You imbue a projectile, such as an arrow or shuriken, with holy energy so that it deals extra damage to undead equal to that dealt by your lay on hands feature. This extra damage is not multiplied on a critical hit. Although this spell does not expend a daily use of your lay on hands class feature, you must have at least one daily use available to cast this spell. If the projectile hits a target or is destroyed before the duration ends, the spell is discharged.', NULL, NULL, false, false),
  ('divine_favor', 'Divine Favor', 'evocation', NULL, NULL, 1, 'divine', 'cleric/oracle 1, inquisitor 1, paladin 1; Domain nobility 1; Subdomain archon (good, law) 1', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute', NULL, NULL, 'Calling upon the strength and wisdom of a deity, you gain a +1 luck bonus on attack and weapon damage rolls for every three caster levels you have (at least +1, maximum +3). The bonus doesn’t apply to spell damage.', NULL, NULL, true, false),
  ('divine_illumination', 'Divine Illumination', 'conjuration', NULL, 'good, light', 2, 'divine', 'cleric 3, inquisitor 3, paladin 2', '1 minute', 'medium (100 ft. +5 ft./level)', NULL, NULL, NULL, '1 minute/level', 'Will partial', 'yes', 'With this spell, you create shafts of blue light that illuminate all undead creatures in the area. Affected undead take a –20 penalty on all Stealth checks. Invisible undead are not made visible by this effect, but the light does make it easy to pinpoint the exact squares in which such undead are located (they still retain the 50% miss chance granted by invisibility). This spell increases light levels by one step in a 5-foot radius around an affected undead creature. Once an undead is affected, it remains illuminated as long as remains within the spell’s range, even if it leaves the spell’s original radius, until the spell’s duration ends.', NULL, NULL, true, false),
  ('divine_power', 'Divine Power', 'evocation', NULL, NULL, 4, 'divine', 'cleric/oracle 4, inquisitor 4, shaman 4; Domain war 4', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level', NULL, NULL, 'Calling upon the divine power of your patron, you imbue yourself with strength and skill in combat. You gain a +1 luck bonus on attack rolls, weapon damage rolls, Strength checks, and Strength-based skill checks for every three caster levels you have (maximum +6). You also gain 1 temporary hit point per caster level. Whenever you make a full-attack action, you can make an additional attack at your full base attack bonus, plus any appropriate modifiers. This additional attack is not cumulative with similar effects, such as haste or weapons with the speed special ability.', NULL, NULL, true, false),
  ('divine_pursuit', 'Divine Pursuit', 'transmutation', NULL, NULL, 5, 'divine', 'inquisitor 5', '1 standard action component V, S', 'personal', 'you', NULL, NULL, '1 minute/level; see text', NULL, NULL, 'Select one creature within 60 feet that you have damaged. If that creature has a burrow, climb, fly, or swim speed, you gain that form of movement for the duration of the spell at the same speed and maneuverability as the selected creature. If this gives you the burrow or swim speed, you can breathe while burrowing or swimming. If the creature moves 1,000 feet or more from you, the spell ends. If the creature has more than one of these types of movement, you select one from the types available to the creature.', NULL, NULL, false, false),
  ('divine_transfer', 'Divine Transfer', 'necromancy', NULL, NULL, 3, 'divine', 'paladin 3', '1 standard action', 'touch', NULL, NULL, NULL, '1 round/level', 'Fortitude negates (harmless)', 'yes (harmless)', 'With a single touch, you transfer some of your life essence to the subject, transferring your hit points and your resolve. When you touch the subject you can transfer up to a number of hit points equal to your Constitution score to the target. These hit points heal the subject, but cannot raise the subject’s hit points higher than its normal hit point total. In addition, the subject gains damage reduction/evil equal to your Charisma bonus (if any) for the duration of the spell.', NULL, NULL, false, false),
  ('divine_trident', 'Divine Trident', 'evocation', NULL, 'electricity', 2, 'both', 'cleric 2, druid 2, witch 2', '1 standard action', '0 ft. trident-like bolt of electricity', NULL, NULL, NULL, '1 minute/level (D)', 'none', 'yes', 'A 4-foot-long, blazing, forked bolt of electricity springs forth from your hand. You wield this spear-like bolt as if it were a trident (you are considered proficient with the bolt). Attacks with the trident are melee touch attacks. The bolt deals 1d8 points of electricity damage + 1 point per 2 caster levels (maximum +10). Since the bolt is immaterial, your Strength modifier does not apply to the damage. The bolt can ignite combustible materials such as parchment, straw, dry sticks, and cloth.', NULL, NULL, true, false),
  ('divine_vessel', 'Divine Vessel', 'transmutation', NULL, 'chaotic, evil, good, or lawful', 8, 'divine', 'oracle 8', '1 standard action', 'personal', NULL, NULL, NULL, '1 round/level (D)', NULL, NULL, 'You accept otherworldly energies into your body and transform.', NULL, NULL, false, false),
  ('dominate_animal', 'Dominate Animal', 'enchantment', 'compulsion', 'mind-affecting', 3, 'divine', 'druid 3, shaman 3; Domain animal 3', '1 round', 'close (25 ft. + 5 ft./2 levels)', 'one animal', NULL, NULL, '1 round/level', 'Will negates', 'yes', 'This spell allows you to enchant the targeted animal and direct it with simple commands such as “Attack,” “Run,” and “Fetch.” Suicidal or self-destructive commands (including an order to attack a creature two or more size categories larger than the dominated animal) are simply ignored.', NULL, NULL, false, false),
  ('dominate_monster', 'Dominate Monster', 'enchantment', 'compulsion', 'mind-affecting', 6, 'arcane', 'sorcerer/wizard 9, summoner 6, witch 9; Domain charm 9', NULL, NULL, 'one creature', NULL, NULL, NULL, NULL, NULL, 'This spell functions like dominate person, except that the spell is not restricted by creature type.', NULL, NULL, false, false),
  ('dominate_person', 'Dominate Person', 'enchantment', 'compulsion', 'mind-affecting', 4, 'both', 'bard 4, mesmerist 4, shaman 5, sorcerer/wizard 5, witch 5; Subdomain slavery 5', '1 round', 'close (25 ft. + 5 ft./2 levels)', 'one humanoid', NULL, NULL, '1 day/level', 'Will negates', 'yes', 'You can control the actions of any humanoid creature through a telepathic link that you establish with the subject’s mind.', NULL, NULL, false, false),
  ('domination_link', 'Domination Link', 'divination', NULL, 'mind-affecting', 3, 'both', 'bard 3, inquisitor 3,', '1 standard action', '60 ft.', NULL, 'cone-shaped emanation', NULL, 'concentration, up to 1 min./level (D)', 'Will negates; see text', 'no', 'This spell functions like detect thoughts, with the additional ability to find echoes of the thoughts of a creature mentally controlling the target. For example, if the target has been dominated by a vampire, you can use evidence left in the target’s mind to learn about that vampire. Each minute you concentrate on the spell, you can learn your choice of one of the following pieces of information.', NULL, NULL, true, false),
  ('doom', 'Doom', 'necromancy', NULL, 'emotion, fear, mind-affecting', 1, 'divine', 'antipaladin 1, cleric/oracle 1, inquisitor 1, shaman 1; Subdomain demon (chaos, evil) 1', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one living creature', NULL, NULL, '1 min./level', 'Will negates', 'yes', 'This spell fills a single subject with a feeling of horrible dread that causes it to become shaken.', NULL, NULL, true, false),
  ('dousing_rain', 'Dousing Rain', 'evocation', NULL, 'water', 2, 'both', 'bard 2, druid 2, shaman 2, witch 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, 'cylinder (10-ft. radius, 40 ft. high)', NULL, '1 round/level (D)', 'none', 'no', 'With a beckoning gesture, you call forth a downpour of rain. For the duration of the spell, the following effects apply within the affected area. Nonmagical fires are automatically extinguished, and all creatures and objects in the area gain fire resistance 5. The conjured water is conductive, and whenever a doused creature takes electricity damage, it takes 1 additional point of electricity damage. At 6th, 12th, and 18th levels, the fire resistance increases by 5 and the additional electricity damage increases by 1 point.', 'a drop of water', NULL, true, false),
  ('draconic_ally', 'Draconic Ally', 'conjuration', 'creation', 'draconic', 3, 'both', 'antipaladin 3, bloodrager 3, paladin 3, psychic 3, occultist 3, sorcerer/wizard 3, spiritualist 3, summoner 3', '10 minutes', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'one intelligent draconic servant', '1 day/level (D)', 'none', 'no', 'You create a semi-living intelligent draconic servant that loyally obeys and serves you.', 'a scale from a dragon and 250 gp', NULL, false, true),
  ('draconic_malice', 'Draconic Malice', 'enchantment', NULL, 'draconic', 3, 'both', 'antipaladin 3, bard 3, bloodrager 3, cleric 3, inquisitor 3, mesmerist 3, psychic 3, shaman 3, sorcerer/wizard 3, witch 3', '1 standard action', 'personal', 'you', NULL, '10-foot aura centered on you', '1 minute/level', 'Will negates (harmless)', 'no', 'You surround yourself with a palpable aura of draconic fear and dread.', NULL, NULL, false, false),
  ('draconic_reservoir', 'Draconic Reservoir', 'evocation', NULL, 'acid, cold, electricity, or fire', 3, 'arcane', 'alchemist 3, bloodrager 3, sorcerer/wizard 3; Subdomain dragon 3; Elemental School air 3, earth 3, fire 3, water 3', '1 standard action', 'touch', NULL, NULL, NULL, '10 minutes/level or until discharged; see text', 'Fortitude negates (harmless)', 'yes (harmless)', 'Draconic reservoir functions as protection from energy, absorbing 6 points of one type of energy damage per caster level (acid, cold, electricity, or fire, maximum 60 points). Each round, as a swift action, the subject can release 1d6 points of the absorbed energy and apply it to any melee attack, as if using an acidic, flaming, frost, or shock weapon. The first creature the subject strikes with this attack takes the energy damage in addition to any other consequences of the attack.', 'a scale from dragon that produces the energy you seek to absorb', NULL, false, false),
  ('draconic_suppression', 'Draconic Suppression', 'abjuration', NULL, NULL, 5, 'arcane', 'sorcerer/wizard 5, witch 5', '1 standard action', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'A dragon that fails its saving throw cannot use its breath weapon for the duration of the spell and is treated as one age category younger for determining which special abilities it can use. For example, an ancient green dragon would revert to the special abilities of a very old dragon and lose access to its miasma ability and its dominate person spell-like ability. This spell has no effect on a dragon’s armor class, feats, frightful presence, hit points, physical attacks, saving throws, senses, size, skills, spellcasting, or statistics.', NULL, NULL, false, false),
  ('dragon_turtle_shell', 'Dragon Turtle Shell', 'abjuration', NULL, NULL, 2, 'both', 'alchemist 3, cleric 3, druid 2, sorcerer/wizard 3', '1 standard action', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'When you are struck by an opponent’s natural attacks, the damage is resolved as if the attack came from a creature one size smaller per 5 caster levels (maximum of four size categories smaller at CL 20th). Refer to Table 3–1 to determine an attack’s altered base damage. If the creature’s natural attack deals nonstandard damage, refer instead to the Improved Natural Attack feat. It is not possible to reduce the base damage of a creature’s natural attack below 1d2 with this spell.', 'a piece of turtle shell', NULL, false, false),
  ('dragon_s_breath', 'Dragon’s Breath', 'evocation', NULL, 'acid, cold, electricity, or fire', 4, 'arcane', 'alchemist 4, bloodrager 4, magus 4, sorcerer/wizard 4; Subdomain dragon 4; Elemental School air 4, earth 4, fire 4, water 4', '1 standard action', '30 ft. or 60 ft.', NULL, 'cone-shaped burst or line', NULL, 'instantaneous', 'Reflex half', 'yes', 'You breathe out a blast of energy. Creatures in the affected area take 1d6 points of energy damage per caster level (maximum of 12d6). A successful Reflex save results in half damage. The spell’s effect and energy type depend on the type of dragon scale used:', 'a dragon scale', NULL, false, false),
  ('dragonvoice', 'Dragonvoice', 'transmutation', NULL, NULL, 2, 'arcane', 'alchemist 2, bard 2, sorcerer/wizard 2, witch 2', '1 standard action', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'By magically altering the way your vocal cords create sounds, you can emulate the vocal inflections of dragons.', NULL, NULL, false, false),
  ('drain_construct', 'Drain Construct', 'necromancy', NULL, NULL, 2, 'arcane', 'sorcerer/wizard 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one construct', NULL, NULL, '1 round/level (D)', 'Will negates', 'no', 'You weaken a target construct, temporarily sapping its animating force and limiting its normal functionality. If the construct fails its saving throw, for the duration of this spell, it loses any damage reduction and fast healing it had and its base speed is reduced by half.', NULL, NULL, false, false),
  ('drain_poison', 'Drain Poison', 'transmutation', NULL, 'poison', 3, 'both', 'alchemist 3, antipaladin 3, cleric 3, druid 3, ranger 3, witch 3', '1 standard action', 'touch', 'one weapon or a single piece of ammunition', NULL, NULL, '24 hours', 'none', 'no', 'By touching a weapon against the fang of a poisonous creature and casting this spell, you drain 1 dose of the creature’s poison, which is magically applied to your weapon without risk of poisoning yourself. The poison remains on the weapon until either it strikes a creature, you touch the weapon, or you wipe off the poison. It otherwise functions exactly like a dose of a manufactured poison applied to a weapon. You can use this spell with natural as well as manufactured weapons. This spell does not prevent you from exposing yourself to the poison if you roll a natural 1 on an attack roll while the poison is applied to your weapon.', 'the fang of a poisonous creature', NULL, true, false),
  ('dread_bolt', 'Dread Bolt', 'evocation', NULL, 'evil', 2, 'divine', 'cleric/oracle 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'arrow-shaped projectile of evil energy', 'instantaneous (1d4 rounds)', 'Will partial (see text); Spell resistance yes', NULL, 'You unleash a crackling missile of darkness from your unholy symbol at any one target in range as a ranged touch attack.', NULL, NULL, true, false),
  ('dreadscape', 'Dreadscape', 'illusion )', 'phantasm', 'emotion, fear, mind-affecting', 3, 'arcane', 'bard 3, medium 3, mesmerist 3, psychic 4, sorcerer/wizard 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'up to one creature/level, no two of which can be more than 30 feet apart', NULL, NULL, '10 minutes/level', 'Will negates', 'yes', 'Your targets see their surroundings as a nightmarish reflection of the world around them. Buildings and furnishings take on a dirty, ruined appearance. Even allies appear foreign and hostile, with friendly speech turning into garbled mockery and threats.', 'a pinch of black sand', NULL, false, false),
  ('dream', 'Dream', 'illusion', 'phantasm', 'mind-affecting', 5, 'arcane', 'alchemist 5, bard 5, sorcerer/wizard 5; Subdomain imagination 5, moon 6; Bloodline dreamspun 5', '1 minute', 'unlimited', 'one living creature touched', NULL, NULL, 'see text', 'none', 'yes', 'You, or a messenger you touch, send a message to others in the form of a dream. At the beginning of the spell, you must name the recipient or identify him or her by some title that leaves no doubt as to identity. The messenger then enters a trance, appears in the intended recipient’s dream, and delivers the message. The message can be of any length, and the recipient remembers it perfectly upon waking. The communication is one-way. The recipient cannot ask questions or offer information, nor can the messenger gain any information by observing the dreams of the recipient.', NULL, NULL, false, false),
  ('dream_council', 'Dream Council', 'illusion )', 'phantasm', 'mind-affecting', 4, 'arcane', 'bard 6, medium 4, mesmerist 5, psychic 6, sorcerer/wizard 7', '1 standard action', 'unlimited', 'one or more living creatures', NULL, NULL, 'see text', 'Will negates', 'yes', 'This spell functions as dream, but you and the target of your dream can converse in a limited fashion as long as the recipient is also asleep. You can send or receive a number of dream messages equal to your caster level. Each message can be up to 25 words long or a single vague image that can’t convey fine details such as words. You can send and receive these dream messages with a single target or multiple targets, but each message you send or receive counts against the total number of messages allowed. Sending a message takes 1 round. The spell ends and you wake up when you run out of messages.', NULL, NULL, false, false),
  ('dream_dalliance', 'Dream Dalliance', 'illusion )', 'phantasm', 'mind-affecting', 3, 'arcane', 'mesmerist 3, psychic 4, sorcerer/wizard 4', '1 round', 'medium (100 ft. + 10 ft./level)', 'one creature', NULL, NULL, 'instantaneous', 'Will disbelief, then Will partial (see text)', 'yes', 'You create a comforting phantasm, which leeches onto the psyche of a nearby target. The creature can attempt a Will saving throw to prevent the phantasm from entering its psyche, but otherwise it takes up permanent residence in the creature’s mind. The phantasm fills its target’s dreams with happy visions, comforting manifestations of loved ones, and incredible vistas, feeding the target a perfect fantasy life it never wishes to leave. After the target’s next night’s sleep, the target must succeed at a Will saving throw to wake up; otherwise, it remains asleep for the rest of the day and following night. Each night it must succeed at a new saving throw or remain asleep for days or weeks on end as it slowly starves to death (presuming it normally needs to eat to survive). Loud noises, jostling, and even pain won’t rouse the slumbering target. Dealing 1 point of damage per the target’s Hit Die awakens the target, but it awakens fatigued and takes a –2 penalty on all saving throws against spells and effects that may put it back to sleep until the phantasm has been banished.', NULL, NULL, false, false),
  ('dream_feast', 'Dream Feast', 'conjuration', 'creation', NULL, 1, 'divine', 'cleric/oracle 1, druid 1, ranger 1, shaman 1', '1 standard action', 'touch', 'creature touched', NULL, NULL, 'instantaneous', 'Will negates (harmless)', 'yes (harmless)', 'The next time the target sleeps (within the next 8 hours), she dreams of a rich feast with her favorite foods and drinks. When she awakens, she is sated as if she had eaten a nutritious meal, regardless of what she dreamed she ate. The target must sleep for at least 1 hour to gain the benefits of this spell. Being awakened during this period interrupts the spell and cancels its effects.', NULL, NULL, true, false),
  ('dream_reality', 'Dream Reality', 'illusion', 'compulsion', 'mind-affecting', 5, 'both', 'alchemist 5, bard 5, cleric 6, mesmerist 5, occultist 5, psychic 6, sorcerer/wizard 6', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 minute/level (D)', 'Will disbelief', 'yes', 'You cause the target to perceive the world as if in a dream.', NULL, NULL, false, false),
  ('dream_scan', 'Dream Scan', 'divination', NULL, 'mind-affecting', 4, 'arcane', 'bard 6, medium 4, mesmerist 5, psychic 5, sorcerer/wizard 6', '1 standard action', 'unlimited', 'one living creature', NULL, NULL, 'see text', 'Will negates', 'yes', 'This spell functions as dream, but rather than sending a message to a sleeping target, you can instead read the target’s thoughts. The target must be asleep for you to perform a dream scan, though if the target isn’t asleep, you can wait in a trance until your target falls asleep. Once the target is asleep, You can concentrate in order to read its surface thoughts as if using detect thoughts. You can continue concentrating for up to 1 minute per caster level.', NULL, NULL, false, false),
  ('dream_shield', 'Dream Shield', 'abjuration', NULL, NULL, 2, 'both', 'alchemist 2, bard 2, medium 2, mesmerist 2, psychic 3, shaman 2, sorcerer/wizard 4, witch 4', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 hour/level', 'Will negates (harmless)', 'no', 'You ward the target’s mind against intrusion and influence while she is unconscious. While sleeping, the target is protected against divinations such as nondetection and gains spell resistance equal to 10 + your caster level against mind-affecting effects. In addition, the subject immediately receives another saving throw (if one was allowed to begin with) against any spell or effect that would possess or exercise direct mental control over her. This functions in all respects like the second property of protection from evil but it applies regardless of the alignment of the creature or object that created the possession or mental influence effect.', 'hollow glass ball or dreamcatcher', NULL, false, false),
  ('dream_travel', 'Dream Travel', 'conjuration', 'teleportation', 'mind-affecting', 6, 'arcane', 'mesmerist 6, psychic 6', '1 standard action', 'touch', 'you and one creature/level', NULL, NULL, '1 hour/level (D)', 'Will negates', 'yes', 'You and the other targets of the spell are physically drawn from the Material Plane into the Dimension of Dreams on a voyage into the dreams of a creature you designate. In the Dimension of Dreams, you move through a swirling sea of thoughts, desires, and emotions created by the minds of dreamers everywhere to reach your destination dreamscape. Reaching the destination dreamscape takes 1 hour. At any point before the spell’s duration ends, you can dismiss the spell to return to where you started on the Material Plane. The connection between dreams and reality is inherently tenuous, and your ability to arrive precisely where you mean to is dependent on your familiarity with the dreamer you’re trying to find. To determine how accurate your arrival is at the end of your dream travel, roll d% on the following table.', NULL, NULL, false, false),
  ('dream_voyage', 'Dream Voyage', 'conjuration', 'teleportation', 'mind-affecting', 9, 'arcane', 'psychic 9', '1 standard action', 'touch', 'You and one creature per level', NULL, NULL, '1 hour/level', 'Will negates', 'yes', 'This spell functions as dream travel, but you and your companions travel through the Dimension of Dreams in a fantastical vehicle of your own devising that halves the travel time. Only you can pilot the vessel, and you can do so even if you aren’t inside it. Your psychic vehicle buffers minds from the intense emotional tides of the Dimension of Dreams, rendering everyone inside immune to harmful emotion and fear effects.', NULL, NULL, false, false),
  ('dress_corpse', 'Dress Corpse', 'necromancy', NULL, NULL, 2, 'both', 'cleric 2, sorcerer/wizard 2, witch 2', '1 standard action', 'touch', 'corpse touched', NULL, NULL, 'instantaneous', 'none', 'no', 'You cause the flesh and bones of a corpse to shift themselves to suit a narrative of your choosing. This spell can hide or create telltale wounds, bruising, and other subtle clues as to the nature of the target’s death, and the final hours leading up to it, allowing you to make the corpse appear to have died in just about any way.', 'a pickled herring', NULL, false, false),
  ('drunkard_s_breath', 'Drunkard’s Breath', 'conjuration', 'creation', NULL, 2, 'both', 'bard 2, cleric 2', NULL, '30 ft.', NULL, 'cone-shaped burst', NULL, NULL, NULL, NULL, 'This spell emanates from your mouth and functions like stinking cloud, except as noted above. The effect is barely visible and does not obscure vision. The nausea effect resembles that of an extreme hangover. This is a poison effect.', NULL, NULL, false, false),
  ('duelist_s_feint', 'Duelist’s Feint', 'enchantment', 'charm', 'mind-affecting', 2, 'arcane', 'bard 2', '1 standard action', '20 ft.', 'one creature', NULL, NULL, '1 round/level', 'Will negates', 'yes', 'With a lascivious wink and a sensuous sway, you flood a foe’s mind with lustful thoughts of you, distracting your target and rendering that creature vulnerable to your attacks.', NULL, NULL, false, false),
  ('duelist_s_parry', 'Duelist’s Parry', 'transmutation', NULL, NULL, 1, 'arcane', 'bard 1, magus 1', '1 immediate action', 'personal', 'you', NULL, NULL, 'instantaneous', NULL, NULL, 'Originally designed by a magus who had long admired swashbucklers for their ability to deflect blows, duelist’s parry has swiftly gained popularity among bards and magi alike.', NULL, NULL, false, false),
  ('dungeonsight', 'Dungeonsight', 'divination', NULL, NULL, 4, 'both', 'bard 4, cleric 5, inquisitor 4, sorcerer/wizard 5', '1 standard action', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'You receive a clear and memorable view of the layout of chambers, barriers, and connecting passages within the area of effect.', NULL, 'a small glass orb worth 150 gp', false, true),
  ('duplicate_familiar', 'Duplicate Familiar', 'conjuration', 'creation', NULL, 4, 'arcane', 'alchemist 4, sorcerer/wizard 5, witch 5', '1 standard action', 'touch', NULL, NULL, 'temporary duplicate of familiar touched', '10 minutes/level', 'Fort negates', 'no', 'You create a duplicate of a familiar. The familiar’s master can use the duplicate as if it were his familiar in all respects, though he doesn’t gain the bonus special ability from more than one familiar at a time. When the spell’s duration expires, the familiar duplicate shrivels into nothing, even if petrified or otherwise transformed.', 'alchemically preserved mockingfey feathers', 'familiar', false, false),
  ('dust_form', 'Dust Form', 'transmutation', 'polymorph', NULL, 5, 'both', 'alchemist 5, cleric 6, druid 6, witch 6', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level', NULL, NULL, 'Upon casting this spell, you keep your relative form, but you and your equipment become composed entirely of dust. While in this dust form, you take no penalties for squeezing, and can move through spaces as if you were a creature three size categories smaller without penalty. You are also considered incorporeal, though any nonmagical attack you make deals half damage (50%). Magic attacks are unaffected, and you can still use your magic items and other equipment as normal. If the duration ends in a square that your normal space cannot occupy, you take 3d6 damage and are shunted to the nearest open space that you can normally occupy.', 'a pinch of dust gathered from a gravestone or sacred shrine', NULL, false, false),
  ('dust_of_twilight', 'Dust of Twilight', 'conjuration', NULL, 'darkness', 2, 'arcane', 'bard 2, bloodrager 2, sorcerer/wizard 2; Mystery dark tapestry 2, lunar 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, NULL, 'instantaneous', 'Fortitude negates (fatigue only)', 'no', 'A shower of iridescent black particles clings to and extinguishes torches, lanterns, sunrods, and similar mundane light sources and dispels any spell of 2nd level or lower with the light descriptor (as dispel magic). Creatures in the area must make a Fortitude save or become fatigued.', 'coal dust', NULL, false, false),
  ('dust_ward', 'Dust Ward', 'abjuration', NULL, NULL, 6, 'both', 'cleric 6, sorcerer/wizard 6, witch 6', '10 minutes', 'touch', 'one magic item', NULL, NULL, 'permanent', 'none', 'no', 'You ward a magic item against other creatures who try to learn to use or copy it.', 'a pinch of pumice', NULL, false, false),
  ('dwarven_veil', 'Dwarven Veil', 'transmutation', NULL, NULL, 2, 'divine', 'cleric 2, paladin 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '10 minutes/level', 'Will negates', 'yes (harmless)', 'This spell enhances the target’s dwarven or dwarf-like qualities, making it appear more attractive, personable, and worthy of respect and admiration by dwarves. The target is still recognizable as itself.', NULL, NULL, false, false),
  ('dweomer_retaliation', 'Dweomer Retaliation', 'abjuration', NULL, NULL, 3, 'arcane', 'sorcerer/wizard 3', '1 immediate action', 'Long (400 f. + 40 f./level)', 'one creature you counterspelled since your last turn', NULL, NULL, 'instantaneous', 'none', 'yes', 'You may only cast this spell immediately after successfully counterspelling an opponent. Drawing upon the residual energy of the countered spells, you gain a number of temporary hit points equal to the level of the countered spell plus your Charisma or Intelligence modifier (for sorcerers and wizards, respectively); your counterspelled opponent takes damage equal to this amount.', NULL, NULL, false, false),
  ('eagle_aerie', 'Eagle Aerie', 'conjuration', 'summoning', 'good', 6, 'both', 'druid 6, summoner/unchained summoner 6', '1 round', 'long (400 ft. + 40 ft./level)', NULL, NULL, 'summoned eagles', '1 hour/level', 'none', 'no', 'You summon a flight of giant eagles (one per three caster levels, maximum of six) to ferry you and your allies across the skies. The eagles avoid combat if possible but defend themselves if attacked; if the eagles attack, the remaining duration of the spell changes from 1 hour per level to 1 round per level (so if the spell had 5 full hours left, the eagles remain in combat for 5 rounds before the spell ends).', NULL, NULL, true, false),
  ('eagle_eye', 'Eagle Eye', 'divination', NULL, NULL, 2, 'both', 'druid 2, psychic 2, ranger 2, shaman 2', '1 minute', 'long (400 ft. + 40 ft./level)', NULL, NULL, 'magical sensor', '1 minute/level (D)', 'none', 'no', 'Eagle eye creates a magical sensor directly above you. The sensor can appear anywhere above you, to a maximum height equal to the spell’s range. You can see from this vantage as if you were actually there, rotating your viewpoint 360 degrees.', NULL, NULL, true, false),
  ('eagle_s_splendor', 'Eagle’s Splendor', 'transmutation', NULL, NULL, 2, 'both', 'alchemist 2, antipaladin 2, bard 2, bloodrager 2, cleric/oracle 2, paladin 2, psychic 2, shaman 2, sorcerer/wizard 2, summoner/unchained summoner 2; Bloodline imperious 2', '1 standard action', 'touch', NULL, NULL, NULL, '1 min./level', 'Will negates (harmless)', 'yes', 'The transmuted creature becomes more poised, articulate, and personally forceful. The spell grants a +4 enhancement bonus to Charisma, adding the usual benefits to Charisma-based skill checks and other uses of the Charisma modifier. Bards, paladins, and sorcerers (and other spellcasters who rely on Charisma) affected by this spell do not gain any additional bonus spells for the increased Charisma, but the save DCs for spells they cast while under this spell’s effect do increase.', 'feathers or droppings from an eagle', NULL, true, false),
  ('eaglesoul', 'Eaglesoul', 'conjuration', 'summoning', 'good', 4, 'both', 'cleric 6, paladin 4, summoner 5', '1 standard action', 'personal', 'you', NULL, NULL, '1 hour/level (see below)', NULL, NULL, 'When you cast this spell, you beseech a good-aligned outsider for their aid against evil. The outsider infuses a small portion of its own power into you, making you a powerful force for good. You gain a +2 morale bonus on all Perception checks made against evil creatures, a +2 bonus on Initiative checks, and detect evil as a constant spell-like ability.', 'vellum inscribed with good outsider’s name', NULL, false, false),
  ('ear_piercing_scream', 'Ear-Piercing Scream', 'evocation', NULL, 'sonic', 1, 'both', 'bard 1, bloodrager 1, inquisitor 1, psychic 1, sorcerer/wizard 1, witch 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'instantaneous; see text', 'Fortitude partial (see text)', 'yes', 'You unleash a powerful scream, inaudible to all but a single target. The target is dazed for 1 round and takes 1d6 points of sonic damage per two caster levels (maximum 5d6). A successful save negates the daze effect and halves the damage.', NULL, NULL, false, false),
  ('early_judgment', 'Early Judgment', 'divination', NULL, NULL, 1, 'both', 'cleric/oracle 2, inquisitor 2, witch 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one humanoid creature', NULL, NULL, '1d4 rounds', 'Will negates', 'yes', 'Depending on the creature’s alignment and its adherence to its ethos, you can provide it a brief glimpse of the reward or punishment that waits for it when it dies by showing it a mental image of its destined plane in the afterlife. If the target is good-aligned, it is fascinated for 1d4 rounds on a failed save. If the target is neutral-aligned, it is confused for 1d4 rounds on a failed save. If the target is evil-aligned, it is shaken for 1d4 rounds on a failed save.', NULL, NULL, true, false),
  ('ears_of_the_city', 'Ears of the City', 'divination', NULL, NULL, 1, 'both', 'bard 1, cleric 1, inquisitor 1, shaman 1, sorcerer/wizard 1, witch 1', '1 standard action', 'touch', 'one creature', NULL, NULL, '1 round/level', 'Will negates (harmless)', 'yes (harmless)', 'The target of this spell sees and hears a stream of past scenes and pieces of conversations related to local people and events. The flashes are so brief that it is impossible to identify individual people or places, but when the target concentrates on a particular topic or individual, she can piece together a coherent narrative told in a multitude of changing voices in her mind.', 'a small piece of a brick', NULL, true, false),
  ('earsend', 'Earsend', 'necromancy', NULL, NULL, 4, 'arcane', 'alchemist 4, sorcerer/wizard 4, witch 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'creature touched', NULL, NULL, '10 minutes/level', 'Will negates (harmless)', 'no', 'You cause one of your ears to tear itself free of your body and transform into a fly-like magical creature you control. This functions like skinsend, except your ear is a Fine construct with a fly speed equal to your base speed and a bonus on Fly checks equal to half your caster level. Your sense of hearing functions from your animated ear as if it were connected to your head, allowing you to hear as well as you normally could from your animated ear’s vantage point.', 'butterfly wing', NULL, false, false),
  ('earth_glide', 'Earth Glide', 'transmutation', NULL, 'earth', 4, 'both', 'alchemist 4, bloodrager 4, druid 4, shaman 4, sorcerer/wizard 4', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 round/level', 'Will negates (harmless)', 'yes (harmless)', 'The target can pass through stone, dirt, or almost any other sort of earth except metal as easily as a fish swims through water, traveling at a speed of 5 feet. If protected against fire damage, it can move through lava. This movement leaves behind no tunnel or hole, nor does it create any ripple or other sign of its presence. It requires as much concentration as walking, so the subject can attack or cast spells normally, but cannot charge or run. Casting move earth on an area containing the target flings the target back 30 feet, stunning it for 1 round (DC 15 Fort negates). This spell does not give the target the ability to breathe underground, so when passing through solid material, the creature must hold its breath.', NULL, NULL, false, false),
  ('earth_tremor', 'Earth Tremor', 'transmutation', NULL, 'earth', 3, 'both', 'bloodrager 3, druid 3, magus 3, shaman 3, sorcerer/wizard 3, witch 3', '1 standard action', 'up to 30 ft. (see text)', NULL, '30-ft. line, 20-ft. cone-shaped spread, or 10-ft.-radius spread (see text)', NULL, 'instantaneous', 'Reflex half (see text)', 'no', 'You strike the ground and unleash a tremor of seismic force, hurling up earth, rock, and sand.', NULL, NULL, false, false),
  ('earthquake', 'Earthquake', 'evocation', NULL, 'earth', 8, 'divine', 'cleric/oracle 8, druid 8, shaman 8; Domain destruction 8, earth 8; Bloodline deep earth 8, div 8; Mystery battle 8', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, '80-ft.-radius spread (S)', NULL, '1 round', 'see text', 'no', 'When you cast earthquake, an intense but highly localized tremor rips the ground. The powerful shockwave created by this spell knocks creatures down, collapses structures, opens cracks in the ground, and more. The effect lasts for 1 round, during which time creatures on the ground can’t move or attack. A spellcaster on the ground must make a Concentration check (DC 20 + spell level) or lose any spell he or she tries to cast. The earthquake affects all terrain, vegetation, structures, and creatures in the area. The specific effect of an earthquake spell depends on the nature of the terrain where it is cast.', NULL, NULL, true, false),
  ('echo', 'Echo', 'illusion', 'figment', NULL, 1, 'both', 'bard 1, druid 1, medium 1, mesmerist 1, occultist 1, psychic 1, ranger 1, spiritualist 1, witch 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels) or long (400 ft. + 40 ft./level); see text', NULL, 'one 10-ft. cube/level (S)', NULL, '1 round/level (D)', 'Will disbelief (if interacted with)', 'yes', 'You cause a sound heard in the target area up to 1 round ago and lasting up to 1 round in duration to repeat at a regular interval. the original sound need not have come from the area, but it echoes from the target area at its original full volume. Any special effects of the sound are not duplicated by this spell. If the area is naturally prone to echoes, such as a space surrounded on at least two sides by cliffs or high river banks, the spell’s range is long. Otherwise, the spell’s range is close.', NULL, 'a conch shell', false, false),
  ('echolocation', 'Echolocation', 'transmutation', NULL, 'sonic', 4, 'both', 'alchemist 4, bard 4, druid 4, sorcerer/wizard 5', '1 standard action', 'personal', 'you', NULL, NULL, '10 minutes/level', NULL, NULL, 'You can perceive the world by creating high-pitched noises and listening to their echoes. This gives you blindsight to a range of 40 feet. The echo-producing noises are too high-pitched to be heard by most creatures, and can only be detected by dragons, other creatures with this ability (such as bats), and creatures with hearing-based blindsense or blindsight. You cannot use this ability if you are deaf, and cannot detect anything in an area of silence.', NULL, NULL, false, false),
  ('ectoplasmic_eruption', 'Ectoplasmic Eruption', 'evocation', NULL, NULL, 7, 'arcane', 'psychic 7, spiritualist 6; Bloodline ectoplasm 7', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, '30-ft.-radius burst', NULL, '1 round/level', 'Reflex half and Will partial; see text', 'yes', 'A cascading avalanche of pale, swirling ectoplasmic matter erupts from a point you select. All creatures in the area when the spell is cast take 6d6 points of bludgeoning damage and are entangled for a number of rounds equal to your caster level.', NULL, NULL, false, false),
  ('ectoplasmic_hand', 'Ectoplasmic Hand', 'evocation', NULL, NULL, 4, 'arcane', 'occultist 5, psychic 5, spiritualist 4', '1 standard action', 'close (25 ft. + 5 ft./level)', NULL, NULL, 'one ectoplasmic appendage', '1 minute/level', 'none', 'no', 'You draw forth a ghostly, animated hand through the ectoplasmic veil to manipulate objects, attack creatures, and deliver touch spells at a distance. The hand remains tethered to you by tendrils of ectoplasm. The ectoplasmic hand and its tether have hardness 10 and hit points equal to 10 + your caster level. The tether can be damaged or sundered anywhere along its length, ending the spell. The ectoplasmic hand has improved evasion, uses your save bonuses, and has an AC of 24 (+6 natural armor, +8 size). The ectoplasmic hand moves up to 30 feet per round, and on each of your turns you can spend a move action to move it an additional 30 feet. If you spend a swift action, the ectoplasmic hand can make an attack using your base attack bonus, modifying its attack rolls and damage rolls with your spellcasting ability score (the ability score that determines your spell save DCs). It deals 1d6 points of damage with a slam attack, and it can wield any light or one-handed weapon. The ectoplasmic hand threatens and can flank targets.', NULL, NULL, false, false),
  ('ectoplasmic_snare', 'Ectoplasmic Snare', 'evocation', NULL, NULL, 3, 'both', 'magus 3, psychic 3, shaman 3, sorcerer/wizard 3, spiritualist 3; Bloodline ectoplasm 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'entangling web of ectoplasm', 'concentration, up to 1 round/level (D)', 'Reflex partial; see text', 'yes', 'You unleash a writhing tendril of ectoplasm to grapple or entangle a target creature. You must make a ranged touch attack to strike a target. If you hit, the target can attempt a Reflex save. On a successful save, the target is entangled for the duration of the spell and suffers no other effects. If the target fails this saving throw, the tendril is more restrictive, making the target grappled and dealing it 1d6+4 points of bludgeoning damage. Each round when you concentrate to maintain the spell, the snare attempts a grapple combat maneuver check to maintain the grapple. As normal when grappling, the snare gains a +5 bonus on grapple combat maneuver checks against opponents it is already grappling. The snare’s CMB is equal to 6 + your caster level, and its CMD is equal to 16 + your caster level. Since the ectoplasm passes between planes, this spell affects incorporeal and ethereal creatures normally.', NULL, NULL, false, false),
  ('effortless_armor', 'Effortless Armor', 'transmutation', NULL, NULL, 2, 'both', 'cleric 2, inquisitor 2, magus 2, paladin 2, psychic 2, ranger 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level', NULL, NULL, 'Armor you wear no longer reduces your speed. You also reduce the armor’s armor check penalty by 1 + 1 per five caster levels (maximum 5).', NULL, NULL, false, false),
  ('ego_whip_i', 'Ego Whip I', 'enchantment', 'compulsion', 'emotion, mind-affecting', 3, 'arcane', 'psychic 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round/level', 'Will partial', 'yes', 'You can use your psychic power to overwhelm the target’s ego, leaving the target feeling hopeless and unsure of itself. Choose Intelligence, Wisdom, or Charisma. The target takes a –2 penalty to that ability score, and is also staggered for the first round it’s affected. A successful Will save negates the staggered effect and reduces the duration of the penalty to 1 round.', NULL, NULL, false, false),
  ('eldritch_conduit', 'Eldritch Conduit', 'transmutation', NULL, NULL, 2, 'arcane', 'sorcerer/wizard 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round/level', 'Will negates', 'yes', 'If the target of this spell fails to resist its effects with a Will save, he becomes outlined in faint radiance, as if via faerie fire. At any time before the eldritch conduit expires, you may cast another spell with an area effect of cone, cylinder, line, or sphere and use the subject of the eldritch conduit as the point of origin for that spell. Doing so ends the spell immediately. The target must be within close range (25 feet + 5 feet/2 levels) in order for you to use the conduit—if the target moves out of range, the eldritch conduit effect persists but cannot be utilized by you until you get back within range.', 'a small mirror', NULL, false, false),
  ('eldritch_fever', 'Eldritch Fever', 'necromancy', NULL, 'curse, disease, evil', 3, 'both', 'inquisitor 3, psychic 3, sorcerer/wizard 3, witch 3', '1 standard', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'instantaneous', 'Fortitude negates', 'yes', 'The target gains the eldritch ague spellblight.', NULL, NULL, false, false),
  ('elemental_assessor', 'Elemental Assessor', 'evocation', NULL, 'acid, cold, electricity, fire', 6, 'both', 'cleric/oracle 6, sorcerer/wizard 6', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'one elemental ray', '1d4+1 rounds (see text)', 'none', 'yes', 'Azata champions developed this spell to deal with fiends with unknown resistances. A ray of spiraling colors springs from your hand and streaks to its target.', 'four needles', NULL, true, false),
  ('elemental_aura', 'Elemental Aura', 'evocation', NULL, 'acid, cold, electricity, or fire', 3, 'arcane', 'alchemist 3, bloodrager 3, magus 3, sorcerer/wizard 3; Bloodline boreal 3; Elemental School air 3, earth 3, fire 3, water 3; Mystery elemental 3', '1 standard action', 'personal', NULL, NULL, NULL, '1 round/level (D)', 'Reflex half; see text', 'yes', 'This spell forms an aura of energy around you, damaging all those that come near you. Choose an energy type: acid, cold, electricity, or fire. Creatures adjacent to you when this spell is cast and at the start of your turn take 2d6 points of energy damage of the selected type. This aura has an additional effect, depending upon the type of energy chosen.', NULL, NULL, false, false),
  ('elemental_body', 'Elemental Body', 'transmutation', 'polymorph', NULL, 4, 'arcane', 'alchemist 4, bloodrager 4, magus 4, sorcerer/wizard 4; Bloodline elemental 4; Elemental School air 4, earth 4, fire 4, water 4; Mystery elemental 4', '1 standard action', 'personal', 'you', NULL, NULL, '1 min/level (D)', NULL, NULL, 'When you cast this spell, you can assume the form of a Small air elemental, Small earth elemental, Small fire elemental, or Small water elemental. The abilities you gain depend upon the type of elemental into which you change. Elemental abilities based on size, such as burn, vortex, and whirlwind, use the size of the elemental you transform into to determine their effect.', 'the element you plan to assume', NULL, false, false),
  ('elemental_mastery', 'Elemental Mastery', 'transmutation', NULL, 'see text', 4, 'both', 'bloodrager 4, druid 4, magus 4, ranger 4, sorcerer/wizard 4', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level', NULL, NULL, 'You gain mastery over the element matching the elemental essence in your blood (fire for ifrits, earth for oreads, air for sylphs, and water for undines). If you are a suli, you can choose any one of the four options as you cast this spell, but the duration is reduced to 1 round per level. Your mastery gives you an insight bonus to your speed or a new movement mode, depending on the element you master, and grants one additional benefit. This spell’s descriptor matches the chosen element.', NULL, NULL, false, false),
  ('elemental_speech', 'Elemental Speech', 'divination', NULL, 'air, earth, fire, or water', 2, 'both', 'bard 3, cleric/oracle 3, druid 2, sorcerer/wizard 2; Elemental School air 2, earth 2, fire 2, water 2', '1 standard action', 'personal', NULL, NULL, NULL, '1 minute/level', NULL, NULL, 'This spell enables you to converse with creatures associated with a chosen element, including but not limited to true elemental creatures. This spell gains the elemental subtype based on the version of the spell you cast. Elemental speech does not guarantee a friendly reaction; it merely enables communication. You may converse with all creatures of the selected type with an Intelligence score of 1 or greater, even if they do not understand one another.', 'iron filings', NULL, false, false),
  ('elemental_swarm', 'Elemental Swarm', 'conjuration', 'summoning', 'see text', 9, 'divine', 'druid 9, shaman 9, witch 9; Domain air 9, earth 9, fire 9, water 9; Bloodline elemental 9; Mystery elemental 9', '10 minutes', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'two or more summoned creatures, no two of which can be more than 30 ft. apart', '10 min./level (D)', 'none', 'no', 'This spell opens a portal to an Elemental Plane and summons elementals from it. A druid can choose any plane (Air, Earth, Fire, or Water); a cleric opens a portal to the plane matching his domain.', NULL, NULL, false, false),
  ('elemental_touch', 'Elemental Touch', 'evocation', NULL, 'acid, cold, electricity, or fire', 2, 'arcane', 'alchemist 2, bloodrager 2, magus 2, sorcerer/wizard 2; Elemental School air 2, earth 2, fire 2, water 2', '1 standard action', 'personal', NULL, NULL, NULL, '1 round/level (D)', 'see text', 'no', 'Upon completing the casting of this spell, elemental energy infuses your hands.', 'a bit of the chosen element: earth, water, air, or fire', NULL, false, false),
  ('elude_time', 'Elude Time', 'transmutation', NULL, NULL, 5, 'arcane', 'alchemist 5', '1 standard action', 'personal', NULL, NULL, NULL, 'up to 1 minute/level; see text', NULL, NULL, 'You place yourself in a state of suspended animation, similar to temporal stasis. At the time of casting, you choose when the stasis will expire, up to the maximum duration of the spell.', 'powdered diamond, emerald, ruby, and sapphire dust worth 500 gp', NULL, false, true),
  ('emblazon_crest', 'Emblazon Crest', 'transmutation', NULL, NULL, 1, 'both', 'magus 1, paladin 1, sorcerer/wizard 1', NULL, 'touch', 'creature touched', NULL, NULL, '1 hour/level', 'Will negates (harmless)', 'yes (harmless)', 'This spell ensures the subject touched is always able to display her proper crest and coat of arms.', NULL, NULL, false, false),
  ('emblem_of_greed', 'Emblem of Greed', 'transmutation', 'polymorph', NULL, 6, 'both', 'cleric 6, inquisitor 6, magus 6, medium 6, shaman 7, sorcerer/wizard 6', '1 standard action', 'touch', '1 masterwork melee weapon touched', NULL, NULL, '1 minute/level', 'none (object)', 'no', 'You transform one melee weapon into a burning glaive. The target of your spell must be a masterwork or magical melee weapon appropriate to your size. The weapon becomes a glaive appropriate to your size and has a +1 enhancement bonus and the flaming weapon special ability. When wielding the glaive, you are considered proficient with it and use your caster level as your base attack bonus (which may give you multiple attacks). When you reach caster level 14th, the glaive gains the spell-storing weapon special ability. When you reach caster level 17th, it loses the flaming weapon special ability, and gains the flaming burst weapon special ability. The glaive’s enhancement bonus increases to +2 at caster level 15th, and +3 at caster level 19th.', 'a masterwork or magical melee weapon', NULL, false, false),
  ('embrace_destiny', 'Embrace Destiny', 'divination', NULL, NULL, 1, 'both', 'oracle 1, sorcerer/wizard 2, witch 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level (see text)', NULL, NULL, 'Upon completing this spell, roll a single d20 and record the result. At any point during the duration of this spell, you may use that roll for a single ability check, attack roll, initiative check, saving throw, or skill check, using the recorded result in place of a roll. This spell cannot be used to replace a roll that has already been made; the recorded result must be used instead of a roll. Once you have used this recorded result or the duration of the spell ends, the spell’s effect ends. You can’t have more than one instance of embrace destiny active on you at the same time.', NULL, NULL, false, false),
  ('emergency_force_sphere', 'Emergency Force Sphere', 'evocation', NULL, 'force', 4, 'arcane', 'sorcerer/wizard 4', '1 immediate action', '5 ft.', NULL, NULL, '5-ft.-radius hemisphere of force centered on you', '1 round/level (D)', 'None', 'no', 'As wall of force, except you create a hemispherical dome of force with hardness 20 and a number of hit points equal to 10 per caster level. The bottom edge of the dome forms a relatively watertight space if you are standing on a reasonably flat surface. The dome shape means that falling debris (such as rocks from a collapsing ceiling) tend to tumble to the side and pile up around the base of the dome. If you make a DC 20 Craft (stonemasonry), Knowledge (engineering), or Profession (architect or engineer) check, the debris is stable enough that it retains its dome-like configuration when the spell ends, otherwise it collapses.', NULL, NULL, false, false),
  ('emotive_block', 'Emotive Block', 'enchantment', 'compulsion', 'mind-affecting', 2, 'arcane', 'mesmerist 2, psychic 3, spiritualist 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round/level (D)', 'Will negates', 'yes', 'You create an emotional block in the target’s mind, adding an emotion component to each spell or spell-like ability he uses. This is in addition to any other components the spell already requires, and doesn’t replace the somatic component. The target’s spell-like abilities require this emotion component, even though they normally don’t need spell components.', NULL, NULL, false, false),
  ('empathy_conduit', 'Empathy Conduit', 'necromancy', NULL, NULL, 5, 'both', 'shaman 5, sorcerer/wizard 5, witch 5', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, NULL, '1 round/level', 'Will negates', 'yes', 'You make a conduit between the targeted master and her familiar, allowing you to target the master or the familiar with your spells in order to affect the other. If the master succeeds at its save to resist this spell but the familiar fails, you can choose to have your spells that target the master affect the familiar instead. If the familiar resists but the master doesn’t, your spells that target the familiar can affect the master instead. If both the familiar and the master fail to resist this spell, you can affect either the familiar or the master when you target either with a spell. When you target the master to affect her familiar or vice versa, the target attempts a save (if one is allowed) with its own saving throw bonus, but the other creature is affected by the spell.', NULL, 'a glass rod', false, false),
  ('empower_holy_water', 'Empower Holy Water', 'transmutation', NULL, 'good', 1, 'both', 'alchemist 2, bard 2, paladin 1', '1 standard action', 'touch', 'one or more vials of holy water', NULL, NULL, '1 minute/level', 'none (object)', 'no', 'You empower a vial of holy water to deal additional damage to undead creatures. You can empower one vial of holy water at 4th level, two at 8th level, and three at 12th level. When thrown at an undead creature, the affected vial of holy water deals an amount of bonus damage equal to your caster level (maximum +10) on a direct hit, and half that amount of bonus damage (maximum +5) to creatures caught in the splash area. This additional damage is positive energy damage, and has no effect on living creatures.', NULL, NULL, false, false),
  ('enchantment_foil', 'Enchantment Foil', 'abjuration', NULL, NULL, 4, 'both', 'alchemist 4, cleric 4, inquisitor 4, sorcerer/wizard 4, witch 4', '1 standard action', 'personal', 'you', NULL, NULL, '1 hour/level (see text)', NULL, NULL, 'You gain a +4 bonus on saving throws against enchantment effects. If you succeed at a save against an enchantment effect, you identify the effect as if you had succeeded at a Spellcraft check to do so. Furthermore, you can choose to act as if you had failed your saving throw. If you do so, you gain a +20 bonus on Bluff checks to convince others that you failed your save and are under the enchantment’s effects. A creature that attempts to use magic to detect this ruse or to make you speak truthfully about it must succeed at a caster level check (DC 15 + your caster level) to do so.', NULL, NULL, false, false),
  ('enchantment_sight', 'Enchantment Sight', 'divination', NULL, NULL, 2, 'both', 'alchemist 2, bard 2, cleric 2, inquisitor 2, medium 2, mesmerist 2, occultist 2, paladin 2, psychic 2, sorcerer/wizard 2, spiritualist 2, witch 2', '1 standard action', 'personal', 'you', NULL, NULL, '10 minutes/level (D)', NULL, NULL, 'Your irises take on a purplish tinge and you can see whether creatures within 60 feet of you are affected by an enchantment effect. To your eyes only, a creature under the effects of an enchantment spell glows with a simple white light around its head. You can immediately discern whether the brightness of the light is faint, moderate, strong, or overwhelming depending on the highest spell level of enchantment currently in effect (as per detect magic). Enchantments of the charm or compulsion subschool glow with a scarlet or emerald hue, respectively.', NULL, NULL, false, false),
  ('endothermic_touch', 'Endothermic Touch', 'transmutation', NULL, NULL, 1, 'both', 'druid 1, shaman 1, sorcerer/wizard 1, witch 1', '1 standard action', 'touch', 'one living creature that has the dragon type or the reptilian subtype', NULL, NULL, '1 round/level', 'Fort negates', 'yes', 'This spell slows the metabolism and other bodily functions of a creature for a short amount of time.', 'a small bit of snakeskin', NULL, true, false),
  ('endure_elements', 'Endure Elements', 'abjuration', NULL, NULL, 1, 'both', 'alchemist 1, bloodrager 1, cleric/oracle 1, druid 1, paladin 1, psychic 1, ranger 1, shaman 1, sorcerer/wizard 1, summoner/unchained summoner 1; Domain sun 1; Mystery elemental 1, outer rifts 1, winter 1', '1 standard action', 'touch', 'creature touched', NULL, NULL, '24 hours', 'Will negates (harmless)', 'yes (harmless)', 'A creature protected by endure elements suffers no harm from being in a hot or cold environment. It can exist comfortably in conditions between -50 and 140 degrees Fahrenheit (-45 and 60 degrees Celsius) without having to make Fortitude saves. The creature’s equipment is likewise protected.', NULL, NULL, false, false),
  ('enemy_hammer', 'Enemy Hammer', 'transmutation', NULL, NULL, 6, 'arcane', 'sorcerer/wizard 6', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, NULL, NULL, '1 round/level (D)', 'Fortitude partial', 'yes', 'You grab a creature with telekinesis and use it to batter nearby opponents or objects. You must target a specific creature when casting this spell and once you select that creature you cannot switch to another. Each round, as a standard action, you can attempt to hurl the target at any creature or object within 30 feet of it. You must make an attack roll whenever you use the target as a weapon. The attack bonus for this attack is equal to your caster level plus either your Intelligence or Charisma modifier (whichever is higher). If you successfully hit the new target with the creature both it and the creature take damage based on the creature’s size.', 'puppet strings', NULL, false, false),
  ('enemy_insight', 'Enemy Insight', 'divination', NULL, NULL, 2, 'divine', 'ranger 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 minute/level', 'none', 'no', 'You forge a mental bond between yourself and the other targets, each of which must have an Intelligence score of 3 or higher. Choose one of your favored enemy types (such as goblinoids or magical beasts). You grant the targets half your favored enemy bonus against that type of creature. If any target moves out of range, the spell ends for it.', NULL, NULL, true, false),
  ('enemy_s_heart', 'Enemy’s Heart', 'necromancy', NULL, 'death, evil', 2, 'divine', 'adept 2, antipaladin 2, cleric 2, witch 2; Subdomain cannibalism 2', '1 full-round action, special see below', 'touch', 'living creature touched', NULL, NULL, 'concentration/1 minute per HD of the subject; see text', 'none', 'yes', 'You cut out an enemy’s heart and consume it, absorbing that enemy’s power as your own. As part of casting this spell, you perform a coup de grace with a slashing weapon on a helpless, living adjacent target. If the target dies, you eat its heart to gain the spell’s benefits. If the target survives, the spell is not wasted and you can try again as long as you continue concentrating on the spell. When you consume the heart, you gain the benefits of a death knell spell, except you gain 1d8 temporary hit points +1 per Hit Die of the target, and the bonus to Strength is a profane bonus.', 'target creature’s heart', NULL, false, false),
  ('energy_drain', 'Energy Drain', 'necromancy', NULL, NULL, 9, 'both', 'cleric/oracle 9, shaman 9, sorcerer/wizard 9; Subdomain loss 9, undead 9; Bloodline accursed 9', NULL, NULL, NULL, NULL, NULL, NULL, 'Fortitude partial; see text for enervation', NULL, 'This spell functions like enervation, except that the creature struck gains 2d4 temporary negative levels. Twenty-four hours after gaining them, the subject must make a Fortitude saving throw (DC = energy drain spell’s save DC) for each negative level. If the save succeeds, that negative level is removed. If it fails, that negative level becomes permanent.', NULL, NULL, false, false),
  ('energy_hack', 'Energy Hack', 'transmutation', NULL, 'acid, cold, electricity, or fire; see below', 4, 'arcane', 'sorcerer/wizard 4', '1 immediate action', 'personal', 'you', NULL, NULL, '1 round/level (see below)', NULL, NULL, 'You can cast this spell only when you take 10 or more points of acid, cold, electricity, or fire damage from a spell or spell-like ability—this spell has the same energy descriptors as the damaging effect. When you use a spell or spell-like ability with the acid, cold, electricity, or fire descriptor or use an arcanist exploit, arcane school power, bloodline power, magus arcana, or hex that deals acid, cold, electricity, or fire damage, you can choose to change the energy type and descriptor to match one of the descriptors of energy hack.', NULL, NULL, false, false),
  ('energy_siege_shot', 'Energy Siege Shot', 'transmutation', NULL, 'variable', 5, 'arcane', 'sorcerer/wizard 5, summoner 5', '10 minutes Component V, S, M (a ball of pitch)', 'close (25 ft. + 5 ft./2 levels)', 'one Large siege engine', NULL, NULL, '10 minute/level', 'Fort negates (harmless, object)', 'yes (harmless, object)', 'This spell transforms any ammunition fired by the target ranged siege engine into ammunition made of pure energy. When casting the spell, the caster picks a one of the following energy types: acid, cold, electricity, fire, sonic, or force. The ammunition within the siege engine now deals that type of energy damage on a hit, though the amount of damage dealt by the ammunition does not change, nor does it change any of the other effects of the ammunition. Unlike other forms of energy damage, this energy damage does full damage to objects.', 'a ball of pitch', NULL, false, false),
  ('enervation', 'Enervation', 'necromancy', NULL, NULL, 4, 'arcane', 'bloodrager 4, sorcerer/wizard 4, witch 4; Subdomain loss 5, undead 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'ray of negative energy', 'instantaneous', 'none', 'yes', 'You point your finger and fire a black ray of negative energy that suppresses the life force of any living creature it strikes. You must make a ranged touch attack to hit. If you hit, the subject gains 1d4 temporary negative levels (see Special Abilities). Negative levels stack.', NULL, NULL, false, false),
  ('enhance_water', 'Enhance Water', 'transmutation', NULL, NULL, 1, 'both', 'bard 1, cleric/oracle 1, paladin 1', '1 round', 'touch', '1 pint of water/level', NULL, NULL, 'instantaneous', 'Fort negates (harmless, object)', 'yes (harmless, object)', 'This spell transforms water into an alcoholic beverage, typically ale, beer, mead, or wine. The alcohol is of middling quality but perfectly drinkable. The spell also serves to remove poisons, diseases, minerals, and other toxins from the water as it transforms. The more contaminants that exist in the water, the darker the ale or the more full-bodied the wine becomes. The beverage’s alcohol content is not affected by the presence or absence of contaminants.', NULL, NULL, false, false),
  ('enhanced_diplomacy_3_5e', 'Enhanced Diplomacy (3.5E)', 'divination', NULL, NULL, 0, 'divine', 'cleric 0, druid 0', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 minute or until discharged', 'Will negates (harmless)', 'yes (harmless)', 'You imbue the subject with divine diplomacy skills. The creature gets a +2 competence bonus on a single Diplomacy or Intimidate check. It must choose to use the bonus before making the roll to which it applies.', NULL, NULL, false, false),
  ('enlarge_person', 'Enlarge Person', 'transmutation', NULL, NULL, 1, 'arcane', 'alchemist 1, bloodrager 1, magus 1, psychic 1, sorcerer/wizard 1, summoner/unchained summoner 1, witch 1; Domain strength 1; Subdomain growth 1; Bloodline aberrant 1, boreal 1, efreeti 1; Mystery battle 1', '1 round', 'close (25 ft. + 5 ft./2 levels)', 'one humanoid creature', NULL, NULL, '1 min./level (D)', 'Fortitude negates', 'yes', 'This spell causes instant growth of a humanoid creature, doubling its height and multiplying its weight by 8. This increase changes the creature’s size category to the next larger one. The target gains a +2 size bonus to Strength, a -2 size penalty to Dexterity (to a minimum of 1), and a -1 penalty on attack rolls and AC due to its increased size.', 'powdered iron', NULL, false, false),
  ('enlarge_tail', 'Enlarge Tail', 'transmutation', NULL, NULL, 1, 'both', 'alchemist 1, antipaladin 1, druid 1, magus 1, sorcerer/wizard 1, summoner 1, witch 1', '1 standard action', 'personal', 'your tail', NULL, NULL, '1 hour/level', NULL, NULL, 'When attacking with your tail or tail weapons, you gain 5 feet of reach, a +1 bonus on attack rolls, and a +2 bonus on damage rolls.', NULL, NULL, false, false),
  ('enlightened_step', 'Enlightened Step', 'transmutation', NULL, 'air, meditative', 6, 'divine', 'cleric 6, druid 6, shaman 6', '1 hour', 'personal', 'you', NULL, NULL, '24 hours or until discharged', NULL, NULL, 'Through careful regulation of your body’s mystical energies, thoughtful control of your poise and balance, and the focus in your mind on the surety of each and every step you take, you are able to make your steps lighter than air.', 'soothing incense worth 600 gp', NULL, false, true),
  ('enshroud_thoughts', 'Enshroud Thoughts', 'abjuration', NULL, 'mind-affecting', 2, 'both', 'alchemist 2, bard 2, inquisitor 2, medium 2, mesmerist 2, psychic 2, ranger 3, shaman 2, witch 2', '1 standard action', 'personal', 'you', NULL, NULL, '10 minutes/level (D)', 'Will negates (harmless)', 'yes (harmless)', 'You become warded against the mental prying of others, including the effects of divination spells such as detect thoughts and seek thoughts, as well as enchantment spells such as modify memory and memory lapse. If another creature attempts to target you with a mind-affecting spell that detects or alters your thoughts or memories, the caster must succeed at a caster level check against a DC equal to 11 + your caster level or the spell fails. Only spells that detect or alter your thoughts or memories are blocked by this spell; effects such as clairaudience/clairvoyance, detect evil, and locate creature continue to affect you as normal.', NULL, NULL, false, false),
  ('entangle', 'Entangle', 'transmutation', NULL, NULL, 1, 'divine', 'druid 1, ranger 1, shaman 1; Domain plant 1; Bloodline fey 1; Elemental School wood 2', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, 'plants in a 40-ft.-radius spread', NULL, '1 min./level (D)', 'Reflex partial; see text', 'no', 'This spell causes tall grass, weeds, and other plants to wrap around creatures in the area of effect or those that enter the area. Creatures that fail their save gain the entangled condition. Creatures that make their save can move as normal, but those that remain in the area must save again at the end of your turn. Creatures that move into the area must save immediately. Those that fail must end their movement and gain the entangled condition. Entangled creatures can attempt to break free as a move action, making a Strength or Escape Artist check. The DC for this check is equal to the DC of the spell. The entire area of effect is considered difficult terrain while the effect lasts.', NULL, NULL, true, false),
  ('enter_image', 'Enter Image', 'transmutation', NULL, NULL, 2, 'both', 'bard 2, cleric/oracle 3, medium 3, mesmerist 2, occultist 2, psychic 3, sorcerer/wizard 3; Subdomain aristocracy 3', '1 standard action', '50 ft./level', NULL, NULL, 'transfer consciousness to any object bearing your likeness', 'concentration', 'none', 'no', 'You gain a dim impression of the activities around any object bearing your face or form and can also project your consciousness into one such object at a time, allowing you to observe or even interact with nearby creatures. This spell allows you to leave your body and subconsciously monitor the immediate area around any depiction of your image whether one, hundreds, or even thousands. Each such image has the full range of your normal senses (sight, hearing, smell, etc.) and you can make a Perception check to notice anything occurring nearby. The DC of this check is always 10 greater than what it would be if you were actually present at that location, so even if you would normally notice something automatically (such as talking, normally a DC of 0), you would need to make a DC 10 Perception check to notice it.', 'a drop of paint and a ball of clay', NULL, true, false),
  ('enthrall', 'Enthrall', 'enchantment', 'charm', 'language-dependent, mind-affecting, sonic', 2, 'both', 'bard 2, cleric/oracle 2, inquisitor 2, psychic 2, shaman 2, witch 2; Domain nobility 2; Subdomain love 2, revolution 2', '1 round', 'medium (100 ft. + 10 ft./level)', NULL, NULL, NULL, '1 hour or less', 'Will negates; see text', 'yes', 'If you have the attention of a group of creatures, you can use this spell to hold them enthralled. To cast the spell, you must speak or sing without interruption for 1 full round. Thereafter, those affected give you their undivided attention, ignoring their surroundings. They are considered to have an attitude of friendly while under the effect of the spell. Any potentially affected creature of a race or religion unfriendly to yours gets a +4 bonus on the saving throw.', NULL, NULL, false, false),
  ('entice_fey_lesser', 'Entice Fey, Lesser', 'conjuration', 'calling', NULL, 3, 'both', 'bard 4, druid 5, medium 3, ranger 4, shaman 5; Mystery whimsy 5', '10 minutes', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'one called fey with 6 Hit Dice or fewer', 'instantaneous', 'none', 'no', 'This spell functions as lesser planar ally, except that you entice a fey of 6 HD or fewer to lend you its aid with an offering of music or something else it finds appealing. Like lesser planar ally, this spell is unpredictable, and the fey who answers the calling is up to the whims of nature and the fey, not your own choice.', 'offerings worth 500 gp plus payment, see text', NULL, true, true),
  ('enticing_adulation', 'Enticing Adulation', 'enchantment', NULL, 'mind-affecting', 3, 'arcane', 'bard 3, sorcerer/wizard 4, witch 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '10 minutes/level', 'Will negates', 'yes', 'A targeted creature that fails its saving throw is filled with a deep desire to protect and care for you, fawning over your needs and ensuring your comfort. If another creature harms you, the target is immediately overcome with rage and is compelled to attack the aggressor, gaining a +2 morale bonus to Strength and Constitution, a +1 morale bonus on Will saves, and a –2 penalty to its Armor Class. These bonuses last until the instigating creature is defeated or retreats, or the target of the spell is killed or rendered unconscious.', 'a lock of your hair', NULL, false, false),
  ('entomb', 'Entomb', 'transmutation', NULL, 'earth', 8, 'both', 'arcanist 8, druid 8, shaman 8, sorcerer/wizard 8', '1 minute', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'up to three 10-ft. cubes/level (S)', 'permanent', 'none', 'no', 'You designate an aboveground area and send it deep within the earth.', 'a pristine geode worth at least 1,000 gp', NULL, false, true),
  ('entrap_spirit', 'Entrap Spirit', 'necromancy', NULL, NULL, 4, 'arcane', 'medium 4, occultist 5, psychic 5, spiritualist 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'incorporeal creature or haunt', NULL, NULL, '1 hour/level (D)', 'Will negates', 'yes', 'You trap the target in the mirror used as the spell’s focus. The target cannot be affected by any means while inside the mirror.', NULL, 'a small silver mirror', false, false),
  ('entropic_shield', 'Entropic Shield', 'abjuration', NULL, NULL, 1, 'divine', 'cleric/oracle 1, psychic 1; Subdomain entropy 1; Mystery dark tapestry 1', '1 standard action', 'personal', 'you', NULL, NULL, '1 min./level (D)', NULL, NULL, 'A magical field appears around you, glowing with a chaotic blast of multicolored hues. This field deflects incoming arrows, rays, and other ranged attacks. Each ranged attack directed at you for which the attacker must make an attack roll has a 20% miss chance (similar to the effects of concealment). Other attacks that simply work at a distance are not affected.', NULL, NULL, false, false),
  ('envious_urge', 'Envious Urge', 'enchantment', 'compulsion', 'emotion, mind-affecting', 4, 'arcane', 'bard 4, sorcerer/wizard 6', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, NULL, '1 round/level', 'Will negates', 'yes', 'You fill creatures with feelings of seething envy. Affected targets turn upon the nearest creature (whether an ally or enemy) and attempt to disarm it of a valuable weapon, steal something it is holding, or grapple it and strip it of something it prizes (your choice). Affected targets can attempt a new Will save each round as a free action to end this effect.', NULL, NULL, false, false),
  ('epidemic', 'Epidemic', 'necromancy', NULL, 'disease, evil', 6, 'both', 'cleric/oracle 6, druid 6, sorcerer/wizard 7, witch 6', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'living creature', NULL, NULL, 'instantaneous', 'Fortitude negates', 'yes', 'The target contracts one of the following diseases: blinding sickness, bubonic plague, cackle fever, filth fever, leprosy, mindfire, red ache, shakes, or slimy doom (Core Rulebook 557), as the spell contagion. However, the disease is highly contagious, and any creature that touches the infected target, is touched by the target, or spends more than an hour in a confined space with the target must make a save against the disease’s normal DC (not the spell DC) or contract the disease. If the initial target overcomes the disease by making the required number of saving throws, it remains a carrier of the disease for a length of time equal to the disease’s frequency, and can continue to infect others during this time.', NULL, NULL, false, false),
  ('erase', 'Erase', 'transmutation', NULL, NULL, 1, 'arcane', 'bard 1, psychic 1, sorcerer/wizard 1; Domain rune 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one scroll or two pages', NULL, NULL, 'instantaneous', 'see text', 'no', 'Erase removes writings of either magical or mundane nature from a scroll or from one or two pages of paper, parchment, or similar surfaces. With this spell, you can remove explosive runes, a glyph of warding, a sepia snake sigil, or an arcane mark, but not illusory script or a symbol spell. Nonmagical writing is automatically erased if you touch it and no one else is holding it. Otherwise, the chance of erasing nonmagical writing is 90%.', NULL, NULL, false, false),
  ('erase_impressions', 'Erase Impressions', 'abjuration', NULL, NULL, 3, 'arcane', 'medium 3, mesmerist 4, occultist 3, psychic 5, spiritualist 4', '1 round', 'touch', 'object touched', NULL, NULL, 'instantaneous', 'Will negates (object)', 'yes (object)', 'You banish psychic impressions from the object touched, rendering it devoid of recent history. You choose how much time to erase, up to a maximum of 1 day per caster level.', NULL, NULL, false, false),
  ('erode_defenses', 'Erode Defenses', 'transmutation', NULL, NULL, 2, 'arcane', 'magus 2, sorcerer/wizard 3, witch 3', '1 standard action', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Your spell slowly begins to eat away at the defenses of your target.', NULL, NULL, false, false),
  ('eroding_ray', 'Eroding Ray', 'transmutation', NULL, NULL, 2, 'both', 'cleric 2, druid 2, wizard/sorcerer 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'ray', 'instantaneous', 'none', 'no', 'You can fire one ray, plus one additional ray for every 4 levels beyond 3rd (to a maximum of three rays at 11th level). Each ray requires a ranged touch attack to hit and can target only a construct or an object. If a ray hits, the target begins to crumble, taking 2d6 points of damage. This damage ignores hardness and damage reduction.', NULL, NULL, false, false),
  ('eruptive_postules', 'Eruptive Postules', 'transmutation', NULL, 'acid', 3, 'arcane', 'alchemist 3, bloodrager 3, sorcerer/wizard 3, witch 3', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level (D)', 'Fortitude partial (see text)', 'yes', 'Your skin erupts in swollen, pus-filled bumps that burst open if you are struck. Any creature that strikes you with its body or a handheld weapon deals normal damage, but at the same time the attacker takes 1d6 points of acid damage and must save or be sickened for 1 round. If the attack against you is a critical hit, the attacker must save or be nauseated instead of sickened. This damage can harm a swarm.', NULL, NULL, false, false),
  ('escape_alarm', 'Escape Alarm', 'abjuration', NULL, NULL, 2, 'both', 'arcanist 2, bard 2, hunter 2, inquisitor 2, occultist 2, psychic 2, ranger 2, skald 2, sorcerer/wizard 2, spiritualist 2, summoner 2, summoner (unchained) 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, 'ten 10-foot cubes/level', NULL, '24 hours', 'none', 'no', 'You place a ward on an area that notifies you when a creature exits it. This functions as alarm, except as noted. It alerts you when a creature leaves, rather than enters, the area, and you can’t select a password to bypass its effects. Instead, when you place an escape alarm, you can attune up to one additional creature per caster level to the spell. You are automatically attuned to your own escape alarm and don’t count against the limit. Attuned creatures can enter and exit the spell’s area without triggering the alarm. If you select a mental alarm rather than an audible one, all attuned creatures receive the mental alert when someone exits the warded area.', NULL, 'a short segment of chain', false, false),
  ('escaping_ward', 'Escaping Ward', 'abjuration', NULL, NULL, 2, 'both', 'bard 2, inquisitor 2, magus 2, ranger 2, sorcerer/wizard 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level', NULL, NULL, 'This ward grants you extra maneuverability when you avoid attacks against larger foes. While affected by this spell, when you are attacked and missed by a creature that is at least one size category larger than you, you can, as an immediate action, move up to 5 feet away from the attacking creature. You can increase this movement by 5 feet for every 5 caster levels. This movement does not provoke attacks of opportunity.', NULL, NULL, false, false),
  ('ether_step', 'Ether Step', 'transmutation', NULL, NULL, 5, 'arcane', 'magus 5, sorcerer/wizard 6, summoner 5', '1 immediate action', 'personal', 'you', NULL, NULL, 'see text', NULL, NULL, 'You step into the Ethereal Plane long enough to dodge a blow or confound a spell; you must cast ether step after you are targeted by an attack or effect but before you learn the results of the attack or effect. This spell functions as ethereal jaunt, except that you become ethereal until the beginning of your next turn. On the turn after you cast this spell and return to your starting point, you can take only move actions or free actions.', NULL, NULL, false, false),
  ('ethereal_envelope', 'Ethereal Envelope', 'conjuration', 'teleportation', NULL, 4, 'arcane', 'psychic 5, spiritualist 4', '1 standard action', 'personal', 'you', NULL, NULL, '1 hour/level (D)', NULL, NULL, 'You place yourself into a cataleptic meditative state and shunt yourself to the Ethereal Plane, where your body is cocooned within a folded ripple of misty space, with total cover from creatures on the Ethereal Plane. While inside your ethereal envelope, you are treated as being asleep for most purposes.', 'empty crystal box', NULL, false, false),
  ('ethereal_envelopment', 'Ethereal Envelopment', 'conjuration', 'teleportation', NULL, 5, 'arcane', 'psychic 7, spiritualist 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 hour/level (D)', 'Will negates, see text', 'yes', 'This spell is similar to ethereal envelope, but it allows you to shunt an unwilling creature to the Ethereal Plane and seal it there within a cocoon of misty ethereal fibers. If the target fails its save, it’s forced into a cataleptic meditative state as if unconscious. However, each round at the end of its turn, it can attempt a Will save to awaken itself from this meditation.', 'empty crystal box', NULL, false, false),
  ('ethereal_fists', 'Ethereal Fists', 'transmutation', NULL, NULL, 4, 'arcane', 'magus 4, spiritualist 3; Mystery ascetic 4', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level (D)', NULL, NULL, 'Your hands reach simultaneously into the Ethereal and Material planes, allowing you to deal normal damage with claws, unarmed strikes, and touch spells or effects to ethereal creatures.', NULL, NULL, false, false),
  ('ethereal_jaunt', 'Ethereal Jaunt', 'transmutation', NULL, NULL, 5, 'both', 'cleric/oracle 7, sorcerer/wizard 7, summoner 5, unchained summoner 6; Subdomain thievery 7; Bloodline astral 7, ectoplasm 6; Mystery ancestor 7', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level (D)', NULL, NULL, 'You become ethereal, along with your equipment. For the duration of the spell, you are in the Ethereal Plane, which overlaps the Material Plane. When the spell expires, you return to material existence.', NULL, NULL, false, false),
  ('etherealness', 'Etherealness', 'transmutation', NULL, NULL, 9, 'both', 'cleric/oracle 9, shaman 9, sorcerer/wizard 9; Bloodline ectoplasm 9', '1 Standard Action', 'touch; see text', NULL, NULL, NULL, '1 min./level (D)', NULL, 'yes', 'This spell functions like ethereal jaunt, except that you and other willing creatures joined by linked hands (along with their equipment) become ethereal. Besides yourself, you can bring one creature per three caster levels to the Ethereal Plane. Once ethereal, the subjects need not stay together.', NULL, NULL, false, false),
  ('etheric_shards', 'Etheric Shards', 'evocation', NULL, 'force', 4, 'arcane', 'occultist 4, psychic 5, spiritualist 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, 'one 10-ft. cube/level', NULL, '1 hour/level (D)', 'Reflex partial or Reflex negates (see text)', 'no', 'You harden interpenetrated ethereal substance into deadly transdimensional razors that are invisible to normal sight.', 'broken glass', NULL, false, false),
  ('euphoric_cloud', 'Euphoric Cloud', 'conjuration', 'creation', 'poison', 2, 'both', 'druid 2, magus 2, psychic 2, sorcerer/wizard 2, witch 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'fog spreads in 20-ft. radius, 20 ft. high', '1 round/level', 'Fort negates (see text)', 'no', 'You create a bank of fog similar to that created by fog cloud except its vapors are intoxicating. Living creatures in the cloud become fascinated. This condition lasts as long as a creature is in the cloud and for 1d4+1 rounds after it leaves. Any creature that succeeds at its save but remains in the cloud must continue to save each round on your turn.', 'rare mushrooms worth 5 gp', NULL, false, true),
  ('euphoric_tranquility', 'Euphoric Tranquility', 'enchantment', 'compulsion', 'emotion, mind-affecting', 6, 'both', 'bard 6, cleric/oracle 8, druid 8, sorcerer/wizard 8; Subdomain love 8; Elemental School wood 8', '1 standard action', 'touch', NULL, NULL, NULL, '1 round/level', 'none and Will partial (see below)', 'yes', 'A creature under the effect of this enchantment enters a state of euphoria. The target treats all creatures as dear friends and abhors violence, but may rise up to protect itself if violence is perpetrated against it. Until the end of the spell’s duration, the creature’s speed is halved, and it cannot make attacks or cast spells. If the creature is attacked, it gets a Will Saving Throw. If the Saving Throw succeeds, the creature can make act normally for 1 round. If the Saving Throw fails, the creature moves half its speed away from the attacker as its next action.', 'a poppy flower', NULL, true, false),
  ('evaluator_s_lens', 'Evaluator’s Lens', 'conjuration', 'creation', NULL, 2, 'both', 'inquisitor 2, occultist 3, sorcerer/wizard 3, summoner 2, witch 3', '1 standard action', 'personal', NULL, NULL, NULL, '1 minute/level or until discharged', NULL, NULL, 'You summon an insubstantial lens of force 4 inches in diameter that hovers in front of your face. When you attempt a saving throw against a spell with the figment or pattern descriptor, you can roll twice and take the higher result. You gain a +10 enhancement bonus on Appraise checks to appraise the worth of an item viewed through the lens, and you never judge an item’s value wildly inaccurately. If you successfully identify that the item has magical properties, you can immediately attempt a Spellcraft check to determine the item’s properties, as if you had cast detect magic on the item and examined it for 3 rounds. This spell cannot determine the properties of artifacts.', NULL, NULL, false, false),
  ('evolution_surge', 'Evolution Surge', 'transmutation', NULL, NULL, 3, 'arcane', 'summoner/unchained summoner 3', '1 standard action', 'touch', NULL, NULL, NULL, '1 minute/level', 'Will negates (harmless)', 'no', 'This spell functions as lesser evolution surge (see below), except that you can grant any evolution whose total cost does not exceed 4 evolution points.', 'a chameleon scale', NULL, false, false),
  ('excruciating_deformation', 'Excruciating Deformation', 'transmutation', 'polymorph', 'evil, pain', 3, 'arcane', 'bloodrager 3, psychic 3, sorcerer/wizard 3, witch 3', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 round/level', 'Fortitude partial (see text)', 'yes', 'Your touch attack causes your target to become painfully malformed. Its limbs twist and buckle, while its body contorts uncontrollably, shifting and warping. Each round the target suffers excruciating pain and takes 2d6 points of nonlethal damage, 1 point of Dexterity damage, and 1 point of Constitution damage, and its speed is reduced by 10 feet. Once per round as a free action on its turn, the target can attempt a new Fortitude saving throw to resist the spell for 1 round.', NULL, NULL, false, false),
  ('expeditious_construction', 'Expeditious Construction', 'conjuration', 'creation', 'earth', 1, 'both', 'druid 1, sorcerer/wizard 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'a low wall 10 feet long per 3 levels (minimum 10 feet) (S)', 'instantaneous', 'none', 'no', 'You create a low wall or other simple structure of packed earth or loose stone measuring 3 feet thick, 3 feet tall, and 10 feet long per 3 caster levels you possess (minimum 10 feet). Each square of the structure can appear only in unoccupied spaces atop earthen or stone surfaces able to support it. The wall grants cover as per a low wall and can be climbed with a successful DC 5 Climb check.', 'a handful of earth or stone', NULL, false, false),
  ('expeditious_excavation', 'Expeditious Excavation', 'transmutation', NULL, 'earth', 1, 'both', 'bloodrager 1, druid 1, sorcerer/wizard 1; Bloodline deep earth 1; Elemental School earth 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, 'dirt in a 5-ft. cube', NULL, 'instantaneous', 'see text', 'no', 'You can excavate and move earth, dust, and sand up to the size of a 5-foot cube. If you are buried, you may open a 5-foot cube around yourself, but the spell cannot be used for tunneling.', 'tiny shovel', NULL, false, false),
  ('expeditious_retreat', 'Expeditious Retreat', 'transmutation', NULL, NULL, 1, 'both', 'alchemist 1, bard 1, inquisitor 1, magus 1, psychic 1, sorcerer/wizard 1, summoner/unchained summoner 1; Subdomain azata (chaos, good) 1, exploration 1', '1 standard action', 'personal', 'you', NULL, NULL, '1 min./level (D)', NULL, NULL, 'This spell increases your base land speed by 30 feet. This adjustment is treated as an enhancement bonus. There is no effect on other modes of movement, such as burrow, climb, fly, or swim. As with any effect that increases your speed, this spell affects your jumping distance (see the Acrobatics skill).', NULL, NULL, false, false),
  ('expel_blood', 'Expel Blood', 'conjuration', NULL, 'evil, water', 6, 'arcane', 'sorcerer/wizard 7, summoner 6, witch 7', '1 round', 'close (25 ft. + 5 ft./2 levels)', 'one Small or larger living creature', NULL, NULL, 'instantaneous and 1 round/level; see text', 'Fort negates', 'yes', 'You animate a portion of the target’s blood, causing it to force itself out of the victim’s body and form a corrupted water elemental. The target takes 2d4 points of Constitution damage unless it succeeds at a Fortitude saving throw. Additionally, if the target fails the saving throw, blood (or an analogous internal fluid, such as ichor) pours from the target’s body and pools in an empty adjacent square of your choice. The fluids immediately form into a fiendish water elemental of the same size as the target (but not larger than a Large fiendish water elemental). This fiendish water elemental does not have the vortex ability, but it has the blood drain special attack, which deals 1d3 points of Constitution damage at the end of the water elemental’s turn if it grapples a foe. The elemental gains Improved Grapple as a bonus feat. You have no control over the fiendish water elemental once it is summoned, though the water elemental does not attack you under any circumstances.', 'a drop of blood from each of three different creatures', NULL, false, false),
  ('expend', 'Expend', 'abjuration', NULL, NULL, 7, 'arcane', 'sorcerer/wizard 7; Mystery succor 7', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, '20-ft.-radius burst', NULL, 'instantaneous', 'Will negates', 'yes', 'You cause all creatures in the affected area to use up one or more of their limited-use magical abilities without any actual effect. A limited-use magical ability is any supernatural or spelllike ability which a creature can only activate a certain number of times during a set interval (3/day, 1/hour, etc.). The spell does not affect abilities which the creature can use at will or which are constant. It also does not apply to magical items or anything else external to a creature. A creature in the spell’s area must make a Will Saving Throw or expend a single use of one of its abilities. Abilities with the greatest number of uses per day are affected first; if more than one ability has the same number of uses, randomly determine which one is affected first. Creatures must continue making Will saves, expending an additional use of an ability for each failed save, until they succeed, at which point the spell has no further effect.', 'miniature broken hourglass', NULL, false, false),
  ('explode_head', 'Explode Head', 'evocation', NULL, NULL, 5, 'arcane', 'magus 6, psychic 5, sorcerer/wizard 6', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one living corporeal creature', NULL, NULL, 'instantaneous', 'special; see text', 'yes', 'You cause incredible pressure to build in the target’s head; this spell works only on a creature that has a head and would die from the loss of a head. The spell kills any such target that has 20 hit points or fewer, exploding its head and spreading debris in a 10-foot radius.', NULL, NULL, false, false),
  ('explosion_of_rot', 'Explosion of Rot', 'necromancy', NULL, NULL, 4, 'divine', 'druid 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, '10-ft.-radius burst', NULL, 'instantaneous', 'Reflex half (see text)', 'yes', 'You call forth a burst of decay that ravages all creatures in the area. Even nonliving creatures such as constructs and undead crumble or wither in this malignant eruption of rotting energy. Creatures in the area of effect take 1d6 points of damage per caster level (maximum 15d6) and are staggered for 1d4 rounds. A target that succeeds at a Reflex saving throw takes half damage and negates the staggered effect. Plant creatures are particularly susceptible to this rotting effect; a plant creature caught in the burst takes a –2 penalty on the saving throw and takes 1 extra point of damage per die.', 'a rotting flower', NULL, false, false),
  ('explosive_runes', 'Explosive Runes', 'abjuration', NULL, 'force', 3, 'arcane', 'sorcerer/wizard 3; Domain rune 4; Mystery apocalypse 3', '1 standard action', 'touch', 'one touched object weighing no more than 10 lbs.', NULL, NULL, 'permanent until discharged (D)', 'see text', 'yes', 'You trace mystic runes upon a book, map, scroll, or similar object bearing written information. The explosive runes detonate when read, dealing 6d6 points of force damage. Anyone next to the explosive runes (close enough to read them) takes the full damage with no saving throw; any other creature within 10 feet of the explosive runes is entitled to a Reflex save for half damage. The object on which the explosive runes were written also takes full damage (no saving throw).', NULL, NULL, false, false),
  ('exquisite_accompaniment', 'Exquisite Accompaniment', 'illusion', 'shadow', 'shadow', 3, 'arcane', 'bard 3', '1 standard action', 'personal', NULL, NULL, 'phantom instrument', '1 round/level (D)', 'none', 'no', 'You create a phantom instrument, a glowing construct of magic in the form of a portable musical instrument of your choice. The instrument floats beside you, moving as you move (even if you teleport). It cannot be damaged, but can be dispelled. The instrument plays as you direct, and as long as it plays, you do not have to expend rounds of bardic performance from your daily allotment to maintain an effect. Activating a bardic performance or switching to a new effect still costs a round of your overall bardic performances per day.', NULL, NULL, false, false),
  ('extreme_buoyancy', 'Extreme Buoyancy', 'evocation', NULL, NULL, 2, 'both', 'alchemist 2, bard 2, druid 2, hunter 2, investigator 2, medium 2, occultist 2, psychic 2, ranger 2, shaman 2, skald 2, warpriest 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '10 minutes/level', 'Will negates', 'yes', 'The target’s buoyancy becomes and stays swiftly rising, regardless of how dense the target and its gear are. Among other effects, the target needs to succeed at a DC 20 Swim check to submerge itself and to stay submerged.', 'a bag of air', NULL, true, false),
  ('extreme_flexibility', 'Extreme Flexibility', 'transmutation', NULL, NULL, 2, 'arcane', 'alchemist 2, bloodrager 2, magus 2, psychic 2, sorcerer/wizard 2, witch 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level', NULL, NULL, 'You gain a +1 dodge bonus to AC, a +4 circumstance bonus on Escape Artist checks and combat maneuver checks to escape a grapple, and +4 circumstance bonus to your CMD against grapple attempts.', NULL, NULL, false, false),
  ('eyebite', 'Eyebite', 'necromancy', NULL, 'emotion, pain', 6, 'arcane', 'alchemist 6, bard 6, sorcerer/wizard 6, witch 6; Domain scalykind 6; Subdomain curse 6; Bloodline abyssal 6, accursed 6', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one living creature', NULL, NULL, '1 round/level', 'Fortitude negates', 'yes', 'Each round, you can target a single living creature, striking it with waves of power. Depending on the target’s HD, this attack has as many as three effects.', NULL, NULL, false, false),
  ('eyes_of_the_void', 'Eyes of The Void', 'transmutation', NULL, NULL, 4, 'both', 'alchemist 4, antipaladin 4, sorcerer/wizard 4', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level', NULL, NULL, 'You gain darkvision, the ability to see 60 feet even in total darkness, including that created by deeper darkness. Darkvision is black-and-white only, but otherwise like normal sight. While affected, your eyes turn completely black (but appear white to anyone viewing you with darkvision).', 'a pinch of dried carrot or an agate', NULL, false, false),
  ('fable_tapestry', 'Fable Tapestry', 'illusion', 'shadow', 'shadow', 5, 'arcane', 'bard 5', '1 round', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, '1 legendary character/4 caster levels', '1 round/level', 'Will disbelief', 'yes', 'This spell is available to members of a specific ethinicity of nomadic people.', NULL, 'your family scarf', false, false),
  ('fabricate', 'Fabricate', 'transmutation', NULL, NULL, 5, 'arcane', 'sorcerer/wizard 5; Domain artifice 5; Elemental School void 5, wood 5', 'see text', 'close (25 ft. + 5 ft./2 levels)', 'up to 10 cu. ft./level; see text', NULL, NULL, 'instantaneous', 'none', 'no', 'You convert material of one sort into a product that is of the same material. Creatures or magic items cannot be created or transmuted by the fabricate spell. The quality of items made by this spell is commensurate with the quality of material used as the basis for the new fabrication. If you work with a mineral, the target is reduced to 1 cubic foot per level instead of 10 cubic feet.', 'the original material, which costs the same amount as the raw materials required to craft the item to be created', NULL, false, false),
  ('fabricate_bullets', 'Fabricate Bullets', 'transmutation', NULL, NULL, 1, 'arcane', 'sorcerer/wizard 1', '1 round', 'touch', '1 pound of soft metal', NULL, NULL, 'instantaneous', 'none', 'no', 'You convert 1 pound of lead into bullets. When you cast this spell, you decide whether you create normal sling bullets, firearm bullets, or firearm pellets. The spell creates two sling bullets, 30 firearm bullets, or 10 uses of pellets.', '1 pound of lead or other soft metal worth 2 gp', NULL, false, true),
  ('fabricate_disguise', 'Fabricate Disguise', 'transmutation', NULL, NULL, 1, 'both', 'alchemist 1, antipaladin 1, bard 1, inquisitor 1, psychic 1, sorcerer/wizard 1, witch 1', '1 standard action', 'personal', 'you', NULL, NULL, 'instantaneous', NULL, NULL, 'You change outfits or create a disguise out of materials you are wearing or carrying (potentially including a disguise kit). The spell can’t alter your body or change the structure of objects, but can style wigs, apply makeup or piercings, and otherwise make use of tools to make superficial changes. In an instant, you have a non-magical disguise or clothing change. Attempt a Disguise check to determine the effectiveness of the disguise.', NULL, NULL, false, false),
  ('face_of_the_devourer', 'Face of the Devourer', 'transmutation', 'polymorph', NULL, 1, 'both', 'adept 1, antipaladin 1, cleric/oracle 1, druid 1, sorcerer/wizard 1', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 minute/level', 'Fort negates (harmless)', 'yes (harmless)', 'You transform the target’s face into a hideous shape, such as a half-melted visage with insect legs instead of teeth, seeping pits instead of eyes, and suckered tongues dangling from its misshapen mouth. You do not choose what shape the target’s face takes, and the shape is different every time you cast the spell. This transformation does not interfere with the target’s senses or its ability to breathe, though it might prevent it from speaking. The target gains a +4 circumstance bonus on Intimidate checks.', NULL, NULL, false, false),
  ('faerie_fire', 'Faerie Fire', 'evocation', NULL, 'light', 1, 'arcane', 'druid 1; Subdomain light 1, moon 1; Mystery solar 1, whimsy 1', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, 'creatures and objects within a 5-ft.-radius burst', NULL, '1 min./level (D)', 'none', 'yes', 'A pale glow surrounds and outlines the subjects. Outlined subjects shed light as candles. Creatures outlined by faerie fire take a -20 penalty on all Stealth checks. Outlined creatures do not benefit from the concealment normally provided by darkness (though a 2nd-level or higher magical darkness effect functions normally), blur, displacement, invisibility, or similar effects. The light is too dim to have any special effect on undead or dark-dwelling creatures vulnerable to light.', NULL, NULL, true, false),
  ('fair_is_foul', 'Fair Is Foul', 'transmutation', NULL, 'curse', 2, 'both', 'antipaladin 2, cleric 3, shaman 3, sorcerer/wizard 4, spiritualist 3, witch 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, 'permanent (D)', 'Fort negates', 'yes', 'You curse the target with a disfiguring or painful mutation.', 'a newt eye', NULL, false, false),
  ('fairness', 'Fairness', 'enchantment', 'compulsion', 'mind-affecting', 1, 'divine', 'cleric/oracle 1, inquisitor 2, paladin 2', '1 round', 'close (25 ft. + 5 ft./2 levels)', 'one humanoid creature per level', NULL, NULL, '1 minute/level', 'Will negates', 'yes', 'Humanoid creatures affected by this spell must trade fairly with others to the best of their knowledge. If they know the fair value (or even an estimated fair value) of a good or service, they cannot participate in a trade if it would benefit one side unfairly, and must attempt to stop such trades from occurring, preventing them from cheating another while under the influence of this spell.', NULL, NULL, true, false),
  ('fairy_ring_retreat', 'Fairy Ring Retreat', 'conjuration', 'creation', NULL, 7, 'both', 'druid 7, shaman 7, witch 7', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'extradimensional meadow, up to three 10-ft. cubes/level (S)', '2 hours/level (D)', 'none', 'no', 'You conjure up an extradimensional meadow that can be accessed from a single entrance on the plane from which the spell was cast. The entry point looks like a circle of toadstools enclosing a 10-foot square. Only those you designate can enter the meadow before you do, and the portal is shut and made invisible behind you when you enter. You can open it again from your own side at will. Once a visitor has passed through the entry point, they find themselves in an idyllic twilight meadow surrounded by an impassable grove of fruit and nut trees. The atmosphere is clean, fresh, and warm.', NULL, NULL, true, false),
  ('fallback_strategy', 'Fallback Strategy', 'abjuration', NULL, NULL, 1, 'both', 'cleric/oracle 1, inquisitor 1, paladin 1, magus 1', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level or until discharged; see text', NULL, NULL, 'While this spell is active, you may reroll one attack roll, combat maneuver check, or skill check before the result of the roll or check is known. You must take the result of the reroll, even if it’s worse than the original roll. Once the reroll is used, the spell ends. You can have no more than one fallback strategy active on you at the same time.', NULL, NULL, true, false),
  ('false_age', 'False Age', 'transmutation', NULL, NULL, 2, 'arcane', 'alchemist 2, bard 2, psychic 2, sorcerer/wizard 2, witch 2', '1 standard action', 'personal', 'you', NULL, NULL, '10 minutes/level', NULL, NULL, 'Select an age category within one step of your actual age category, either older or younger. Your appearance changes to match your age for the chosen category. Your ability scores increase or decrease as appropriate for your chosen age category.', 'fine talcum powder', NULL, false, false),
  ('false_alibi', 'False Alibi', 'enchantment', 'compulsion', 'mind-affecting', 3, 'both', 'bard 3, cleric/oracle 3, inquisitor 3', '1 round', 'close (25 ft. + 5 ft./2 levels)', 'one living creature', NULL, NULL, 'permanent; see text', 'Will negates', 'yes', 'This spell functions similarly to modify memory, except you can modify the target’s memory only in a specific way.', 'emerald dust worth 100 gp', NULL, false, true),
  ('false_belief', 'False Belief', 'enchantment', 'compulsion', 'mind-affecting', 2, 'arcane', 'bard 2, mesmerist 2, psychic 2; Mystery intrigue 2', '10 minutes, plus length of memory to be altered', 'touch', 'willing creature touched', NULL, NULL, '1 hour/level', 'none', 'yes', 'You temporarily alter the target’s memory (similar to modify memory) to eliminate, change, or implant a memory of up to 1 hour in length. When the duration of this expires, the target’s real memory returns, and the false memory fades to little more than a vague outline, like a dream. This false memory seems true to the target, so effects that detect lies or force the target to speak the truth (as the subject understands it) don’t detect the falsehood.', 'lemon juice and a scrap of parchment', NULL, false, false),
  ('false_face', 'False Face', 'transmutation', 'polymorph', NULL, 1, 'both', 'alchemist 1, bard 1, inquisitor 1, mesmerist 1, sorcerer/wizard 1, witch 1', '1 standard action', 'personal', 'you', NULL, NULL, '1 hour/level', NULL, NULL, 'This spell alters details of your appearance so that you are no longer recognizable as yourself. Your new appearance is within the norms for your race, ethnicity, and gender. You lack control over the details of your appearance; however, when casting false face, you can choose an appearance you previously used, allowing you to maintain specific identities.', 'a folded-paper mask', NULL, false, false),
  ('false_future', 'False Future', 'illusion', 'glamer', NULL, 3, 'both', 'bard 3, cleric 4, medium 3, mesmerist 3, psychic 4, shaman 4, sorcerer/wizard 5, spiritualist 4, witch 4', '1 standard action', 'touch', 'creature or object touched', NULL, NULL, '1 hour/level (D)', 'Will negates or Will disbelief (see text)', 'yes', 'You interfere with attempts to predict the target’s future by preventing divinations from revealing what the target will do and what will befall the target while under the spell’s effects.', 'crushed jade worth 100 gp', NULL, false, true),
  ('false_life', 'False Life', 'necromancy', NULL, NULL, 2, 'both', 'alchemist 2, bloodrager 2, psychic 2, shaman 2, sorcerer/wizard 2, witch 2; Bloodline astral 2; Mystery bones 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 hour/level or until discharged; see text', NULL, NULL, 'You harness the power of unlife to grant yourself a limited ability to avoid death. While this spell is in effect, you gain temporary hit points equal to 1d10 + 1 per caster level (maximum +10).', 'a drop of blood', NULL, false, false),
  ('false_resurrection', 'False Resurrection', 'conjuration', 'calling', 'chaotic, evil, ruse', 7, 'both', 'cleric 7, shaman 8, witch 8', '1 minute', 'touch', 'dead creature touched', NULL, NULL, '1 day/level', 'none', 'yes (harmless)', 'This spell functions as resurrection except that instead of recalling the dead soul to life, the spell calls a shadow demon with the advanced simple template to possess the body. If you fail to overcome the subject’s spell resistance, the subject’s soul can negate the calling and gain the option to return to life (as resurrection) in the restored body. The possession otherwise functions (as possession) except that the subject’s soul is not present to resist. When false resurrection ends or the demon is removed from the subject, the demon returns to the Abyss, leaving the body alive but soulless (like that created by clone). If the soul hasn’t been returned to life already, it has the option to return in the now-empty body if it still lives (as resurrection). If the body was killed, the demon is sent back to the Abyss but the subject remains dead.', 'diamond worth 10,000 gp', NULL, true, true),
  ('false_vision', 'False Vision', 'illusion', 'glamer', NULL, 5, 'arcane', 'bard 5, sorcerer/wizard 5; Domain trickery 5; Mystery streets 5', '1 standard action', 'touch', NULL, NULL, NULL, '1 hour/level (D)', 'none', 'no', 'This spell creates a subtle illusion, causing any divination (scrying) spell used to view anything within the area of this spell to instead receive a false image (as the major image spell), as defined by you at the time of casting. As long as the duration lasts, you can concentrate to change the image as desired. While you aren’t concentrating, the image remains static.', 'crushed jade worth 250 gp', NULL, false, true),
  ('familiar_double', 'Familiar Double', 'illusion', 'shadow', 'shadow', 7, 'arcane', 'witch 7', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'one shadow duplicate', '1 round/level (D)', 'Will disbelief (if interacted with)', 'no', 'This spell functions as project image, except the image appears in your familiar’s square and moves when your familiar moves.', 'a small replica of you worth 5 gp', NULL, false, true),
  ('familiar_figment', 'Familiar Figment', 'illusion', 'figment', NULL, 2, 'arcane', 'sorcerer/wizard 2, witch 2', '1 standard action', 'touch', 'your familiar', NULL, NULL, '1 round/level (D)', 'none', 'no', 'You create an illusory duplicate of your familiar that moves erratically around your familiar’s space, frequently moving through the familiar’s body with a blurring effect that makes it indistinguishable from the real creature.', NULL, NULL, false, false),
  ('familiar_melding', 'Familiar Melding', 'necromancy', NULL, NULL, 4, 'both', 'shaman 4, sorcerer/wizard 4, witch 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'your familiar', NULL, NULL, '1 hour/level or until you return to your body', 'Will negates (harmless)', 'yes', 'You project your soul into your familiar, taking over its body while leaving its consciousness intact. When you transfer your soul upon casting, your body is, as near as anyone can tell, dead.', NULL, NULL, false, false),
  ('fastidiousness', 'Fastidiousness', 'abjuration', NULL, NULL, 1, 'both', 'bard 1, cleric 1, mesmerist 1, occultist 1, paladin 1, psychic 1, sorcerer/wizard 1', '1 standard action', 'personal', 'you', NULL, NULL, '24 hours', NULL, NULL, 'While protected by fastidiousness, your person and your equipment stay clean and dry. Dust and moisture slough off immediately; even when you are completely soiled, your appearance reverts to a pristine state over the course of 1 minute.', NULL, NULL, false, false),
  ('fear', 'Fear', 'necromancy', NULL, 'emotion, fear, mind-affecting', 3, 'both', 'antipaladin 4, bard 3, bloodrager 4, inquisitor 4, shaman 4, sorcerer/wizard 4, witch 4; Subdomain fear 4; Bloodline draconic 4, ghoul 4; Mystery bones 4, dragon 4, juju(PAP39/PZO9039) 3, juju(PZO9436) 3', '1 standard action', '30 ft.', NULL, 'cone-shaped burst', NULL, '1 round/level or 1 round; see text', 'Will partial', 'yes', 'An invisible cone of terror causes each living creature in the area to become panicked unless it succeeds on a Will save. If cornered, a panicked creature begins cowering. If the Will save succeeds, the creature is shaken for 1 round.', 'the heart of a hen or a white feather', NULL, false, false),
  ('fear_the_sun', 'Fear the Sun', 'transmutation', NULL, NULL, 1, 'both', 'antipaladin 1, bloodrager 1, cleric 2, druid 2, inquisitor 2, occultist 2, psychic 2, shaman 2, sorcerer/wizard 2, witch 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'up to one creature/level, no two of which can be more than 30 ft. apart', NULL, NULL, '1 round/level', 'Fort negates', 'yes', 'Each target that fails its saving throw gains light blindness, as per the universal monster rule. When exposed to bright light, affected targets are blinded for 1 full round and are dazzled in successive rounds. If you cast this spell in the presence of bright light, any target that fails its save is blinded immediately, and dazzled starting at the beginning of its first turn.', 'a drow eyelash', NULL, false, false),
  ('fearsome_duplicate', 'Fearsome Duplicate', 'illusion', 'figment', NULL, 3, 'both', 'bard 3, inquisitor 3, mesmerist 3, psychic 3, sorcerer/wizard 3, witch 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'monstrously distorted duplicate of you', '1 minute/level (D)', 'Will disbelief (if interacted with)', 'no', 'You create a larger and far more menacing version of yourself that you can send forth, manipulate like a puppet, and use to interact with others. You can make the duplicate up to two size categories larger than you are and determine a theme as to how it alters your original appearance. However, this duplicate always retains some vestiges of your actual appearance. Creatures who already know you gain a +2 bonus on saving throws made to disbelieve this spell. Your duplicate has no actual substance, and you cannot use it to alter its surroundings or to attack or otherwise harm creatures it encounters. You can use the duplicate to speak, and interact verbally with creatures using the Bluff, Diplomacy, and Intimidate skills, and you gain a +2 competence bonus on Intimidate checks when using that skill through the duplicate.', NULL, NULL, false, false),
  ('feast_of_ashes', 'Feast of Ashes', 'transmutation', NULL, 'curse', 2, 'both', 'druid 2, psychic 2, witch 2; Bloodline ghoul 2', '1 standard action', 'close (25 ft. + 5 ft/2 levels)', NULL, NULL, NULL, '2 days/level (D)', 'Fortitude negates', 'yes', 'You curse the target with a hunger no food can assuage. On a failed Saving Throw, the target begins to starve. The effects of this spell cannot inflict more nonlethal damage than the target has hit points. No amount of eating can counter the effect and, further, even attempting to eat causes the target to become nauseated for 1 round unless they make a DC 12 Fortitude save. The target still experiences the other normal effects of anything consumed (such as poisons or potions).', 'a pinch of ash', NULL, false, false),
  ('feast_on_fear', 'Feast On Fear', 'necromancy', NULL, 'emotion, fear, mind-affecting', 4, 'both', 'bard 4, shaman 5, sorcerer/wizard 5, witch 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 round/level', 'Fort negates', 'yes', 'Each round as a standard action, you can target a single living creature of up to 9 HD and strike it with terrifying waves of power. If the target fails its saving throw, it becomes panicked for 1d4 rounds, and you gain 5 temporary hit points (which disappear after 1 hour). After the panic ends, the creature remains shaken for 10 minutes per caster level, and it automatically becomes panicked again if it comes within sight of you during that time.', NULL, NULL, false, false),
  ('feather_fall', 'Feather Fall', 'transmutation', NULL, NULL, 1, 'arcane', 'bard 1, bloodrager 1, magus 1, psychic 1, sorcerer/wizard 1, summoner/unchained summoner 1; Domain void 1; Subdomain feather 2; Elemental School air 1', '1 immediate action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, 'until landing or 1 round/level', 'Will negates (harmless) or Will negates (object)', 'yes (object)', 'The affected creatures or objects fall slowly. Feather fall instantly changes the rate at which the targets fall to a mere 60 feet per round (equivalent to the end of a fall from a few feet), and the subjects take no damage upon landing while the spell is in effect. When the spell duration expires, a normal rate of falling resumes.', NULL, NULL, false, false),
  ('feather_step', 'Feather Step', 'transmutation', NULL, NULL, 1, 'both', 'bard 1, druid 1, psychic 1, ranger 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '10 minutes/level', 'Fortitude negates (harmless)', 'yes', 'For the duration of this spell, the subject ignores the adverse movement effects of difficult terrain, and can even take 5-foot steps in difficult terrain.', NULL, NULL, false, false),
  ('feeblemind', 'Feeblemind', 'enchantment', 'compulsion', 'mind-affecting', 5, 'arcane', 'sorcerer/wizard 5, witch 5; Bloodline aberrant 5, accursed 5; Mystery dark tapestry 5', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one creature', NULL, NULL, 'instantaneous', 'Will negates; see text', 'yes', 'Target creature’s Intelligence and Charisma scores each drop to 1. The affected creature is unable to use Intelligence– or Charisma-based skills, cast spells, understand language, or communicate coherently. Still, it knows who its friends are and can follow them and even protect them. The subject remains in this state until a heal, limited wish, miracle, or wish spell is used to cancel the effect of the feeblemind. A creature that can cast arcane spells, such as a sorcerer or a wizard, takes a -4 penalty on its saving throw.', 'a handful of clay, crystal, or glass spheres', NULL, false, false),
  ('ferment', 'Ferment', 'transmutation', NULL, NULL, 1, 'both', 'alchemist 1, bard 1, cleric 1, druid 1, sorcerer/wizard 1, witch 1', '1 standard action', 'touch', 'object touched', NULL, NULL, '10 minutes/level', 'Fort negates (object)', 'yes (object)', 'This spell temporarily imbues a potable liquid (including elixirs, extracts, potions, and poisons) with an intoxicant.', 'a drop of ale, mead, or wine', NULL, false, false),
  ('fester', 'Fester', 'necromancy', NULL, NULL, 2, 'both', 'inquisitor 3, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 round/level or 1 round; see text', 'Fortitude partial', 'yes', 'Necrotic energy permeates the target, blocking healing abilities. The subject gains Spell Resistance equal to 12 + your caster level against effects that restore hit points or grant temporary hit points. In addition, any healing provided by effects that ignore Spell Resistance (such as fast healing, regeneration, and some spells) are halved. If the target succeeds on a Fortitude Saving Throw, fester lasts only a single round.', 'rotted meat', NULL, false, false),
  ('fey_form', 'Fey Form', 'transmutation', 'polymorph', NULL, 3, 'both', 'alchemist 3, bloodrager 3, druid 3, magus 4, shaman 3, sorcerer/wizard 4, witch 4', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level (D)', NULL, NULL, 'You assume the form of a Small or Medium creature of the fey type. Your base speed changes to match the new form’s base speed, with a maximum speed of 60 feet (even if the chosen fey form has a base speed in excess of that speed). If the form you assume has any of the following abilities, you gain those abilities: climb speed 30 feet, fly speed 30 feet (average maneuverability), swim speed 30 feet, darkvision 60 feet, low-light vision, scent, and boot stomp. If the form you assume has the aquatic subtype, you can breathe air and water. If the creature has any weaknesses, you gain those weaknesses. If a listed ability depends on an item (as is the case with boot stomp), this spell transforms the nearest counterpart among your worn gear into that item.', 'a piece of the creature whose form you plan to assume', NULL, false, false),
  ('fey_gate', 'Fey Gate', 'conjuration', 'creation', NULL, 6, 'both', 'bard 6, cleric 8, druid 8, sorcerer/wizard 8, summoner 6, witch 8', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 round/level; see text', 'none', 'no', 'This spell functions as the planar travel function of gate, except it can be used to travel only between points on the Material Plane and the Fey World, and it comes with additional dangers.', NULL, NULL, false, false),
  ('fickle_winds', 'Fickle Winds', 'transmutation', NULL, 'air', 3, 'both', 'cleric/oracle 5, druid 5, ranger 3, sorcerer/wizard 5; Elemental School wood 5', '1 standard action', NULL, NULL, NULL, NULL, '1 minute/level (D)', 'none (see text)', 'yes', 'You create a mobile cylinder of wind encompassing every target of the spell and protecting them as wind wall, but not interfering with them in any way. For example, arrows and bolts fired at the targets are deflected upward and miss, but the targets’ own arrows or bolts pass through the wall as if it were not there.', NULL, NULL, false, false),
  ('fiendish_wrath', 'Fiendish Wrath', 'enchantment', 'compulsion', 'emotion, mind-affecting', 3, 'arcane', 'alchemist 3, bard 3, bloodrager 3, mesmerist 3, psychic 4, sorcerer/wizard 4, summoner 3, witch 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one willing living creature per 3 levels, no two of which can be more than 30 ft. apart', NULL, NULL, 'concentration + 1 round/level (D)', 'none', 'yes', 'Each affected creature flies into a combat frenzy. The target gains a +2 morale bonus to Strength and Constitution, and a +1 morale bonus on Will saves. If an affected creature strikes an enemy with two claw attacks or two unarmed strikes while in this frenzy, it can use the rend ability, dealing an additional amount of damage equal to its claw or unarmed strike damage plus 1-1/2 times its Strength bonus.', NULL, NULL, false, false),
  ('fiery_body', 'Fiery Body', 'transmutation', NULL, 'fire', 9, 'arcane', 'sorcerer/wizard 9; Subdomain ash 9; Elemental School fire 9; Mystery flame 9', '1 standard action', 'personal', NULL, NULL, NULL, '1 minute/level', NULL, NULL, 'This spell transforms your body into living flame. You and your equipment are immune to fire damage. In fact, every time you would normally take damage from fire, you are instead healed of damage at a rate of 1 point per 3 points of damage the fire attack would have normally inflicted. You are immune to blindness, critical hits, ability score damage, deafness, disease, drowning, electricity, poison, stunning, and all spells that affect your physiology or respiration. You take only half damage from acid or electricity. You take 150% as much damage from cold than normal.', NULL, NULL, false, false),
  ('fiery_runes', 'Fiery Runes', 'evocation', NULL, 'fire', 2, 'both', 'alchemist 2, bloodrager 2, druid 2, magus 2, sorcerer/wizard 2', NULL, 'touch', 'melee weapon touched', NULL, NULL, '1 minute/level or until discharged (see text)', 'none', 'yes (see text)', 'You charge a weapon with a magic rune of fire.', NULL, NULL, false, false),
  ('fiery_shuriken', 'Fiery Shuriken', 'conjuration', 'creation', 'fire', 2, 'arcane', 'sorcerer/wizard 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'Two or more fiery shuriken', '1 round/level (D)', 'none', 'yes', 'You call forth two fiery projectiles resembling shuriken, plus one more for every two caster levels beyond 3rd (to a maximum of eight shuriken at 15th level), which hover in front of you. When these shuriken appear, you can launch some or all of them at the same target or different targets. Each shuriken requires a ranged touch attack roll to hit and deals 1d8 points of fire damage. You provoke no attacks of opportunity when launching them. Any shuriken you do not launch as part of casting this spell remains floating near you for the spell’s duration. On rounds subsequent to your casting of this spell, you can spend a swift action to launch one of these remaining shuriken or a standard action to launch any number of these remaining shuriken. If you fail to launch a shuriken before the duration ends, that shuriken disappears and is wasted.', 'a pinch of sulfur and a single shuriken worth 2 sp', NULL, false, true),
  ('final_sacrifice', 'Final Sacrifice', 'evocation', NULL, NULL, 2, 'both', 'antipaladin 3, bloodrager 2, cleric 3, shaman 3, sorcerer/wizard 3, summoner 2, witch 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one summoned creature', NULL, NULL, 'instantaneous', 'Fort negates, then Reflex half (see text)', 'yes', 'You disrupt the conjuring energies within a summoned creature, causing it to violently explode. If the target fails its Fortitude save, it is immediately slain and all creatures within 20 feet of the target take 1d4 points of damage per spell level of the summoning spell that conjured the target. This damage is fire damage unless the target creature has the cold or water subtype, in which case it’s cold damage. Creatures caught in this explosion take half damage if they succeed at their Reflex saves against this spell’s DC. Final sacrifice can detonate a summoner‘s eidolon, though an eidolon receives a +4 bonus on its Fortitude save unless the spell is cast by the eidolon‘s own summoner.', NULL, NULL, false, false),
  ('find_fault', 'Find Fault', 'divination', NULL, NULL, 3, 'both', 'bard 3, bloodrager 3, inquisitor 3, magus 3, medium 3, oracle 3, psychic 3, shaman 3, sorcerer/wizard 3, witch 3', '1 standard action', 'medium (100 ft. plus 10 ft./level)', '1 creature', NULL, NULL, 'instantaneous', 'none', 'yes', 'You instantly learn many of the target’s weaknesses, as if you had made an appropriate Knowledge skill check with a result equal to 20 + your caster level. Additionally, your first melee or ranged attack roll against the creature before the end of your next turn gains a +5 insight bonus. If the creature is polymorphed, disguised, or hidden by an illusion and you are not aware of it’s true form, this spell fails as if the target has spell resistance you failed to penetrate (the GM may have you attempt a caster level check to conceal the true reason for the spell’s failure).', NULL, NULL, false, false),
  ('find_quarry', 'Find Quarry', 'divination', NULL, NULL, 4, 'divine', 'inquisitor 4, ranger 4', '1 standard action', 'personal', 'you', NULL, NULL, 'instantaneous', 'none', 'no', 'You sense whether a well-known creature you can clearly visualize is within a 20-mile radius of your current location, as well as the distance and direction to the creature in relation to you. You also discern whether the creature is moving, and its direction, speed, and mode of movement. The radius you can sense increases by 5 miles for every two caster levels you have above 10th (to a maximum of a 45-mile radius at 20th level). Anything that would prevent locate creature from finding a creature also prevents find quarry from doing so.', NULL, NULL, true, false),
  ('find_the_path', 'Find the Path', 'divination', NULL, NULL, 6, 'both', 'bard 6, cleric/oracle 6, druid 6, inquisitor 6, shaman 6, witch 6; Domain knowledge 6, travel 6', '3 rounds', 'personal or touch', 'you or creature touched', NULL, NULL, '10 min./level', 'none or Will negates (harmless)', 'no or yes (harmless)', 'The recipient of this spell can find the shortest, most direct physical route to a prominent specified destination, such as a city, keep, lake, or dungeon. The locale can be outdoors or underground, as long as it is prominent. For example, a hunter’s cabin is not prominent enough, but a logging camp is. Find the path works with respect to locations, not objects or creatures at a locale. The location must be on the same plane as the subject at the time of casting.', NULL, 'a set of divination counters', false, false),
  ('find_traps', 'Find Traps', 'divination', NULL, NULL, 2, 'both', 'cleric/oracle 2, inquisitor 2, psychic 2, witch 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 min./level', NULL, NULL, 'You gain intuitive insight into the workings of traps. You gain an insight bonus equal to 1/2 your caster level (maximum +10) on Perception checks made to find traps while the spell is in effect. You receive a check to notice traps within 10 feet of you, even if you are not actively searching for them. Note that find traps grants no ability to disable the traps that you may find.', NULL, NULL, false, false),
  ('finger_of_death', 'Finger of Death', 'necromancy', NULL, 'death', 7, 'both', 'druid 8, sorcerer/wizard 7', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'instantaneous', 'Fortitude partial', 'yes', 'This spell instantly delivers 10 points of damage per caster level. If the target’s Fortitude saving throw succeeds, it instead takes 3d6 points of damage + 1 point per caster level. The subject might die from damage even if it succeeds on its saving throw.', NULL, NULL, false, false),
  ('fins_to_feet', 'Fins to Feet', 'transmutation', 'polymorph', NULL, 3, 'both', 'druid 3, shaman 3, sorcerer/wizard 3, witch 3', '1 standard action', 'touch', 'willing creature touched', NULL, NULL, '1 hour/level (D)', 'none', 'yes', 'You transform the target’s fins, flippers, or tail into legs and feet, allowing it to walk on land. The target loses its swim speed but gains a base speed appropriate for a humanoid of its size (speed 30 if a Medium or larger creature, speed 20 if Small). If the creature is immersed in water for 1 round, the transformation reverts, allowing it to swim normally. One round after leaving the water, the transformation occurs again, allowing it to walk.', NULL, NULL, false, false),
  ('fire_breath', 'Fire Breath', 'evocation', NULL, 'fire', 2, 'arcane', 'alchemist 2, bloodrager 2, magus 2, sorcerer/wizard 2; Elemental School fire 2', '1 standard action', '15 ft.', NULL, 'cone-shaped burst', NULL, '1 round/level or until discharged; see text', 'Reflex half; see text', 'yes', 'Up to thrice during this spell’s duration, you can belch forth a cone of fire as a standard action. The first cone deals 4d6 points of fire damage to every creature in the area. The second cone of flame deals 2d6 points of fire damage to every creature in the area. The third cone of flame deals 1d6 points of fire damage to every creature in the area. A successful Reflex save halves this damage. After the third cone of flame, the spell ends.', 'a chili pepper', NULL, false, false),
  ('fire_of_entanglement', 'Fire of Entanglement', 'evocation', NULL, NULL, 2, 'divine', 'paladin 2', '1 swift action', 'special; see text', NULL, NULL, NULL, '1 round/level', 'Reflex partial', 'yes', 'The next creature you attack using your smite evil class ability is wreathed in flames that impede its movement. Until the end of the spell’s duration, the target is entangled. If the target starts its turn in a square adjacent to you, it is considered to be entangled to an immobile object (you) and cannot move. A target that saves against this spell is affected for only 1 round.', NULL, NULL, false, false),
  ('fire_of_judgment', 'Fire of Judgment', 'evocation', NULL, NULL, 3, 'divine', 'paladin 3', '1 swift action', 'special; see text', NULL, NULL, NULL, '1 round/level', 'Will partial', 'yes', 'After casting this spell, the next creature you attack using your smite evil class ability is engulfed in flames of positive energy. At the start of its turn, the target takes 1d6 points of damage, and takes an additional 1d6 points of damage each time it attacks a creature other than you. If the creature is an outsider with the evil subtype, an evil-aligned dragon, or an undead creature this damage increases to 1d10. With a successful Saving Throw, a creature is affected by this spell for only 1 round. This damage is divine in nature and bypasses any DR the creature possesses.', NULL, NULL, false, false),
  ('fire_of_vengeance', 'Fire of Vengeance', 'evocation', NULL, 'fire', 4, 'divine', 'paladin 4', '1 swift action', 'special; see text', NULL, NULL, NULL, 'see text', 'none', 'no', 'After casting this spell, the next creature you attack using your smite evil class ability is engulfed in holy flames that flare up when the target attacks someone other than you. If at any time during the duration of your smite evil effect the target makes an attack that does not include you, it takes 3d8 points of fire damage. Once triggered in this manner, or when your smite evil ability expires, the spell ends.', NULL, NULL, false, false),
  ('fire_seeds', 'Fire Seeds', 'conjuration', 'creation', 'fire', 6, 'divine', 'druid 6, shaman 6; Domain fire 6, sun 6; Mystery flame 6', '1 standard action', 'touch', NULL, NULL, NULL, '10 min./level or until used', 'none or Reflex half; see text', 'no', 'Depending on the version of fire seeds you choose, you turn acorns into splash weapons that you or another character can throw, or you turn holly berries into bombs that you can detonate on command.', 'acorns or holly berries', NULL, false, false),
  ('fire_shield', 'Fire Shield', 'evocation', NULL, 'fire or cold', 3, 'arcane', 'alchemist 4, bloodrager 4, magus 4, sorcerer/wizard 4, summoner 3, unchained summoner 4; Domain  fire 5, sun 4; Elemental School fire 4', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level (D)', NULL, NULL, 'This spell wreathes you in flame and causes damage to each creature that attacks you in melee. The flames also protect you from either cold-based or fire-based attacks, depending on if you choose cool or warm flames for your fire shield.', 'phosphorus for the warm shield; a firefly or glowworm for the chill shield', NULL, false, false),
  ('fire_snake', 'Fire Snake', 'evocation', NULL, 'fire', 5, 'both', 'druid 5, magus 5, sorcerer/wizard 5; Elemental School fire 5', '1 standard action', '60 ft.', NULL, 'see text', NULL, 'instantaneous', 'Reflex half', 'yes', 'You create a sinuous line of flames that you may shape as desired. The fire snake affects one 5-foot square per caster level, and each square must be adjacent to the previous square, starting with you. The fire snake may not extend beyond its maximum range. Creatures in the path of the fire snake take 1d6 points of fire damage per caster level (maximum 15d6).', 'a snake scale', NULL, false, false),
  ('fire_sneeze', 'Fire Sneeze', 'evocation', NULL, 'air, fire', 2, 'both', 'alchemist 2, druid 2, sorcerer/wizard 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 round + 1 round/2 levels', 'Reflex half', 'yes', 'This spell causes you to begin sneezing gouts of fire that can not only set creatures ablaze but also drop them flat on their backs. Once you cast this spell, you must sneeze each round as a standard action—you can take no other standard action as long as this spell is in effect, nor can you take full-round actions. Each time you sneeze, you produce a 10-foot-long cone of fire and wind. All creatures caught in this cone take 2d6 points of fire damage—a successful Reflex save halves this damage. Any creature that fails to resist this spell with a Reflex save must immediately make a DC 12 Fortitude save or be knocked prone by the blast of wind associated with the sneeze.', 'hot pepper soaked in oil', NULL, false, false),
  ('fire_storm', 'Fire Storm', 'evocation', NULL, 'fire', 7, 'divine', 'cleric/oracle 8, druid 7, shaman 8; Mystery flame 7, volcano 7', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, 'two 10-ft. cubes per level (S)', NULL, 'instantaneous', 'Reflex half', 'yes', 'When a fire storm spell is cast, the whole area is shot through with sheets of roaring flame. The raging flames do not harm natural vegetation, ground cover, or any plant creatures in the area that you wish to exclude from damage. Any other creature within the area takes 1d6 points of fire damage per caster level (maximum 20d6). Creatures that fail their Reflex save catch on fire, taking 4d6 points of fire damage each round until the flames are extinguished. Extinguishing the flames is a full-round action that requires a DC 20 Reflex save.', NULL, NULL, false, false),
  ('fire_trail', 'Fire Trail', 'transmutation', NULL, 'fire', 3, 'arcane', 'alchemist 3, bloodrager 3, magus 3, sorcerer/wizard 3', '1 standard action', 'personal', NULL, NULL, NULL, '1 round/level', 'none', 'yes', 'When you cast this spell, flammable liquid oozes from your pores, dripping onto the ground and spontaneously combusting. The flame does not harm you. During this spell’s duration, each time you leave your space, you create a trail of fire that burns within the spaces you move through for 1 round before it burns out. You can leave up to 60 feet of flame trail each round, assuming you are Small or Medium. If you are larger than Medium, the maximum trail length is reduced based on your size. If you are Large, you can leave a trail up to 30 feet long (and 10 feet wide), and if you are Huge, you can leave a trail up to 15 feet long (and 15 feet wide); even larger casters can only leave a trail up to 10 feet long (and as wide as your space) each round. You choose where to leave a flame trail. Creatures that start their turn adjacent to the flame trail take 1d6 points of fire damage. Creatures that start their turn within the flame trail or that enter an area of flame take a number of points of fire damage equal to 1d6 + 1 per caster level (maximum +10). If a creature moves into an area of the flame trail multiple times in a round, it takes this damage each time it enters the area of the flame trail. Flammable objects in or adjacent to the fire trail catch fire.', NULL, NULL, false, false),
  ('fire_trap', 'Fire Trap', 'abjuration', NULL, 'fire', 2, 'both', 'druid 2, sorcerer/wizard 4; Elemental School fire 4', '10 minutes', 'touch', 'object touched', NULL, NULL, 'permanent until discharged (D)', 'Reflex half; see text', 'yes', 'Fire trap creates a fiery explosion when an intruder opens the item that the trap protects. A fire trap spell can ward any object that can be opened and closed.', 'gold dust worth 25 gp', NULL, false, true),
  ('fire_s_friend', 'Fire’s Friend', 'evocation', NULL, 'fire', 2, 'arcane', 'alchemist 2, bloodrager 2, magus 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level', NULL, NULL, 'You cloak yourself in flames that do not harm you or your carried equipment but damage other creatures and objects. The flames cast light as a torch. Any creature that attacks you with a non-reach melee weapon or that begins its turn engaged in a grapple with you takes 1d6 points of fire damage and must succeed at a Reflex save or catch fire. The creature can negate the damage (and avoid catching fire) with spell resistance.', 'a flame of any size', NULL, false, false),
  ('fireball', 'Fireball', 'evocation', NULL, 'fire', 3, 'arcane', 'bloodrager 3, magus 3, sorcerer/wizard 3; Domain fire 3; Elemental School fire 3; Bloodline efreeti 3; Mystery flame 3', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, '20-ft.-radius spread', NULL, 'instantaneous', 'Reflex half', 'yes', 'A fireball spell generates a searing explosion of flame that detonates with a low roar and deals 1d6 points of fire damage per caster level (maximum 10d6) to every creature within the area. Unattended objects also take this damage. The explosion creates almost no pressure.', 'a ball of bat guano and sulfur', NULL, false, false),
  ('firebelly', 'Firebelly', 'abjuration', NULL, NULL, 1, 'both', 'alchemist 1, cleric/oracle 1, druid 1, paladin 1', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level', 'Reflex half; see text', 'yes; see text', 'A magical fire warms your belly, granting you fire resistance 5 and making your gut hot to the touch (but not enough to damage you or anything else). As a standard action, you can breathe a 15-foot cone of flame that deals 1d4 points of fire damage (Reflex half, SR applies). Each time you use this breath weapon, reduce the remaining duration of the spell by 1 minute.', NULL, NULL, true, false),
  ('firebrand', 'Firebrand', 'transmutation', NULL, 'fire', 7, 'arcane', 'sorcerer/wizard 7; Elemental School fire 7', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 round/level', 'Will negates (harmless), but see below', 'yes (harmless)', 'You mark several allies with a flaming rune. This rune does not cause damage, and sheds light as if it were a torch. While the firebrand burns, any creature it marks is immune to damage from any fire spell you cast. All of the target’s weapons (both natural and manufactured) inflict +1d6 points of fire damage on a hit (this bonus fire damage stacks with any amount of fire damage a creature’s weapons might already inflict). At any point during the spell’s duration, a creature bearing a firebrand can launch a beam of fire at any target within 30 feet as a swift action. This ray requires a ranged touch attack to hit and deals 6d6 points of fire damage. Once a creature uses its firebrand to fire a ray in this manner, the effects of the spell end for that creature.', NULL, NULL, false, false),
  ('firefall', 'Firefall', 'transmutation', NULL, 'fire', 4, 'arcane', 'bloodrager 4, magus 4, sorcerer/wizard 4; Elemental School fire 4', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, NULL, NULL, 'instantaneous', 'Will negates and Reflex negates; see text', 'no', 'Firefall causes a fire to erupt into a geyser of dazzlingly bright liquid flame. The spell uses one fire source, which is immediately extinguished. A fire larger than a 20-foot cube is only partly extinguished. Magical fires are not extinguished, but a creature of the fire subtype used as the source takes 1 point of damage per caster level (no Saving Throw).', 'one fire source', NULL, false, false),
  ('firestream', 'Firestream', 'evocation', NULL, 'fire', 3, 'arcane', 'bloodrager 3, magus 3, sorcerer/wizard 3', '1 standard action', '20 ft.', NULL, '20-ft. line', NULL, 'concentration, up to 1 round/level; see text', 'Reflex half', 'yes', 'A rushing stream of fire sprays from your outstretched hand, dealing 2d6 points of fire damage to every creature in the area. Each round you continue to concentrate on the spell, you can select a new area for it to affect.', NULL, NULL, false, false),
  ('firewalker_s_meditation', 'Firewalker’s Meditation', 'abjuration', NULL, 'meditative', 3, 'both', 'cleric 4, druid 4, paladin 3, shaman 4, wizard 4', '1 hour', 'personal', 'you', NULL, NULL, '24 hours or until discharged', NULL, NULL, 'You focus your mind on blocking out pain, allowing your body to endure punishments that would be otherwise unbearable.', 'soothing incense worth 400 gp', NULL, false, true),
  ('first_world_revisions', 'First World Revisions', 'transmutation', 'polymorph', NULL, 2, 'both', 'alchemist 2, antipaladin 3, cleric 2, medium 2, psychic 2, sorcerer/wizard 3, witch 2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions as ancestral regression, except as noted above and as follows. The wayang loses her darkvision racial trait and gains the low-light vision racial trait in its place. The alignment and personality of the wayang are not affected by the transformation, but the spell conceals her alignment as per undetectable alignment. Unlike ancestral regression, this spell grants the target a +20 bonus on Disguise checks to pass as a gnome; even though the wayang appears as a gnomish analog of herself, the differences between gnomes and wayangs are great enough that she cannot be mistaken for a gnome by other wayangs who know her.', NULL, NULL, false, false),
  ('flame_arrow', 'Flame Arrow', 'transmutation', NULL, 'fire', 3, 'arcane', 'bloodrager 3, magus 3, sorcerer/wizard 3; Elemental School fire 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'fifty projectiles, all of which must be together at the time of casting', NULL, NULL, '10 min./level', 'none', 'no', 'This spell allows you to turn ammunition (such as arrows, crossbow bolts, shuriken, and sling stones) into fiery projectiles. Each piece of ammunition deals an extra 1d6 points of fire damage to any target it hits. A flaming projectile can easily ignite a flammable object or structure, but it won’t ignite a creature it strikes.', 'a drop of oil and a small piece of flint', NULL, false, false),
  ('flame_blade', 'Flame Blade', 'evocation', NULL, 'fire', 2, 'divine', 'druid 2, shaman 2', '1 standard action', '0 ft.', NULL, NULL, 'sword-like beam', '1 min./level (D)', 'none', 'yes', 'A 3-foot-long, blazing beam of red-hot fire springs forth from your hand. You wield this blade-like beam as if it were a scimitar. Attacks with the flame blade are melee touch attacks. The blade deals 1d8 points of fire damage + 1 point per two caster levels (maximum +10). Since the blade is immaterial, your Strength modifier does not apply to the damage. A flame blade can ignite combustible materials such as parchment, straw, dry sticks, and cloth.', NULL, NULL, true, false),
  ('flame_steed', 'Flame Steed', 'conjuration', 'creation', NULL, 3, 'both', 'bloodrager 3, cleric 4, druid 4, paladin 3, shaman 4, witch 4', '10 minutes', '0 ft.', NULL, NULL, 'one quasi-real creature suitable for a mount', '1 hour/level (D)', 'none, see text', 'no', 'You conjure a Large, quasi-real creature made of flame. It functions like phantom steed, except as follows.', NULL, NULL, false, false),
  ('flame_strike', 'Flame Strike', 'evocation', NULL, 'fire', 4, 'divine', 'cleric/oracle 5, druid 4, inquisitor 5, shaman 5; Domain sun 5, war 5; Subdomain arson 7; Bloodline celestial 5', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, 'cylinder (10-ft. radius, 40-ft. high)', NULL, 'instantaneous', 'Reflex half', 'yes', 'A flame strike evokes a vertical column of divine fire. The spell deals 1d6 points of damage per caster level (maximum 15d6). Half the damage is fire damage, but the other half results directly from divine power and is therefore not subject to being reduced by resistance to fire-based attacks.', NULL, NULL, true, false),
  ('flames_of_the_faithful', 'Flames of the Faithful', 'transmutation', NULL, 'fire', 2, 'divine', 'inquisitor 2', '1 standard action', 'touch', NULL, NULL, NULL, '1 round/level', 'Fortitude negates (object, harmless)', 'yes (object, harmless)', 'With a touch, you cause a glowing rune to appear on a single weapon, granting that weapon the flaming property (and allowing it to cause an extra 1d6 points of fire damage on a successful hit). If you are using the judgment class feature, your weapon gains the flaming burst property instead.', NULL, NULL, false, false),
  ('flaming_aura', 'Flaming Aura', 'transmutation', NULL, 'fire', 4, 'both', 'bloodrager 4, cleric 4, magus 4, shaman 4, sorcerer/wizard 4, summoner 4, witch 4', '1 standard action', 'personal', 'you (see text)', NULL, NULL, '1 minute/level', 'none (harmless, see text)', 'no (harmless, see text)', 'The spell allows you channel fire into your very being. If you don’t already have the fire subtype, this spell grants you the fire subtype. If you already have the fire subtype, you instead channel the flames from your being outward, creating a 10-foot-radius aura of fire centered on you. Creatures who enter or end their turns in the aura must succeed at a Fortitude saving throw or take 1d8 points of fire damage.', 'a small piece of charcoal', NULL, true, false),
  ('flaming_sphere', 'Flaming Sphere', 'evocation', NULL, 'fire', 2, 'both', 'bloodrager 2, druid 2, magus 2, sorcerer/wizard 2; Subdomain arson 2; Elemental School fire 2; Mystery solar 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, '5-ft.-diameter sphere', '1 round/level', 'Reflex negates', 'yes', 'A burning globe of fire rolls in whichever direction you point and burns those it strikes. It moves 30 feet per round. As part of this movement, it can ascend or jump up to 30 feet to strike a target. If it enters a space with a creature, it stops moving for the round and deals 3d6 points of fire damage to that creature, though a successful Reflex save negates that damage. A flaming sphere rolls over barriers less than 4 feet tall. It ignites flammable substances it touches and illuminates the same area as a torch would.', 'tallow, brimstone, and powdered iron', NULL, true, false),
  ('flare', 'Flare', 'evocation', NULL, 'light', 0, 'both', 'bard 0, druid 0, magus 0, psychic 0, sorcerer/wizard 0', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'burst of light', 'instantaneous', 'Fortitude negates', 'yes', 'This cantrip creates a burst of light. If you cause the light to burst in front of a single creature, that creature is dazzled for 1 minute unless it makes a successful Fortitude save. Sightless creatures, as well as creatures already dazzled, are not affected by flare.', NULL, NULL, false, false),
  ('flare_burst', 'Flare Burst', 'evocation', NULL, 'light', 1, 'both', 'bard 1, bloodrager 1, druid 1, magus 1, psychic 1, sorcerer/wizard 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, '10-ft.-radius burst of light', 'instantaneous', 'Fortitude negates', 'yes', 'This spell functions as flare, except it affects all creatures in a 10-foot-radius burst from the target point.', NULL, NULL, false, false),
  ('flash_fire', 'Flash Fire', 'transmutation', NULL, NULL, 3, 'arcane', 'sorcerer/wizard 3, witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', '1 firearm', NULL, NULL, 'instantaneous', 'Will negates (object); see text', 'yes (object); see text', 'The firearm fires with a blinding flash, even if the firearm is not currently loaded. Every creature within 15 feet of the creature carrying the weapon must succeed at a Fortitude save or be blinded for 1d4 rounds. The creature carrying the firearm takes a –4 penalty on this saving throw. If the firearm is loaded, the ammunition is wasted.', 'a pinch of powdered fool’s gold', NULL, false, false),
  ('flash_flood', 'Flash Flood', 'conjuration', 'creation', 'water', 6, 'both', 'druid 6, shaman 6, sorcerer/wizard 6', '1 standard action', '60 ft.', NULL, 'cone-shaped burst', NULL, 'instantaneous and 1 round per level; see text', 'Reflex partial, see text', 'no', 'You call forth a fast-moving wave that batters all creatures in its path and leaves the target area flooded. Each creature in the area must succeed at a Reflex save or take 1d6 points of bludgeoning damage per 2 caster levels (maximum 10d6).', 'water-smoothed pebble', NULL, false, false),
  ('flash_forward', 'Flash Forward', 'conjuration', 'teleportation', NULL, 4, 'both', 'alchemist 4, antipaladin 4, bard 4, bloodrager 4, inquisitor 4, magus 4, medium 4, occultist 4, paladin 4, psychic 5, sorcerer/wizard 5', '1 standard action', 'personal', 'you', NULL, NULL, 'instantaneous', 'none (harmless)', 'no', 'You cheat the laws of time and enter into combat before reverting back to your original position. As part of the action to cast the spell, you make a charge attack against an enemy. You make this charge attack normally, accounting for terrain, obstacles, attacks of opportunity, attack rolls, and damage rolls. At the end of your charge action, you instantly teleport back to your original location as a free action. Any damage or conditions dealt by you or to you during this action are real and remain when you return to your original location.', NULL, 'a single gear or bit of clockwork', false, false),
  ('flashfire', 'Flashfire', 'evocation', NULL, 'fire', 3, 'divine', 'druid 3, shaman 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, 'one 5-ft. square/2 levels', NULL, '1 round/level', 'Reflex negates (object) and Fort negates', 'yes (object)', 'You cause flames to spring up in the area of effect. These flames deal 1d6 points of fire damage for every 3 caster levels you have (maximum 5d6) to each creature that enters a burning area or begins its turn in the area; these creatures also catch on fire. A creature that succeeds at a Reflex save negates the damage and avoids catching on fire. the area and all adjacent 5-foot squares are smoky, providing concealment within. You can concentrate as a standard action to ignite one 5-foot square adjacent to a currently burning square. Heavy precipitation (including sleet storm) ends the spell. Strong and severe winds spread each square of flashfire downwind by one square each round, but windstorm-force or stronger winds extinguish the fires.', NULL, NULL, false, false),
  ('fleeting_defect', 'Fleeting Defect', 'transmutation', NULL, NULL, 2, 'arcane', 'bard 2, bloodrager 2, magus 2, sorcerer/wizard 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one solid object that does not have the broken condition, or one construct', NULL, NULL, '1 minute/level (D)', 'Fort negates” (harmless, object); see text', 'no', 'You cause a single object to temporarily gain the broken condition. The target must be a single solid object, regardless of its composition, weighing up to 10 pounds per caster level.', NULL, NULL, false, false),
  ('fleeting_memory', 'Fleeting Memory', 'enchantment', 'compulsion', 'mind-affecting', 2, 'arcane', 'bard 3, mesmerist 2, occultist 3, psychic 3, sorcerer/wizard 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round/level (D)', 'Will partial', 'yes', 'You create a gap in the target’s memory, preventing the target from remembering anything that happens from the moment you cast this spell until the moment its complete duration ends.', NULL, NULL, false, false),
  ('flesh_puppet', 'Flesh Puppet', 'necromancy', NULL, 'evil', 2, 'both', 'antipaladin 2, cleric 3, occultist 3, shaman 3, sorcerer/wizard 4, spiritualist 3, witch 4', '1 round', 'touch', 'one corpse touched', NULL, NULL, 'permanent (D)', 'none', 'no', 'You animate one corpse that has been dead no more than 48 hours. It rises as a zombie that is magically tethered to you and obeys your commands. As noted in animate dead, you can’t control more than 4 HD per caster level worth of undead in total, nor can a single casting create more than 2 HD per caster level.', 'an onyx worth 25 gp and a silken string', NULL, false, true),
  ('flesh_to_ooze', 'Flesh to Ooze', 'transmutation', 'polymorph', NULL, 6, 'arcane', 'sorcerer/wizard 6', '1 standard action', 'close (25 f. + 5 f./2 levels)', '1 creature or see text', NULL, NULL, 'permanent', 'Fortitude negates, Will partial, see text', 'No', 'This functions like baleful polymorph, except the target becomes an ooze. A creature of 3 HD or less becomes a gray ooze, 4–9 HD becomes a gelatinous cube or ochre jelly, and 10+ HD becomes a black pudding. Alternatively, instead of a creature you may target a quantity of inert flesh (such as that created by the stone to flesh spell) of sufficient mass, which becomes an ooze of your choice.', 'alchemical reagents worth 100 gp', NULL, false, true),
  ('flesh_to_stone', 'Flesh to Stone', 'transmutation', NULL, NULL, 6, 'both', 'magus 6, shaman 6, sorcerer/wizard 6, witch 6; Elemental School earth 6', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one creature', NULL, NULL, 'instantaneous', 'Fortitude negates', 'yes', 'The subject, along with all its carried gear, turns into a mindless, inert statue. If the statue resulting from this spell is broken or damaged, the subject (if ever returned to its original state) has similar damage or deformities. The creature is not dead, but it does not seem to be alive either when viewed with spells such as deathwatch.', 'lime, water, and earth', NULL, false, false),
  ('flesh_wall', 'Flesh Wall', 'necromancy', NULL, 'evil', 5, 'both', 'cleric 6, shaman 6, sorcerer/wizard 6, spiritualist 5, summoner 5, witch 6', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'a wall of corpses with an area of up to one 5-ft. square/level (S)', 'concentration + 1 round/level (D)', 'none', 'no', 'You animate corpses, forming them into a wall of joined flesh and limbs. The wall inserts itself into any surrounding nonliving material if its area is sufficient to do so. The wall can’t be created so that it occupies the same space as a creature or another object.', 'one corpse for every 5-ft. square of the wall', NULL, true, false),
  ('fleshcurdle', 'Fleshcurdle', 'transmutation', 'polymorph', NULL, 2, 'arcane', 'sorcerer/wizard 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one living or undead creature', NULL, NULL, '1 round/level', 'Fort negates', 'yes', 'You warp the target creature’s flesh, discoloring it and causing it to become misshapen and impairing its function. When you cast this spell, you must choose one of three types of effects to inflict on the target—movement, attacks, or defense.', 'scrap of pickled flesh', NULL, false, false),
  ('fleshwarping_swarm_drow', 'Fleshwarping Swarm (Drow)', 'conjuration', 'summoning', NULL, 3, 'arcane', 'sorcerer/wizard 3, summoner 3, witch 3 Duration concentration + 2 rounds and 1 hour/level (see text)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions as summon swarm, except that living and undead creatures that fail their saving throw against the swarm’s distraction find that their limbs twist and spasm, as their bodies become susceptible to transmutations. Such creatures take a –4 penalty to Dexterity and on saving throws against transmutation effects for 1 hour per caster level.', NULL, NULL, false, false),
  ('fleshworm_infestation', 'Fleshworm Infestation', 'conjuration', 'summoning', 'evil', 4, 'both', 'cleric/oracle 4, inquisitor 4, sorcerer/wizard 4, witch 4', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 round/level (D)', 'Fortitude partial (see text)', 'yes', 'With a touch, you cause an infestation of ravenous worms to manifest in the target’s flesh. The target must make a Fortitude save every round. Failure means it takes 1d6 hit points of damage and 2 points of Dexterity damage, and is staggered for 1 round. If it makes the save, it takes no hit point or Dexterity damage and is only sickened for 1 round rather than staggered. Fleshworm infestation cannot be ended early by remove disease or heal, as the infestation starts anew if the current worms are slain. Protection from evil negates this spell’s effects for as long as the two durations overlap. Dispel evil automatically ends a fleshworm infestation.', NULL, NULL, false, false),
  ('fleshy_facade', 'Fleshy Facade', 'transmutation', 'polymorph', NULL, 2, 'both', 'alchemist 2, bard 2, inquisitor 2, psychic 2, sorcerer/wizard 2, witch 2', '1 standard action', 'touch', 'corporeal undead creature touched', NULL, NULL, '10 minutes/level (D)', 'yes (harmless)', 'yes (harmless)', 'The target’s flesh fills out and gains a healthy, natural color.', NULL, NULL, false, false),
  ('flexible_fury', 'Flexible Fury', 'transmutation', NULL, NULL, 3, 'arcane', 'bard 3', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level', NULL, NULL, 'You swap one of your current rage powers for another rage power you qualify for. If the rage power granted by this spell has a use limitation (such as once per rage or a number of times per day), any uses of that rage power count toward that limit (including for later castings of this spell).', NULL, NULL, false, false),
  ('flexile_curse', 'Flexile Curse', 'transmutation', NULL, 'curse', 3, 'both', 'bard 3, cleric 5, inquisitor 3, psychic 5, sorcerer/wizard 5, witch 3', '1 standard action', 'touch', 'creature touched', NULL, NULL, 'permanent', 'Will negates', 'yes', 'You curse your target with a withering aura that degrades its armor and shield (if any). This reduces the hardness, armor bonus, and enhancement bonus of any armor or shield worn by the target by 1. For every hour the target wears a suit of armor or a shield, the hardness, armor bonus, and enhancement bonus are reduced by an additional 1. If the armor or shield’s hardness is reduced to 0, anytime the target of the curse is struck while wearing that item, there is a 20% chance that it gains the broken condition. If the enhancement bonus of magic suit of armor or shield is reduced to 0, the armor or shield loses any other special abilities it had.', NULL, NULL, false, false),
  ('flickering_lights', 'Flickering Lights', 'evocation', NULL, 'darkness, light', 2, 'both', 'bard 2, cleric 2, inquisitor 2, magus 2, occultist 2, shaman 2, sorcerer/wizard 2', '1 round', 'medium (100 ft. + 10 ft./level)', NULL, 'contiguous area consisting of one 10-foot cube/level (S)', NULL, '1 round/level', 'Will negates', 'yes', 'You cause the illumination in the area to seem to flicker erratically, fluctuating between absolute darkness and blinding brightness.', 'a patch of white cloth and a patch of black cloth', NULL, false, false),
  ('floating_disk', 'Floating Disk', 'evocation', NULL, 'force', 1, 'arcane', 'magus 1, psychic 1, sorcerer/wizard 1; Subdomain trade 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, '3-ft.-diameter disk of force', '1 hour/level', 'none', 'no', 'You create a slightly concave, circular plane of force that follows you about and carries loads for you. The disk is 3 feet in diameter and 1 inch deep at its center. It can hold 100 pounds of weight per caster level. If used to transport a liquid, its capacity is 2 gallons. The disk floats approximately 3 feet above the ground at all times and remains level. It floats along horizontally within spell range and will accompany you at a rate of no more than your normal speed each round. If not otherwise directed, it maintains a constant interval of 5 feet between itself and you. The disk winks out of existence when the spell duration expires. The disk also winks out if you move beyond its range or try to take the disk more than 3 feet away from the surface beneath it. When the disk winks out, whatever it was supporting falls to the surface beneath it.', 'a drop of mercury', NULL, false, false),
  ('flotsam_vessel', 'Flotsam Vessel', 'conjuration', 'creation', NULL, 1, 'both', 'cleric 2, druid 2, ranger 1, summoner 1', '1 minute', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'raft large enough for caster and one passenger/2 levels', '1 hour/level (D)', 'none', 'no', 'This spell assembles a sturdy raft and oars from driftwood, reeds, and other river detritus. The smallest raft created by the spell is roughly 5 feet square, increasing by an additional 5 feet square for every 2 caster levels you possess. Each 5-foot section of the raft can carry two Medium passengers or 300 pounds of cargo. The vessel functions as a normal raft, except it is not slowed or damaged by non-magical river hazards such as rapids or shallows, and it is always considered to be traveling downstream for the purpose of calculating travel speed, regardless of its actual direction.', 'driftwood branch or river rat’s tail', NULL, false, false),
  ('fluid_form', 'Fluid Form', 'transmutation', NULL, 'water', 4, 'arcane', 'alchemist 4, sorcerer/wizard 6; Subdomain flowing 6, rivers 6; Elemental School water 6; Mystery waves 6', '1 standard action', 'personal', NULL, NULL, NULL, '1 minute/level', NULL, NULL, 'When you cast this spell, your body takes on a slick, oily appearance. For the duration of this spell, your form can stretch and shift with ease and becomes slightly transparent, as if you were composed of liquid. This transparency is not enough to grant concealment. You gain DR 10/slashing and your reach increases by 10 feet. In addition, you can pass through small holes or narrow openings, even mere cracks, with anything you were carrying at the time the spell was cast (except other creatures). Finally, you can move through water with a swim speed of 60 feet and can breathe both water and air for the duration of this effect. You are treated as if you had the water subtype while this spell is in effect.', 'a mixture of oil and water', NULL, false, false),
  ('flurry_of_snowballs', 'Flurry of Snowballs', 'evocation', NULL, 'cold, water', 2, 'both', 'druid 2, magus 2, sorcerer/wizard 2, witch 2', '1 standard action', '30 ft.', NULL, NULL, 'cone-shaped burst', 'instantaneous', 'Reflex half', 'no', 'You send a flurry of snowballs hurtling at your foes.', NULL, NULL, false, false),
  ('fly', 'Fly', 'transmutation', NULL, NULL, 3, 'both', 'alchemist 3, bloodrager 3, magus 3, medium 3, occultist 3, psychic 3, shaman 3, sorcerer/wizard 3, spiritualist 3, summoner/unchained summoner 3, witch 3; Domain travel 3, void 3; Subdomain azata (chaos, good) 3, feather 3; Bloodline djinni 3, draconic 3; Elemental School air 3; Mystery dragon 3', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 min./level', 'Will negates (harmless)', 'yes (harmless)', 'The subject can fly at a speed of 60 feet (or 40 feet if it wears medium or heavy armor, or if it carries a medium or heavy load). It can ascend at half speed and descend at double speed, and its maneuverability is good.', NULL, 'a wing feather', false, false),
  ('fly_mass', 'Fly, Mass', 'transmutation', NULL, NULL, 7, 'arcane', 'sorcerer/wizard 7; Subdomain feather 6; Elemental School air 7', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '10 minutes/level', 'Will negates (harmless)', 'yes (harmless)', 'This spell functions as fly, save that it can target numerous creatures and lasts longer.', NULL, 'a wing feather', false, false),
  ('focused_scrutiny', 'Focused Scrutiny', 'divination', NULL, NULL, 2, 'both', 'alchemist 2, bard 2, inquisitor 2, psychic 2, shaman 2', '1 standard action', 'personal', 'you', NULL, NULL, '10 minutes/level (D)', NULL, NULL, 'You gain heightened sensitivity to the mannerisms, reactions, and body language of one creature you can perceive, allowing you to sense its state of mind and easily influence it. You gain a +10 bonus on Perception, Sense Motive, and Survival checks attempted against the target creature, as well as a +5 bonus on Diplomacy and Intimidate checks attempted against it.', NULL, NULL, false, false),
  ('foe_to_friend', 'Foe to Friend', 'enchantment', 'compulsion', 'mind-affecting', 5, 'arcane', 'bard 5', '1 immediate action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, NULL, '1 round', 'Will negates', 'yes', 'Cast this spell when an enemy is about to make an attack against an ally. The creature makes the attack against a valid target of your choice instead or the attack is negated. In addition, the target is considered an ally for determining flanking for 1 round.', NULL, NULL, false, false),
  ('fog_cloud', 'Fog Cloud', 'conjuration', 'creation', NULL, 2, 'both', 'druid 2, magus 2, shaman 2, sorcerer/wizard 2, unchained summoner 2, witch 2; Domain water 2, weather 2; Elemental School water 2; Mystery battle 2', '1 standard action', 'medium (100 ft. + 10 ft. level)', NULL, NULL, 'fog spreads in 20-ft. radius', '10 min./level', 'none', 'no', 'A bank of fog billows out from the point you designate. The fog obscures all sight, including darkvision, beyond 5 feet. A creature within 5 feet has concealment (attacks have a 20% miss chance). Creatures farther away have total concealment (50% miss chance, and the attacker can’t use sight to locate the target).', NULL, NULL, false, false),
  ('follow_aura', 'Follow Aura', 'divination', NULL, 'chaotic, evil, good, or lawful', 2, 'divine', 'inquisitor 2', '1 standard action', 'personal', NULL, NULL, NULL, '10 minutes/level (D)', NULL, NULL, 'Choose one alignment type: chaotic, evil, good, or lawful. You gain the ability to follow the trail of a strong or overwhelming aura of that alignment (see detect evil). This is treated as tracking using the scent special quality, except you are following the traces of their aura upon the ground rather than their scent, and you receive no bonus on Perception checks. At 10th level, you can track the trail of creatures with a moderate alignment aura as well.', NULL, NULL, true, false),
  ('font_of_spirit_magic', 'Font of Spirit Magic', 'conjuration', 'creation', NULL, 3, 'divine', 'shaman 3', '1 standard action', '30 ft.', NULL, '30-ft.-radius emanation centered on you', NULL, 'concentration + 1 round/level', 'Will negates (harmless)', 'no', 'You amplify the effect of magic associated with your spirit and wandering spirit (any spells on the spirit magic spell lists for these spirits). When allies within the area cast these spells, they gain a +2 bonus on caster level checks and concentration checks, as well as to spell DCs. This bonus is a sacred bonus if you are good-aligned or a profane bonus if you are evil-aligned; if you are neither good nor evil, you can choose what type of bonus the spell grants when you cast it.', 'gold dust worth 50 gp', NULL, false, true),
  ('fool_s_forbiddance', 'Fool’s Forbiddance', 'abjuration', NULL, 'mind-affecting', 6, 'arcane', 'bard 6', '1 standard action', '10 ft.', NULL, '10-ft.-radius spherical emanation centered on you', NULL, 'concentration', 'Will partial', 'yes', 'Through your antics and performance, you create an area of warding that adversely affects all enemies that dare enter it. When an enemy creature enters the area it must make an immediate Will Saving Throw. If it fails, the creature is confused as long as it is in the area and for 1 round after it leaves. If it succeeds on the Saving Throw, the creature is staggered as long as it is in the area and for 1 round after it leaves.', 'a ring of keys', NULL, false, false),
  ('fool_s_gold_vc', 'Fool’s Gold (VC)', 'illusion', NULL, NULL, 1, 'arcane', 'arcanist 1, bard 1, medium 1, mesmerist 1, psychic 1, skald 1, sorcerer/wizard 1', '1 standard action', 'touch', 'objects touched', NULL, NULL, '1 hour/level', 'none or Will disbelief (see text)', 'no', 'You can temporarily make copper or silver seem to be an equivalent amount of gold. The spell affects 1 gp/level worth of material (thus, at 3rd level, the spell affects up to 300 copper pieces, 30 silver pieces, or a copper or silver item worth no more than 3 gp). Coins increase in value as normal for the new type of coinage. For items other than coins, some of the value of the item comes from its craftsmanship, regardless of the metal used, so the value of the item seems to be 5 times (for silver items) or 50 times (for copper items) its true value. Thus, a copper candlestick originally worth 5 cp transformed by this spell appears to be worth 250 cp, or 2 gp and 5 sp. A successful DC 25 Appraise check automatically detects the true nature of the coins or items. Creatures inspecting or interacting with the coins or items can attempt a saving throw to disbelieve the illusion.', 'a copper piece or silver piece', NULL, false, false),
  ('fool_s_teleport', 'Fool’s Teleport', 'illusion', 'glamer', NULL, 3, 'arcane', 'mesmerist 3, psychic 4, sorcerer/wizard 4', '1 standard action', 'personal and touch', 'you and other touched willing creatures', NULL, NULL, '1 minute/level', 'Will negates (harmless); see text', 'no', 'This spell instantly renders you unseen as per invisibility, but creates a visual and auditory display that makes it appear as if you had teleported away. You can affect one additional Medium or smaller creature or its equivalent per 3 caster levels (a Large creature counts as two Medium creatures, a Huge creature counts as four Medium creatures, and so forth). All creatures to be affected must be in contact with one another, and at least one of those creatures must be in contact with you.', NULL, NULL, false, false),
  ('fool_s_gold', 'Fool’s Gold', 'transmutation', NULL, NULL, 1, 'both', 'alchemist 1, antipaladin 1, bard 1, mesmerist 1, occultist 2, psychic 1, shaman 2, sorcerer/wizard 2, witch 2', '1 standard action', 'touch', '1 gold piece/level touched', NULL, NULL, '10 minutes/level', 'Fort negates (object, see text)', 'yes', 'You cast this spell on one or more gold pieces, which make those who have them more vulnerable to your magics. A creature with one or more of these gold pieces in its possession must attempt a Will save (at this spell’s save DC) the first time the creature is forced to attempt a saving throw against a spell, spell-like ability, or supernatural ability you create. If the creature fails, it takes a –2 penalty on all saving throws against your magic effects as long as the gold piece is in its possession. Additionally, if it fails a saving throw against a magic ability of yours that is not harmless and has a duration, the duration is doubled for that creature.', NULL, 'a lump of gold worth 5 gp', false, true),
  ('forbid_action', 'Forbid Action', 'enchantment', 'compulsion', 'language-dependent, mind-affecting', 1, 'both', 'cleric/oracle 1, inquisitor 1, psychic 1', '1 standard actionComponent V', 'close (25 ft. +5 ft./2 levels)', 'one creature', NULL, NULL, '1 round', 'Will negates', 'yes', 'You forbid the target a single course of action, which it avoids to the best of its ability. You may demand the target not take actions that fall into one of the following options.', NULL, NULL, false, false),
  ('forbiddance', 'Forbiddance', 'abjuration', NULL, NULL, 6, 'divine', 'cleric/oracle 6, inquisitor 6', '6 rounds', 'medium (100 ft. + 10 ft./level)', NULL, '60-ft. cube/level (S)', NULL, 'permanent', 'see text', 'yes', 'Forbiddance seals an area against all planar travel into or within it. This includes all teleportation spells (such as dimension door and teleport), plane shifting, astral travel, ethereal travel, and all summoning spells. Such effects simply fail automatically.', 'holy water and incense worth 1,500 gp, plus 1,500 gp per 60-foot cube', NULL, true, true),
  ('force_anchor', 'Force Anchor', 'conjuration', 'creation', 'force', 2, 'both', 'inquisitor 2, magus 2, sorcerer/wizard 3, summoner 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'one anchor of force', '1 round/level', 'none', 'yes', 'You conjure an anchor of pure force that immediately skewers your target on a successful ranged touch attack. If it hits, the attack deals the target 1d4 points of force damage per 2 caster levels (max 5d4) and the anchor becomes firmly lodged in the target’s torso. The anchor has no weight, but its wide flukes prevent the target from moving through any space smaller than the creature’s size. The anchor also prevents incorporeal targets from moving through solid objects. Whenever the target moves through a square occupied by another creature, the square counts as 2 squares for the purpose of calculating movement, even if the square’s occupant is the target’s ally.', 'a twisted nail', NULL, false, false),
  ('force_hook_charge', 'Force Hook Charge', 'evocation', NULL, 'force', 3, 'arcane', 'bloodrager 3, magus 3', '1 standard action', 'close (25 feet + 5 feet/2 levels)', 'one creature or object within range and you', NULL, NULL, 'instantaneous', 'none', 'yes', 'You create a hook of force that strikes the target and drags you to a space adjacent to it. Make a ranged touch attack against the target; if the touch attack succeeds, the target takes 1 point of force damage per caster level. Whether or not the touch attack hits, the force hook drags you in a straight line to a square adjacent to the target. This movement provokes attacks of opportunity as normal. The pulling hook keeps you from falling as part of this movement; therefore you can use it to cross a pit or chasm, or reach a higher or lower elevation. If the line of effect from you to the target passes through an area that is too small to fit your body (such as a portcullis or arrow slit), the hook pulls you to that location and you take damage as if you had fallen the distance from your starting point to that location. If you are restrained, such as being chained to a wall, the hook pulls you to the maximum extent of your restraints but does not break the restraints.', NULL, NULL, false, false),
  ('force_punch', 'Force Punch', 'evocation', NULL, 'force', 3, 'arcane', 'bloodrager 3, magus 3, psychic 3, sorcerer/wizard 3, spiritualist 3; Subdomain fist 4; Mystery ascetic 3', '1 standard action', 'touch', 'creature touched', NULL, NULL, 'instantaneous', 'Fortitude partial', 'yes', 'This spell charges your hand with telekinetic force. Your successful melee touch attack deals 1d4 points of force damage per level (maximum 10d4) and causes the target to be pushed away from you in a straight line up to 5 feet per two caster levels. For every size category of the target above Medium, reduce the distance pushed by 5 feet (–5 feet for Large, –10 feet for Huge, –15 for Gargantuan, and –20 feet for Colossal) to a minimum of 0 feet. A successful Fortitude save negates the movement but not the damage.', NULL, NULL, false, false),
  ('force_sword', 'Force Sword', 'evocation', NULL, 'force', 2, 'arcane', 'bloodrager 2, magus 2, occultist 2, psychic 2, sorcerer/wizard 2, spiritualist 2, witch 2', '1 standard action', '0 ft.', NULL, NULL, 'one sword-shaped weapon of force', '1 minute/level', 'none', 'yes', 'You create a +1 longsword of pure force sized appropriately for you that you can wield or give to another creature like any other longsword. At 8th level, the sword functions as a +2 longsword.', NULL, NULL, false, false),
  ('forcecage', 'Forcecage', 'evocation', NULL, 'force', 7, 'arcane', 'sorcerer/wizard 7', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, 'barred cage (20-ft. cube) or windowless cell (10-ft. cube)', NULL, '1 round/level (D)', 'Reflex negates', 'no', 'This spell creates an immobile, invisible cubical prison composed of either bars of force or solid walls of force (your choice).', 'ruby dust worth 500 gp', NULL, false, true),
  ('forced_mutation', 'Forced Mutation', 'transmutation', NULL, NULL, 3, 'both', 'cleric 3, inquisitor 3, magus 3, occultist 3, sorcerer/wizard 3, witch 3', '1 standard action', 'touch', 'living creature touched', NULL, NULL, '1 round/level', 'Fort negates', 'yes', 'The body of the target creature twists and distorts, reshaping into a grotesque figure. Because of the disfigurement, the creature takes a –4 penalty to Constitution and Charisma. The creature also receives one of the following deformities (your choice) from the list in the mutant acquired template: blind, deaf, fragile, fractured mind, lame, poor ability (applied to your choice of Strength, Dexterity, Intelligence, or Wisdom), spasms, and useless arm. The deformity is subject to all limitations described in the mutant template (for example, this spell cannot impose the lame deformity on a creature with a base speed slower than 20 feet).', 'a small piece of radioactive clay', NULL, false, false),
  ('forced_quiet', 'Forced Quiet', 'transmutation', NULL, 'sonic', 1, 'both', 'bard 1, inquisitor 1, psychic 1, sorcerer/wizard 1, witch 1', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one creature', NULL, NULL, '1 round/level', 'Will negates', 'yes', 'With a gesture, you muffle sound around the target, making it unable to yell or otherwise make loud noises. This does not affect spellcasting by the target. The target can still use sonic effects, but the DC of these effects decreases by 2. The target gains a +2 bonus on saving throws against sonic effects. The target gains a +4 circumstance bonus on Stealth checks.', NULL, NULL, false, false),
  ('forced_repentance', 'Forced Repentance', 'enchantment', 'compulsion', 'emotion, mind-affecting', 4, 'divine', 'inquisitor 4, paladin 4; Subdomain redemption 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 round/level', 'Will negates', 'yes', 'You force an evil creature that does not have the evil subtype to momentarily reflect on its past actions and be overcome by grief and conscience. The target immediately drops prone and begins to loudly confess all of its sins and transgressions to the caster for the duration of the spell. The spell immediately ends if you move out of line of sight or if the target is attacked.', NULL, NULL, true, false),
  ('forceful_hand', 'Forceful Hand', 'evocation', NULL, 'force', 6, 'arcane', 'magus 6, sorcerer/wizard 6; Mystery godclaw 6', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions as interposing hand, except that it can also pursue and bull rush one opponent you select.', NULL, NULL, false, false),
  ('forceful_strike', 'Forceful Strike', 'evocation', NULL, 'force', 4, 'both', 'cleric 4, inquisitor 4, magus 4, paladin 4', '1 swift action', 'touch or reach of melee weapon', '1 creature', NULL, NULL, 'instantaneous', 'Fortitude partial', 'yes', 'You cast this spell as you strike a creature with a melee weapon, unarmed strike, or natural attack to unleash a concussive blast of force. You deal normal weapon damage from the blow, but also deal an additional amount of force damage equal to 1d4 points per caster level (maximum of 10d4). The force of the blow may be enough to knock the target backward as well. To determine if the target is pushed back, make a combat maneuver check with a bonus equal to your caster level to resolve a bull rush attempt against the creature struck. You do not move as a result of this free bull rush, but it can push the target back if it defeats the target’s CMD. A successful Fortitude save halves the force damage and negates the bull rush effect.', NULL, NULL, false, false),
  ('foresight', 'Foresight', 'divination', NULL, NULL, 9, 'both', 'druid 9, shaman 9, sorcerer/wizard 9, witch 9; Domain knowledge 9; Elemental School void 9; Bloodline destined 9', '1 standard action', 'personal or touch', 'see text', NULL, NULL, '10 min./level', 'none or Will negates (harmless)', 'no or yes (harmless)', 'This spell grants you a powerful sixth sense in relation to yourself or another. Once foresight is cast, you receive instantaneous warnings of impending danger or harm to the subject of the spell. You are never surprised or flat-footed. In addition, the spell gives you a general idea of what action you might take to best protect yourself and gives you a +2 insight bonus to AC and on Reflex saves. This insight bonus is lost whenever you would lose a Dexterity bonus to AC.', 'a hummingbird’s feather', NULL, true, false),
  ('forest_friend', 'Forest Friend', 'abjuration: Level druid 2, ranger 2', NULL, NULL, 9, 'arcane', NULL, '1 round', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 minute/level', 'none', 'no', 'While subject to this spell, the targets find that forested areas become helpful instead of hindering. The targets suffer no hindrances to movement and suffer no penalties on Acrobatics and Stealth checks from undergrowth in forested terrain. Furthermore, forested overgrowth imposes a miss chance 10% lower than normal. When moving in and among trees, those subject to the spell gain a +5 circumstance bonus on Acrobatics checks and Climb checks. Rangers in their favored terrain can also add their favored terrain bonus on such Acrobatics and Climb checks.', 'a pinch of manure', NULL, false, false),
  ('forest_s_sense', 'Forest’s Sense', 'divination', 'scrying', NULL, 3, 'divine', 'druid 4, ranger 3, shaman 4', '1 standard action', '1 mile/level', 'one creature', NULL, NULL, '1 minute/level (D); see text', 'Will negates', 'yes', 'You can sense the location of a target creature within range if it is also within 10 feet of a living plant or fungus. You must be able to target the creature by tangible qualities such as its build, clothing texture, size, or tracks, but you need not have line of effect to your target. the fungus or plants near the target serve as a scrying sensor for this spell. Your senses of hearing, smell, and touch extend to all fungus and plants within 10 feet of the target, allowing you to gauge the size and shape of nearby objects and potentially to overhear conversations in which the target is currently participating. Your scent ability and tremorsense extend through this scrying sensor if you have them, but any other special senses you might have do not. For 1 day after casting this spell, you gain a +5 insight bonus on Survival checks to track creatures you sensed via the spell. You can dismiss this bonus on Survival checks.', NULL, NULL, false, false),
  ('foretell_failure', 'Foretell Failure', 'divination', NULL, NULL, 4, 'both', 'bard 4, occultist 5, oracle 4, psychic 4, sorcerer/wizard 5, witch 4', '1 swift action', 'personal', 'you', NULL, NULL, 'instantaneous', NULL, NULL, 'You cast this spell immediately before you would take an action that requires a d20 roll, such as a skill check, attack roll, or ability check. The action must be something you can complete in a single round. The spell magically informs you whether the action will succeed if you roll a 10 or better on the d20 roll involved. If the action would be successful under those circumstances, you must take the action. If the action would not be successful, you can take a different action.', NULL, NULL, false, false),
  ('forgetful_slumber', 'Forgetful Slumber', 'enchantment', 'compulsion', 'mind-affecting', 4, 'arcane', 'bard 4, sorcerer/wizard 4, witch 4', '1 round', 'close (25 ft. + 5 ft./2 levels)', 'one living creature', NULL, NULL, '1 minute/level', 'Will negates', 'yes', 'This spell acts as the deep slumber spell, but only affects one creature of 10 Hit Dice or fewer. In addition, a creature affected by this spell awakens with no knowledge of the events that led to the spell’s casting. The target loses all memory from the 5 minutes prior to falling asleep. No effect short of a miracle or wish can restore memories lost by this spell.', 'a few drops of river water', NULL, false, false),
  ('form_of_the_alien_dragon_i_iii', 'Form of The Alien Dragon I-III', 'transmutation', 'polymorph', NULL, 6, 'arcane', 'alchemist 6, magus 6, psychic 7, sorcerer/wizard 6', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level (D)', 'see text', 'no', 'You become a Medium esoteric or outer dragon.', 'a scale of the dragon type you plan to assume', NULL, false, false),
  ('form_of_the_dragon', 'Form of the Dragon', 'transmutation', 'polymorph', NULL, 6, 'arcane', 'alchemist 6, magus 6, sorcerer/wizard 6; Subdomain dragon 6; Bloodline draconic 6', '1 standard action', 'personal', 'you', NULL, NULL, '1 min./level (D)', 'see below', 'no', 'You become a Medium chromatic or metallic dragon. You gain a +4 size bonus to Strength, a +2 size bonus to Constitution, a +4 natural armor bonus, fly 60 feet (poor), darkvision 60 feet, a breath weapon, and resistance to one element. You also gain one bite (1d8), two claws (1d6), and two wing attacks (1d4). Your breath weapon and resistance depend on the type of dragon. You can only use the breath weapon once per casting of this spell. All breath weapons deal 6d8 points of damage and allow a Reflex save for half damage. In addition, some of the dragon types grant additional abilities, as noted below.', 'a scale of the dragon type you plan to assume', NULL, false, false),
  ('form_of_the_exotic_dragon_i_iii', 'Form of the Exotic Dragon I-III', 'transmutation', 'polymorph', NULL, 6, 'both', 'alchemist 6, druid 7, sorcerer/wizard 6', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level (D)', 'see below', 'no', 'You become a Medium imperial or primal dragon.', 'a scale of the dragon type you plan to assume', NULL, false, false),
  ('form_validation', 'Form Validation', 'divination', NULL, NULL, 1, 'both', 'alchemist 1, inquisitor 1, sorcerer/wizard 1', '1 standard action', 'touch', 'creature touched', NULL, NULL, 'instantaneous', 'none', 'yes (harmless)', 'To cast this spell, you must have a bit of hair, a fingernail clipping, or some other portion of a creature. The sample must be no more than 1 week old per caster level. As part of casting, you touch the target creature, and instantly know whether the target is the same creature the sample is from.', 'a bit of hair, a fingernail, or a similar portion of a creature', NULL, false, false),
  ('fortune_s_path', 'Fortune’s Path', 'divination', NULL, NULL, 2, 'both', 'bard 2, cleric 3, sorcerer/wizard 3', '10 minutes', 'personal', 'you', NULL, NULL, 'instantaneous', NULL, NULL, 'You predict events in your near future. Visions of the foretold events appear in the mirror after you cast this spell. Roll d% and add your caster level (maximum 10) to determine results this spell returns, as listed below.', 'incense worth 50 gp', 'silver mirror worth at least 100 gp', false, true),
  ('foster_hatred', 'Foster Hatred', 'enchantment', 'compulsion', 'emotion', 4, 'both', 'antipaladin 4, inquisitor 5, mesmerist 5, psychic 6, spiritualist 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'any number of living creatures, no two of which can be more than 30 ft. apart', NULL, NULL, '1 hour/level (D)', 'Will negates', 'yes', 'You build upon your targets’ innate prejudice, stoking it from a simmer to the full flame of hatred. Choose a creature type (if you choose humanoid or outsider, you must also choose a subtype).', NULL, NULL, true, false),
  ('fox_s_cunning', 'Fox’s Cunning', 'transmutation', NULL, NULL, 2, 'arcane', 'alchemist 2, bard 2, psychic 2, sorcerer/wizard 2, summoner/unchained summoner 2; Domain [subdomain] Community [education]', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 min./level', 'Will negates (harmless)', 'yes', 'The target becomes smarter. The spell grants a +4 enhancement bonus to Intelligence, adding the usual benefits to Intelligence-based skill checks and other uses of the Intelligence modifier. Wizards (and other spellcasters who rely on Intelligence) affected by this spell do not gain any additional bonus spells for the increased Intelligence, but the save DCs for spells they cast while under this spell’s effect do increase. This spell doesn’t grant extra skill ranks.', 'hairs or dung from a fox', NULL, true, false),
  ('fractions_of_heal_and_harm', 'Fractions of Heal and Harm', 'transmutation', NULL, NULL, 3, 'both', 'arcanist 3, bard 3, bloodrager 3, cleric/oracle 3, crimson assassin 3, skald 3, sorcerer/wizard 3, warpriest 3', '1 swift action', 'personal', 'you', NULL, NULL, 'instantaneous', NULL, NULL, 'This spell channels a portion of the next spell you cast into magic that heals you. The next instantaneous area damage spell of 3rd level or lower that you cast deals only 75% of its damage, but heals you of a number of hit points equal to the remaining 25% of the spell’s damage. For example, if you cast this spell and followed it with a fireball that would normally deal 40 hit points of damage, the fireball instead deals 30 hit points of damage and heals you of 10 hit points of damage. The spell affected by this spell must be cast before the end of your next turn. This spell has no effect on spells that do not deal damage or spells higher than 3rd level. This healing is treated as if you had been affected by a cure or inflict spell (whichever would heal you), and is treated as the same spell level as the area-affecting spell for the purpose of effects that relate to the spell level of cure or inflict spells.', NULL, NULL, false, false),
  ('free_spirit', 'Free Spirit', 'abjuration', NULL, NULL, 3, 'both', 'bard 3, cleric 3, druid 3, medium 3, shaman 3, spiritualist 3, witch 3', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level', NULL, NULL, 'This spell allows you to gain the benefits of a freedom of movement spell and a +4 bonus on saving throws against fear effects. The spell also makes you drunk.', NULL, NULL, false, false),
  ('free_swim', 'Free Swim', 'abjuration', NULL, NULL, 3, 'both', 'alchemist 3, bard 3, cleric 3, druid 3, hunter 3, inquisitor 3, investigator 3, medium 3, mesmerist 3, occultist 3, oracle 3, psychic 3, ranger 3, skald 3, spiritualist 3, warpriest 3', '1 standard action', 'touch', 'creature touched', NULL, NULL, '10 minutes/level', 'Will negates (harmless)', 'yes (harmless)', 'The target can move and attack underwater normally without the usual penalties involved with underwater combat, as if under the effects of freedom of movement. However, the target doesn’t gain any protections against grapple, paralysis, and magical effects that impede movement (such as solid fog, slow, and web).', 'a strip of kelp bound to the target', NULL, true, false),
  ('freedom', 'Freedom', 'abjuration', NULL, NULL, 9, 'arcane', 'sorcerer/wizard 9; Domain liberation 9', '1 standard action', 'close (25 ft. + 5 ft./2 levels) or see text', 'one creature', NULL, NULL, 'instantaneous', 'Will negates (harmless)', 'yes', 'The subject is freed from spells and effects that restrict movement, including binding, entangle, grappling, imprisonment, maze, paralysis, petrification, pinning, sleep, slow, stunning, temporal stasis, and web. To free a creature from imprisonment or maze, you must know its name and background, and you must cast this spell at the spot where it was entombed or banished into the maze.', NULL, NULL, false, false),
  ('freedom_of_movement', 'Freedom of Movement', 'abjuration', NULL, NULL, 4, 'both', 'alchemist 4, bard 4, cleric/oracle 4, druid 4, inquisitor 4, ranger 4; Domain liberation 4, luck 4; Subdomain flowing 4; Bloodline destined 4', '1 standard action', 'personal or touch', 'you or creature touched', NULL, NULL, '10 min./level', 'Will negates (harmless)', 'yes (harmless)', 'This spell enables you or a creature you touch to move and attack normally for the duration of the spell, even under the influence of magic that usually impedes movement, such as paralysis, solid fog, slow, and web. All combat maneuver checks made to grapple the target automatically fail. The subject automatically succeeds on any combat maneuver checks and Escape Artist checks made to escape a grapple or a pin.', 'a leather strip bound to the target', NULL, true, false),
  ('freedom_s_toast', 'Freedom’s Toast', 'conjuration', 'teleportation', NULL, 4, 'both', 'bard 5, cleric/oracle 5, inquisitor 5, sorcerer/wizard 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'instantaneous', 'Will negates (harmless)', 'yes (harmless)', 'When the caster hoists a flagon and delivers a toast to freedom, the target is transported up to 15 feet from its position to a space of your choice, though that space must be within your line of sight. If the target was prone at the time of casting, you can choose for the target to be standing upon reaching the destination. Furthermore, if the target was bound with non-magical ropes, manacles, or other restraints, those restraints are not transported with the target, effectively freeing the target from those restraints. If the target is bound by magical restraints, you can bar those restraints from being transported with the target with a successful caster level check against a DC based on the restraints’ caster level (DC = 11 + the restraining magic item’s or spell’s caster level).', 'a small amount of ale in a flagon', NULL, true, false),
  ('freezing_sphere', 'Freezing Sphere', 'evocation', NULL, 'cold', 6, 'arcane', 'magus 6, sorcerer/wizard 6; Subdomain ice 7; Elemental School water 6', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, 'see text', NULL, 'instantaneous or 1 round/level; see text', 'Reflex half; see text', 'yes', 'Freezing sphere creates a frigid globe of cold energy that streaks from your fingertips to the location you select, where it explodes in a 40-foot-radius burst, dealing 1d6 points of cold damage per caster level (maximum 15d6) to each creature in the area. A creature of the water subtype instead takes 1d8 points of cold damage per caster level (maximum 15d8) and is staggered for 1d4 rounds.', NULL, 'a small crystal sphere', false, false),
  ('frightful_aspect', 'Frightful Aspect', 'transmutation', 'polymorph', NULL, 8, 'both', 'cleric 8, druid 8, sorcerer/wizard 8, witch 8, Mystery ascetic 8', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level', NULL, NULL, 'You become a larger, awful version of yourself. You grow to size Large, and take on features that horrify your enemies. You gain the following abilities: a +6 size bonus to Strength, a +4 size bonus to Constitution, a +6 natural armor bonus, DR 10/magic, and spell resistance equal to 10 + half your caster level. You also emit an aura that emanates 30 feet from you. Enemy creatures within the aura are shaken. Each time a creature shaken by this aura hits you with a melee attack, that creature becomes frightened for 1d4 rounds, though at the end of that duration it is no longer affected by this aura. The aura’s effect is a fear and mind-affecting effect.', 'the skin of a toad', NULL, false, false),
  ('frigid_souls', 'Frigid Souls', 'necromancy', 'haunted', 'cold, emotion, fear, mind-affecting', 3, 'both', 'cleric 4, druid 4, ranger 3, shaman 4, sorcerer/wizard 4, witch 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, 'one 5-ft. cube/level (S)', NULL, '1 hour/level (D)', 'Will negates', 'yes', 'You harness fear of frozen environments into a haunt that withers defenses against the cold. Any creature that enters the affected area must succeed at a Will save or gain spell resistance equal to 11 + your caster level against any abjuration effect that provides resistance to or protection against cold damage or cold climates. This spell resistance cannot be voluntarily lowered. Once every 30 minutes as an immediate action, the haunt attempts a dispel check (1d20 + your caster level) against an active abjuration effect currently protecting a creature in the affected area against cold, even if it was active before the creature was haunted or it successfully bypassed the spell resistance imposed by the haunt. Against creatures with multiple layers of protection, these dispel checks start with the highest-level abjuration effects and work their way down the list. Each time the haunt attempts a dispel check, the spell’s haunt-like manifestation occurs during that round.', NULL, NULL, true, false),
  ('frigid_touch', 'Frigid Touch', 'evocation', NULL, 'cold', 2, 'both', 'bloodrager 2, druid 2, magus 2, sorcerer/wizard 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, 'instantaneous', 'none', 'yes', 'This spell causes your hand to glow with a pale blue radiance.', NULL, NULL, false, false),
  ('frost_fall', 'Frost Fall', 'evocation', NULL, 'cold', 2, 'both', 'druid 2, sorcerer/wizard 2, witch 2; Mystery winter 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, '5-foot radius burst', NULL, '1 round/2 levels', 'Fortitude partial', 'yes', 'The area of this spell is covered in chilling frost, dealing 2d6 points of cold damage to all creatures within it. Creatures that the spell initially damages must succeed at a Fortitude save or become staggered for 1 round. The area remains chilled for the spell’s duration. Any creature that starts your turn within the spell’s area takes 1d6 points of cold damage (Fortitude saving throw for half) but does not become staggered even on a failed saving throw.', NULL, NULL, false, false),
  ('frost_mammoth', 'Frost Mammoth', 'conjuration', 'creation', 'cold', 6, 'both', 'cleric 7, druid 7, shaman 7, sorcerer/wizard 7, summoner 6', '1 round', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'one frost mammoth', '1 round/level (D)', 'none', 'no', 'A blast of snow suddenly fills an area with a space of 15 feet, immediately taking the shape of a woolly mammoth made of snow with tusks of solid ice. The mammoth has statistics identical to those of a mastodon, except it also has the cold subtype (and thus gains immunity to cold and vulnerability to fire). The frost mammoth obeys your telepathic commands. It allows you or anyone you designate to ride it, and it is treated as if combat trained. At 17th level, a frost mammoth you conjure deals an additional 1d6 points of cold damage with each physical attack.', 'a fragment of mammoth tusk', NULL, false, false),
  ('frostbite', 'Frostbite', 'transmutation', NULL, 'cold', 1, 'both', 'bloodrager 1, druid 1, magus 1, shaman 1, witch 1', '1 standard action', 'touch', NULL, NULL, NULL, 'instantaneous', 'none', 'yes', 'Your melee touch attack deals 1d6 points of nonlethal cold damage + 1 point per level, and the target is fatigued. The fatigued condition ends when the target recovers from the nonlethal damage. This spell cannot make a creature exhausted even if it is already fatigued. You can use this melee touch attack up to one time per level.', NULL, NULL, false, false),
  ('frosty_aura', 'Frosty Aura', 'transmutation', NULL, 'cold', 4, 'both', 'bloodrager 4, cleric 4, magus 4, shaman 4, sorcerer/wizard 4, summoner 4, witch 4', '1 standard action', 'personal', 'you (see text)', NULL, NULL, '1 minute/level', 'none (harmless, see text)', 'no (harmless, see text)', 'The spell allows you to channel cold into your very being. If you don’t already have the cold subtype, this spell grants you the cold subtype. If you already have the cold subtype, you instead channel the frost from your being outward, creating a 10-foot-radius aura of cold centered on you. Creatures who enter or end their turns in the aura must succeed at a Fortitude saving throw or take 1d8 points of cold damage.', 'a chunk of ice or a few drops of water melted from glacier ice', NULL, true, false),
  ('frozen_note', 'Frozen Note', 'enchantment', 'compulsion', 'mind-affecting, sonic', 5, 'arcane', 'bard 5', '1 standard action', NULL, NULL, '30-ft.-radius emanation centered on you Targets any number of creatures within area', NULL, 'concentration (up to 1 round/level); see text', 'Will partial; see text', 'yes', 'You produce and sustain a single perfect musical note that holds nearby creatures, friend as well as foe, utterly spellbound until you stop singing. Affected creatures are both paralyzed and oblivious to their surroundings so long as you maintain the note.', NULL, NULL, false, false),
  ('full_pouch', 'Full Pouch', 'transmutation', NULL, NULL, 2, 'both', 'alchemist 2, bard 2, druid 2, inquisitor 3, occultist 3, ranger 3, sorcerer/wizard 2', '1 swift action', 'touch', '1 object touched', NULL, NULL, 'instantaneous', 'Fort negates (object)', 'no', 'You cast this spell as you draw out a consumable alchemical item to use. The object must be an alchemical item, but not a dose of disease, a poison, a magic potion, or another type of consumable item. The item divides itself into two nearly identical copies and the newly separated one is delivered into your hand. The new item functions as the original in all ways except the copied item suffers a slight reduction in quality. Saves against the new alchemical item’s affects use the original item’s save DC or the save DC of this spell, whichever is higher.', 'alchemical reagents or herbs worth 1 gp', NULL, false, true),
  ('fumblestep', 'Fumblestep', 'conjuration', NULL, NULL, 1, 'arcane', 'mesmerist 1, sorcerer/wizard 1, spiritualist 1, witch 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 minute/level or until discharged (see text)', 'none (see text)', 'yes', 'Fumblestep coats a target’s feet in slick ectoplasm that retains some psychic connection to your mind. While the spell remains in effect, the target creature takes a –1 penalty on Reflex saving throws and Acrobatics checks.', 'a sharp pebble', NULL, false, false),
  ('fumbletongue', 'Fumbletongue', 'enchantment', 'compulsion', 'mind-affecting', 1, 'arcane', 'bard 1, psychic 1, witch 1; Mystery lunar 1', '1 standard action', 'close (25 ft. +5 ft./2 levels)', 'one creature', NULL, NULL, '1d4 rounds', 'Will negates', 'yes', 'This enchantment causes a creature to be unable to speak intelligibly. Any effort the target makes to talk, in any language, comes out as a useless mix of unconnected words and noises. Even magic words are affected to some extent; the target has a 20% spell failure chance for any spell it attempts to cast with verbal components, and a 20% chance to incorrectly use a command word to activate a magic item. This spell has no effect on telepathic communication, or the vocalizations of creatures that lack a spoken language.', NULL, NULL, false, false),
  ('funereal_weapon', 'Funereal Weapon', 'transmutation', NULL, NULL, 1, 'divine', 'cleric 1, inquisitor 1, occultist 1, paladin 1', '1 standard action', 'touch', 'weapon touched or 50 projectiles (all of which must be together at the time of casting)', NULL, NULL, '1 minute/level', 'Will negates (harmless, object)', 'yes (harmless, object)', 'You imbue a weapon with a faint silvery glow that dimly illuminates a 5-foot square. An affected weapon also easily bypasses the physical defenses of undead creatures, ignoring 5 points of an undead creature’s damage reduction, as long as the damage reduction is not DR/epic. For example, attacks with a weapon affected by this spell completely ignore a zombie’s DR 5/slashing or reduce a lich’s damage reduction to DR 10/bludgeoning and magic.', NULL, NULL, true, false),
  ('fungal_blisters', 'Fungal Blisters', 'transmutation', NULL, NULL, 2, 'both', 'alchemist 2, druid 2, sorcerer/wizard 2, witch 2', '1 standard action', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'When you cast this spell, horrible, fungal growths sprout forth all over your body. You develop 1d2+1 of these blisters per 2 caster levels. Each time you are dealt more than 5 points of bludgeoning, piercing, or slashing damage from a single attack, one of these blisters bursts, releasing a cloud of harmful spores in a 5-foot-radius burst centered on you.', NULL, NULL, false, false),
  ('fungal_infestation', 'Fungal Infestation', 'necromancy', NULL, 'disease', 3, 'divine', 'druid 3', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1d3 days', 'Fortitude negates', 'yes', 'You coat the target in necrotic fungus that makes its flesh soft and fragile. Toadstools, ringworm, and other disgusting fungal growths sprout from its skin. The target takes 1d3 points of Charisma damage. Any physical attack against the target automatically adds 1d6 points of bleed damage.', NULL, NULL, false, false),
  ('furious_fire_barrage', 'Furious Fire Barrage', 'evocation', NULL, 'fire', 4, 'arcane', 'bloodrager 4, magus 5, sorcerer/wizard 6', '1 standard action', 'personal', NULL, NULL, NULL, '1 round/level; see text', 'Reflex half', 'yes', 'Upon casting this spell, you conjure forth one or two balls of flame, each resting in a free hand. As part of casting this spell or as a standard action, you can throw one flame ball a maximum of 300 feet, dealing 1d6 points of fire damage per caster level you have (maximum 10d6) to all creatures within a 10-foot-radius spread.', 'two balls of guano', NULL, false, false),
  ('fury_of_the_sun', 'Fury of the Sun', 'transmutation', NULL, 'curse, fire', 2, 'both', 'druid 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '10 minutes/level', 'Fort negates', 'yes', 'You curse the target to suffer unbearable heat. On a failed saving throw, the target is immediately subjected to severe heat, takes 1d4 points of nonlethal damage, and is suffering from heatstroke (fatigued). The target must save every 10 minutes as normal for severe heat (starting at DC 15 rather than the DC of this spell). Because this heat is internal, the target cannot avoid it using the normal methods for escaping heat dangers such as Survival checks or finding shade.', NULL, NULL, false, false),
  ('gallant_inspiration', 'Gallant Inspiration', 'divination', NULL, NULL, 2, 'arcane', 'bard 2', '1 immediate action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, 'instantaneous', 'Will negates (harmless)', 'yes', 'This word of arcane-empowered inspiration often ensures success of a crucial endeavor. Cast this spell when a creature fails an attack roll or skill check. The creature gains a +2d4 competence bonus to the attack roll or skill check retroactively.', NULL, NULL, false, false),
  ('garden_of_peril', 'Garden of Peril', 'conjuration', 'creation', 'poison', 2, 'both', 'druid 2, ranger 2, sorcerer/wizard 2, summoner 2, witch 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'one poisonous mushroom/level, no two of which can be more than 30 ft. apart', '1 round/level (D)', 'Fort negates', 'no', 'Vividly colored poisonous mushrooms instantly spring into existence in squares you select. The mushrooms can appear on any solid surface, even growing horizontally from walls or upside down from the ceiling.', 'a pinch of spores', NULL, true, false),
  ('garrulous_grin', 'Garrulous Grin', 'necromancy', NULL, 'fear, mind-affecting', 2, 'both', 'antipaladin 2, bard 2, inquisitor 2, mesmerist 2, psychic 2, shaman 2, spiritualist 2, witch 3', '1 round', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 hour/level (D)', 'Will negates', 'yes', 'This spell plants a seed of supernatural fear deep in a subject’s mind, causing self-doubt, stuttering, and evasiveness.', NULL, NULL, false, false),
  ('gaseous_form', 'Gaseous Form', 'transmutation', NULL, NULL, 3, 'arcane', 'alchemist 3, bard 3, magus 3, medium 3, occultist 3, psychic 3, sorcerer/wizard 3, spiritualist 3; Domain air 3; Elemental School air 3', '1 standard action', 'touch', 'willing corporeal creature touched', NULL, NULL, '2 min./level (D)', 'none', 'no', 'The subject and all its gear become insubstantial, misty, and translucent. Its material armor (including natural armor) becomes worthless, though its size, Dexterity, deflection bonuses, and armor bonuses from force effects still apply. The subject gains DR 10/magic and becomes immune to poison, sneak attacks, and critical hits. It can’t attack or cast spells with verbal, somatic, material, or focus components while in gaseous form. This does not rule out the use of certain spells that the subject may have prepared using the feats Silent Spell, Still Spell, and Eschew Materials. The subject also loses supernatural abilities while in gaseous form. If it has a touch spell ready to use, that spell is discharged harmlessly when the gaseous form spell takes effect.', 'a bit of gauze and a wisp of smoke', NULL, true, false),
  ('gate', 'Gate', 'conjuration', 'creation or calling', NULL, 9, 'both', 'cleric/oracle 9, sorcerer/wizard 9; Domain glory 9; Subdomain trade 9; Bloodline celestial 9; Elemental School air 9, earth 9, fire 9, water 9', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'see text', 'instantaneous or concentration (up to 1 round/level); see text', 'none', 'no', 'Casting a gate spell has two effects.', 'see text', NULL, false, false)
